import tempfile, pathlib, sqlite3
def prep(content, extra=None):
    tmp=tempfile.mkdtemp()
    pathlib.Path(tmp+"/atlas.hcl").write_text(content)
    con=sqlite3.connect(pathlib.Path(tmp)/"test.db"); con.execute("CREATE TABLE t (id integer)"); con.commit(); con.close()
    pathlib.Path(tmp+"/schema.hcl").write_text('table "users" {
 schema = schema.main
 column "id" {
 type = integer
 }
}
schema "main" {
}
')
