import hashlib, base64, itertools
def b64(d): return base64.b64encode(d).decode()
cases=[
 ([("20240101000000.sql", b"")], "uQrMexCPmPG5WdLqSMostjk431qfkG9ffC6LbrbE7hA=", ["59CojHdB7BjmbwKE4NGbbTsJSWJ0chu39LmueryIxxg="]),
 ([("20240101000000_a.sql", b"hello"),("20240102000000_b.sql", b"world")], "uphO3lZMhdaigiy02s8mlexC/mUGoCoX4dd/Do8+0O0=", ["JhP/4E49zPNKwZPywWhZCzfA4aArZZ6xE7GXk4J+OtY=","2qxPdrRR4hoeHsZAgNjle+frRGJA8NSvA2IwLp697kg="]),
]

def candidates(files):
    # generate mapping name -> generator function returning bytes to hash for overall
    variants={}
    # 1 sumfile lines
    def gen_sumlines(per_hashes):
        return "".join(f"{name} h1:{ph}\n" for (name,_),ph in zip(sorted(files), per_hashes)).encode()
    variants['sumlines']=gen_sumlines
    return variants

for files, expected, per_hashes in cases:
    print("case expected", expected)
    # try sumlines
    data="".join(f"{name} h1:{ph}\n" for (name,_),ph in zip(sorted(files), per_hashes)).encode()
    print(" sumlines sha", b64(hashlib.sha256(data).digest()))
    # try without newline at end, etc
    for label, d in [
        ("sumlines_no_final_nl", data.rstrip(b"\n")),
        ("perhashes_concat_b64", "".join(per_hashes).encode()),
        ("perhashes_concat_raw", b"".join(base64.b64decode(ph) for ph in per_hashes)),
        ("names+contents", b"".join(name.encode()+c for name,c in sorted(files))),
    ]:
        print(" ",label, b64(hashlib.sha256(d).digest()))
    # brute line formats using different tokens
    tokens={}
    # individual, cumulative, content
    indiv=[hashlib.sha256(name.encode()+c).digest() for name,c in sorted(files)]
    content=[hashlib.sha256(c).digest() for name,c in sorted(files)]
    cum=[]; h=hashlib.sha256()
    for name,c in sorted(files):
        h.update(name.encode()); h.update(c); cum.append(h.digest().copy() if hasattr(h.digest(),'copy') else bytes(h.digest()))
        # actually h.digest doesn't mutate, so cum is snapshot? hashlib digest is snapshot
    # correct cum list above ok because each iteration we appended digest snapshot
    per_b64=[base64.b64decode(x) for x in per_hashes] # equals cum presumably
    tokens['indiv']=indiv; tokens['content']=content; tokens['cum']=cum
    found=False
    for tname, toks in tokens.items():
        for rep in ['hex','b64','raw']:
            reps=[]
            for t in toks:
                if rep=='hex': reps.append(t.hex().encode())
                elif rep=='b64': reps.append(base64.b64encode(t))
                else: reps.append(t)
            for fmt in ["{r}  {n}\n","{r} {n}\n","{n} {r}\n","{n}  {r}\n","{r}\n","{n}{r}\n","{r}{n}\n","{n} h1:{r}\n"]:
                if rep=='raw' and '{r}' in fmt:
                    # build bytes manually
                    parts=[]
                    for (name,_),r in zip(sorted(files), reps):
                        # fmt textual not work for raw; skip complex
                        pass
                    continue
                data="".join(fmt.format(r=reps[i].decode() if isinstance(reps[i],bytes) else reps[i], n=sorted(files)[i][0]) for i in range(len(files))).encode()
                if b64(hashlib.sha256(data).digest())==expected:
                    print(" FOUND", tname, rep, fmt); found=True
    print(" done")
