from run import run
import tempfile, pathlib, sqlite3, json
def inspect_json(sqls):
    tmp=tempfile.mkdtemp(); db=pathlib.Path(tmp)/"t.db"
    con=sqlite3.connect(db)
    for s in sqls:
        try: con.execute(s)
        except Exception as e: print("sql err",e)
    con.commit(); con.close()
    p=run(["schema","inspect","-u","sqlite://t.db","--format","{{ json . }}"], cwd=tmp)
    try:
        print(json.dumps(json.loads(p.stdout), indent=2))
    except: print(p.stdout, p.stderr)

