package cmdlog

import (
	"context"
	"encoding/json"

	"atlas/migrate"
	"atlas/schema"
	"atlas/sqlclient"
)

type Env struct {
	Driver string
	URL    *sqlclient.URL
	Dir    string `json:"Dir,omitempty"`
}

type Changes struct {
	Applied []*migrate.Change
	Pending []*migrate.Change
	Error   error `json:"-"`
}

type SchemaInspect struct {
	ctx    context.Context
	client *sqlclient.Client
	URL    string
	Realm  *schema.Realm
}

func NewSchemaInspect(client *sqlclient.Client, url string, realm *schema.Realm) *SchemaInspect {
	return &SchemaInspect{ctx: context.Background(), client: client, URL: url, Realm: realm}
}
func (s *SchemaInspect) Client() *sqlclient.Client { return s.client }

func (s *SchemaInspect) MarshalJSON() ([]byte, error) {
	return json.Marshal(RealmJSON(s.Realm))
}

// Realm JSON representation (Atlas schema JSON).
type realmJSON struct {
	Schemas []*schemaJSON `json:"schemas,omitempty"`
}
type schemaJSON struct {
	Name   string       `json:"name"`
	Tables []*tableJSON `json:"tables,omitempty"`
}
