{"command":"cat > hcl.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

// ---------- Diagnostics ----------

type hclRange struct {
	Filename           string
	StartLine, StartCol int
	EndLine, EndCol     int
}

func (r hclRange) String() string {
	if r.Filename == "" && r.StartLine == 0 {
		return "<nil>"
	}
	fn := r.Filename
	if fn == "" {
		fn = "<nil>"
	}
	if r.EndLine != 0 && r.EndLine != r.StartLine {
		return fmt.Sprintf("%s:%d,%d-%d,%d", fn, r.StartLine, r.StartCol, r.EndLine, r.EndCol)
	}
	return fmt.Sprintf("%s:%d,%d-%d", fn, r.StartLine, r.StartCol, r.EndCol)
}

type hclDiag struct {
	Range   hclRange
	Summary string
	Detail  string
}

func (d *hclDiag) Error() string {
	if d.Detail == "" {
		return fmt.Sprintf("%s: %s", d.Range.String(), d.Summary)
	}
	return fmt.Sprintf("%s: %s; %s", d.Range.String(), d.Summary, d.Detail)
}

type hclDiags []*hclDiag

func (ds hclDiags) Error() string {
	if len(ds) == 0 {
		return ""
	}
	if len(ds) == 1 {
		return ds[0].Error()
	}
	return fmt.Sprintf("%s, and %d other diagnostic(s)", ds[0].Error(), len(ds)-1)
}

func diagAt(filename string, startLine, startCol, endLine, endCol int, summary, detail string) *hclDiag {
	return &hclDiag{Range: hclRange{Filename: filename, StartLine: startLine, StartCol: startCol, EndLine: endLine, EndCol: endCol}, Summary: summary, Detail: detail}
}

// ---------- Tokens ----------

type tokKind int

const (
	tEOF tokKind = iota
	tIdent
	tString
	tNumber
	tOBrace
	tCBrace
	tOBrack
	tCBrack
	tOParen
	tCParen
	tAssign
	tDot
	tComma
	tColon
	tQuestion
	tEq
	tNeq
	tLt
	tLte
	tGt
	tGte
	tAnd
	tOr
	tNot
	tPlus
	tMinus
	tStar
	tSlash
	tPercent
	tEllipsis
	tArrow // => (fat arrow)
	tInvalid
)

type token struct {
	kind                    tokKind
	text                    string // raw text
	strVal                  string // decoded literal for strings without interpolation (or full)
	parts                   []strPart
	line, col               int
	endLine, endCol         int
	offset, endOffset       int
}

type strPart struct {
	isExpr bool
	lit    string
	exprSrc string
	// position of expression inside the string (1-based line/col of first char)
	line, col int
}

type lexer struct {
	src      string
	filename string
	pos      int
	line     int
	col      int
	diags    hclDiags
}

func (l *lexer) err(startLine, startCol, endLine, endCol int, summary, detail string) {
	l.diags = append(l.diags, diagAt(l.filename, startLine, startCol, endLine, endCol, summary, detail))
}

func (l *lexer) eof() bool { return l.pos >= len(l.src) }
func (l *lexer) peek() byte {
	if l.eof() {
		return 0
	}
	return l.src[l.pos]
}
func (l *lexer) peekAt(n int) byte {
	if l.pos+n >= len(l.src) {
		return 0
	}
	return l.src[l.pos+n]
}
func (l *lexer) advance() byte {
	if l.eof() {
		return 0
	}
	c := l.src[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return c
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func lexHCL(src, filename string) ([]token, hclDiags) {
	l := &lexer{src: src, filename: filename, line: 1, col: 1}
	var toks []token
	for !l.eof() {
		c := l.peek()
		// whitespace
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			l.advance()
			continue
		}
		// comments
		if c == '#' || (c == '/' && l.peekAt(1) == '/') {
			for !l.eof() && l.peek() != '\n' {
				l.advance()
			}
			continue
		}
		if c == '/' && l.peekAt(1) == '*' {
			l.advance()
			l.advance()
			for !l.eof() && !(l.peek() == '*' && l.peekAt(1) == '/') {
				l.advance()
			}
			if !l.eof() {
				l.advance()
				l.advance()
			}
			continue
		}
		startLine, startCol, startPos := l.line, l.col, l.pos
		mk := func(k tokKind, text string) token {
			return token{kind: k, text: text, line: startLine, col: startCol, endLine: l.line, endCol: l.col, offset: startPos, endOffset: l.pos}
		}
		switch {
		case isIdentStart(c):
			for !l.eof() && isIdentChar(l.peek()) {
				l.advance()
			}
			toks = append(toks, mk(tIdent, l.src[startPos:l.pos]))
		case isDigit(c):
			for !l.eof() && (isDigit(l.peek()) || l.peek() == '.') {
				// avoid consuming a trailing dot not followed by digit (member access)
				if l.peek() == '.' && !isDigit(l.peekAt(1)) {
					goto numdone
				}
				l.advance()
			}
		numdone:
			if !l.eof() && (l.peek() == 'e' || l.peek() == 'E') {
				savePos, saveLine, saveCol := l.pos, l.line, l.col
				l.advance()
				if !l.eof() && (l.peek() == '+' || l.peek() == '-') {
					l.advance()
				}
				if !l.eof() && isDigit(l.peek()) {
					for !l.eof() && isDigit(l.peek()) {
						l.advance()
					}
				} else {
					l.pos, l.line, l.col = savePos, saveLine, saveCol
				}
			}
			toks = append(toks, mk(tNumber, l.src[startPos:l.pos]))
		case c == '"':
			tok := l.lexString()
			toks = append(toks, tok)
		case c == '<' && l.peekAt(1) == '<':
			// heredoc
			if tok, ok := l.lexHeredoc(); ok {
				toks = append(toks, tok)
			} else {
				// fallback: treat as invalid chars
				l.advance()
				l.err(startLine, startCol, l.line, l.col, "Invalid character", "This character is not used within the language.")
				toks = append(toks, mk(tInvalid, "<"))
			}
		case c == '{':
			l.advance()
			toks = append(toks, mk(tOBrace, "{"))
		case c == '}':
			l.advance()
			toks = append(toks, mk(tCBrace, "}"))
		case c == '[':
			l.advance()
			toks = append(toks, mk(tOBrack, "["))
		case c == ']':
			l.advance()
			toks = append(toks, mk(tCBrack, "]"))
		case c == '(':
			l.advance()
			toks = append(toks, mk(tOParen, "("))
		case c == ')':
			l.advance()
			toks = append(toks, mk(tCParen, ")"))
		case c == '=':
			l.advance()
			if l.peek() == '=' {
				l.advance()
				toks = append(toks, mk(tEq, "=="))
			} else if l.peek() == '>' {
				l.advance()
				toks = append(toks, mk(tArrow, "=>"))
			} else {
				toks = append(toks, mk(tAssign, "="))
			}
		case c == '!':
			l.advance()
			if l.peek() == '=' {
				l.advance()
				toks = append(toks, mk(tNeq, "!="))
			} else {
				toks = append(toks, mk(tNot, "!"))
			}
		case c == '<':
			l.advance()
			if l.peek() == '=' {
				l.advance()
				toks = append(toks, mk(tLte, "<="))
			} else {
				toks = append(toks, mk(tLt, "<"))
			}
		case c == '>':
			l.advance()
			if l.peek() == '=' {
				l.advance()
				toks = append(toks, mk(tGte, ">="))
			} else {
				toks = append(toks, mk(tGt, ">"))
			}
		case c == '&':
			l.advance()
			if l.peek() == '&' {
				l.advance()
				toks = append(toks, mk(tAnd, "&&"))
			} else {
				l.err(startLine, startCol, l.line, l.col, "Invalid character", "This character is not used within the language.")
				toks = append(toks, mk(tInvalid, "&"))
			}
		case c == '|':
			l.advance()
			if l.peek() == '|' {
				l.advance()
				toks = append(toks, mk(tOr, "||"))
			} else {
				l.err(startLine, startCol, l.line, l.col, "Invalid character", "This character is not used within the language.")
				toks = append(toks, mk(tInvalid, "|"))
			}
		case c == '.':
			if l.peekAt(1) == '.' && l.peekAt(2) == '.' {
				l.advance()
				l.advance()
				l.advance()
				toks = append(toks, mk(tEllipsis, "..."))
			} else {
				l.advance()
				toks = append(toks, mk(tDot, "."))
			}
		case c == ',':
			l.advance()
			toks = append(toks, mk(tComma, ","))
		case c == ':':
			l.advance()
			toks = append(toks, mk(tColon, ":"))
		case c == '?':
			l.advance()
			toks = append(toks, mk(tQuestion, "?"))
		case c == '+':
			l.advance()
			toks = append(toks, mk(tPlus, "+"))
		case c == '-':
			l.advance()
			toks = append(toks, mk(tMinus, "-"))
		case c == '*':
			l.advance()
			toks = append(toks, mk(tStar, "*"))
		case c == '/':
			l.advance()
			toks = append(toks, mk(tSlash, "/"))
		case c == '%':
			l.advance()
			toks = append(toks, mk(tPercent, "%"))
		case c == ';':
			l.advance()
			l.err(startLine, startCol, l.line, l.col, "Invalid character", "The \";\" character is not valid. Use newlines to separate arguments and blocks, and commas to separate items in collection values.")
			toks = append(toks, mk(tInvalid, ";"))
		default:
			l.advance()
			l.err(startLine, startCol, l.line, l.col, "Invalid character", "This character is not used within the language.")
			toks = append(toks, mk(tInvalid, string(c)))
		}
	}
	toks = append(toks, token{kind: tEOF, line: l.line, col: l.col, endLine: l.line, endCol: l.col, offset: l.pos, endOffset: l.pos})
	return toks, l.diags
}

func (l *lexer) lexString() token {
	startLine, startCol, startPos := l.line, l.col, l.pos
	l.advance() // opening quote
	var parts []strPart
	var cur strings.Builder
	hasExpr := false
	flush := func() {
		if cur.Len() > 0 {
			parts = append(parts, strPart{lit: cur.String()})
			cur.Reset()
		}
	}
	for !l.eof() {
		c := l.peek()
		if c == '"' {
			l.advance()
			flush()
			tok := token{kind: tString, text: l.src[startPos:l.pos], line: startLine, col: startCol, endLine: l.line, endCol: l.col, offset: startPos, endOffset: l.pos, parts: parts}
			if !hasExpr {
				var sb strings.Builder
				for _, p := range parts {
					sb.WriteString(p.lit)
				}
				tok.strVal = sb.String()
			}
			return tok
		}
		if c == '\n' {
			// invalid multi-line string
			l.err(startLine, startCol, l.line+1, 1, "Invalid multi-line string", "Quoted strings may not be split over multiple lines. To produce a multi-line string, either use the \\n escape to represent a newline character or use the \"heredoc\" multi-line template syntax.")
			l.advance()
			// extra diagnostics to mimic multiple diag count
			l.err(startLine, startCol, l.line, l.col, "Missing expression", "Expected the start of an expression, but found an invalid expression token.")
			l.err(l.line, l.col, l.line, l.col, "Extra characters after string", "A quoted string must be terminated before the end of the line.")
			flush()
			return token{kind: tString, text: l.src[startPos:l.pos], line: startLine, col: startCol, endLine: l.line, endCol: l.col, offset: startPos, endOffset: l.pos, parts: parts, strVal: cur.String()}
		}
		if c == '\\' {
			l.advance()
			if l.eof() {
				break
			}
			e := l.advance()
			switch e {
			case 'n':
				cur.WriteByte('\n')
			case 't':
				cur.WriteByte('\t')
			case 'r':
				cur.WriteByte('\r')
			case '"':
				cur.WriteByte('"')
			case '\\':
				cur.WriteByte('\\')
			case 'u':
				// \uXXXX (and \UXXXXXXXX)
				var code int
				n := 4
				for i := 0; i < n && !l.eof() && isHex(l.peek()); i++ {
					code = code*16 + hexVal(l.advance())
				}
				cur.WriteRune(rune(code))
			case 'U':
				var code int
				for i := 0; i < 8 && !l.eof() && isHex(l.peek()); i++ {
					code = code*16 + hexVal(l.advance())
				}
				cur.WriteRune(rune(code))
			default:
				cur.WriteByte(e)
			}
			continue
		}
		if c == '$' && l.peekAt(1) == '{' {
			// interpolation; $${ is escaped
			if l.peekAt(2) == '{' {
				// not standard; fallthrough literal
			}
			flush()
			hasExpr = true
			exprLine, exprCol := l.line, l.col+2
			l.advance()
			l.advance()
			depth := 1
			srcStart := l.pos
			for !l.eof() && depth > 0 {
				cc := l.peek()
				if cc == '{' {
					depth++
				} else if cc == '}' {
					depth--
					if depth == 0 {
						break
					}
				} else if cc == '"' {
					// skip nested string
					l.advance()
					for !l.eof() && l.peek() != '"' {
						if l.peek() == '\\' {
							l.advance()
						}
						if !l.eof() {
							l.advance()
						}
					}
					if !l.eof() {
						l.advance()
					}
					continue
				}
				l.advance()
			}
			exprSrc := l.src[srcStart:l.pos]
			if !l.eof() {
				l.advance() // closing }
			}
			parts = append(parts, strPart{isExpr: true, exprSrc: exprSrc, line: exprLine, col: exprCol})
			continue
		}
		if c == '%' && l.peekAt(1) == '{' {
			// template directive: treat as literal for our purposes, consume to }
			flush()
			hasExpr = true
			exprLine, exprCol := l.line, l.col+2
			l.advance()
			l.advance()
			srcStart := l.pos
			for !l.eof() && l.peek() != '}' {
				l.advance()
			}
			exprSrc := "%" + l.src[srcStart:l.pos]
			if !l.eof() {
				l.advance()
			}
			parts = append(parts, strPart{isExpr: true, exprSrc: exprSrc, line: exprLine, col: exprCol})
			continue
		}
		cur.WriteByte(l.advance())
	}
	// unterminated
	l.err(startLine, startCol, l.line, l.col, "Unterminated string", "A quoted string must be terminated before the end of the file.")
	flush()
	return token{kind: tString, text: l.src[startPos:l.pos], line: startLine, col: startCol, endLine: l.line, endCol: l.col, offset: startPos, endOffset: l.pos, parts: parts}
}

func isHex(c byte) bool {
	return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
func hexVal(c byte) int {
	switch {
	case isDigit(c):
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	default:
		return int(c-'A') + 10
	}
}

func (l *lexer) lexHeredoc() (token, bool) {
	startLine, startCol, startPos := l.line, l.col, l.pos
	// <<[-]MARKER
	save := *l
	l.advance()
	l.advance()
	trim := false
	if !l.eof() && l.peek() == '-' {
		trim = true
		l.advance()
	}
	for !l.eof() && (l.peek() == ' ' || l.peek() == '\t') {
		l.advance()
	}
	if l.eof() || !isIdentStart(l.peek()) {
		*l = save
		return token{}, false
	}
	markerStart := l.pos
	for !l.eof() && isIdentChar(l.peek()) {
		l.advance()
	}
	marker := l.src[markerStart:l.pos]
	// to end of line
	for !l.eof() && l.peek() != '\n' {
		l.advance()
	}
	if !l.eof() {
		l.advance()
	}
	var sb strings.Builder
	for !l.eof() {
		lineStartPos := l.pos
		lineStartCol := l.col
		_ = lineStartCol
		// read a line
		for !l.eof() && l.peek() != '\n' {
			l.advance()
		}
		lineText := l.src[lineStartPos:l.pos]
		check := strings.TrimSpace(lineText)
		if check == marker {
			// consume newline if present handled below
			if !l.eof() {
				l.advance()
			}
			content := sb.String()
			if trim {
				// strip common leading whitespace per line: simplified
				lines := strings.SplitAfter(content, "\n")
				minIndent := -1
				for _, ln := range lines {
					if strings.TrimSpace(ln) == "" {
						continue
					}
					ind := 0
					for ind < len(ln) && (ln[ind] == ' ' || ln[ind] == '\t') {
						ind++
					}
					if minIndent == -1 || ind < minIndent {
						minIndent = ind
					}
				}
				if minIndent > 0 {
					for i, ln := range lines {
						if len(ln) >= minIndent {
							lines[i] = ln[minIndent:]
						}
					}
					content = strings.Join(lines, "")
				}
			}
			tok := token{kind: tString, text: l.src[startPos:l.pos], strVal: content, parts: []strPart{{lit: content}}, line: startLine, col: startCol, endLine: l.line, endCol: l.col, offset: startPos, endOffset: l.pos}
			return tok, true
		}
		sb.WriteString(lineText)
		if !l.eof() {
			sb.WriteByte('\n')
			l.advance()
		}
	}
	*l = save
	return token{}, false
}
EOF
"}

