function.arguments:
{"command":"cat > hcl_parse.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

// ---------- AST ----------

type exprKind int

const (
	exLit exprKind = iota
	exString
	exNumber
	exBool
	exNull
	exList
	exObject
	exTraversal
	exFuncCall
	exBinary
	exUnary
	exCond
	exParen
	exForList
	exForObject
	exIndex
	exAnonSymbol // bare identifier used as a symbol (e.g. CASCADE, STORED)
)

type expr struct {
	kind exprKind
	tok  token
	// literal
	strVal string
	parts  []exprPart
	numVal string
	boolVal bool
	// list/object
	elems []*expr
	keys  []*expr // for object: key exprs (may be nil meaning ident key)
	vals  []*expr
	keyNames []string // static names for object items if known
	// traversal
	trav []string
	root string
	// call
	funcName string
	args     []*expr
	// binary/unary/cond
	op    string
	left  *expr
	right *expr
	cond  *expr
	thenE *expr
	elseE *expr
	// for
	forKeyVar, forValVar string
	forColl              *expr
	forBody              *expr
	forKeyExpr           *expr
	forCond              *expr
	groupEllipsis bool
	// index
	index *expr
	target *expr
}

type exprPart struct {
	isExpr bool
	lit    string
	e      *expr
}

type attr struct {
	Name     string
	nameTok  token
	Expr     *expr
	line     int
}

type block struct {
	Type       string
	typeTok    token
	Labels     []string
	labelToks  []token
	Body       *body
	openBrace  token
	closeBrace token
	singleLine bool
}

type body struct {
	Attrs     map[string]*attr
	AttrOrder []*attr
	Blocks    []*block
}

func (b *body) attr(name string) *attr {
	if b == nil {
		return nil
	}
	return b.Attrs[name]
}
func (b *body) blocksOf(typ string) []*block {
	var out []*block
	for _, bl := range b.Blocks {
		if bl.Type == typ {
			out = append(out, bl)
		}
	}
	return out
}

// ---------- Parser ----------

type parser struct {
	toks     []token
	pos      int
	filename string
	src      string
}

func (p *parser) cur() token  { return p.toks[p.pos] }
func (p *parser) peek(n int) token {
	if p.pos+n >= len(p.toks) {
		return p.toks[len(p.toks)-1]
	}
	return p.toks[p.pos+n]
}
func (p *parser) next() token {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}
func (p *parser) diag(tok token, summary, detail string) *hclDiag {
	return diagAt(p.filename, tok.line, tok.col, tok.endLine, tok.endCol, summary, detail)
}
func (p *parser) diagRange(start, end token, summary, detail string) *hclDiag {
	return diagAt(p.filename, start.line, start.col, end.endLine, end.endCol, summary, detail)
}

func parseHCLFile(src, filename string) (*body, error) {
	toks, lexDiags := lexHCL(src, filename)
	if len(lexDiags) > 0 {
		// Scanner errors in HCL surface together with parse errors; for our
		// purposes returning the lexical diagnostics is close enough, but
		// only if parsing cannot proceed. We try parsing first when the
		// tokens are usable (no invalid tokens from bad characters inside
		// strings etc. may produce spurious results). Match HCL: scan
		// errors are reported. If there are any invalid-char diags, HCL
		// returns them all. But a stray "{" parse error has no lex diags.
		// Decide: if any token is tInvalid, return lex diags.
		for _, t := range toks {
			if t.kind == tInvalid {
				return nil, lexDiags
			}
		}
		// Multiline string etc: return lex diags.
		return nil, lexDiags
	}
	p := &parser{toks: toks, filename: filename, src: src}
	b, err := p.parseBody(true, token{})
	if err != nil {
		return nil, err
	}
	return b, nil
}

func (p *parser) parseBody(top bool, openBrace token) (*body, error) {
	b := &body{Attrs: map[string]*attr{}}
	for {
		t := p.cur()
		if t.kind == tEOF {
			if !top {
				return nil, p.diag(openBrace, "Unclosed configuration block", "There is no closing brace for this block before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.")
			}
			return b, nil
		}
		if t.kind == tCBrace {
			if top {
				return nil, p.diag(t, "Argument or block definition required", "An argument or block definition is required here.")
			}
			return b, nil
		}
		if t.kind != tIdent {
			return nil, p.diag(t, "Argument or block definition required", "An argument or block definition is required here.")
		}
		item, isBlock, err := p.parseBodyItem(openBrace, !top)
		if err != nil {
			return nil, err
		}
		if isBlock {
			bl := item.(*block)
			b.Blocks = append(b.Blocks, bl)
			// After a block, if the next token is on the same line as the closing brace
			// and is not } or EOF, HCL requires a newline. It reports this as
			// a missing newline after argument in some cases; we approximate with
			// checking in parseBodyItem of attributes only.
		} else {
			at := item.(*attr)
			if prev, exists := b.Attrs[at.Name]; exists {
				d := diagAt(p.filename, at.nameTok.line, at.nameTok.col, at.nameTok.endLine, at.nameTok.endCol, "Attribute redefined", fmt.Sprintf("The argument %q was already set at %s:%d,%d-%d. Each argument may be set only once.", at.Name, p.filename, prev.nameTok.line, prev.nameTok.col, prev.nameTok.endLine, prev.nameTok.endCol))
				return nil, hclDiags{d}
			}
			b.Attrs[at.Name] = at
			b.AttrOrder = append(b.AttrOrder, at)
		}
	}
}

type itemIface interface{}

func (p *parser) parseBodyItem(openBrace token, inBlock bool) (interface{}, bool, error) {
	nameTok := p.next() // ident
	// Attribute?
	if p.cur().kind == tAssign {
		p.next() // =
		e, err := p.parseExpression()
		if err != nil {
			return nil, false, err
		}
		at := &attr{Name: nameTok.text, nameTok: nameTok, Expr: e, line: nameTok.line}
		// Post-attribute checks: next token.
		nt := p.cur()
		if nt.kind == tComma {
			return nil, false, p.diag(nt, "Unexpected comma after argument", "Argument definitions must be separated by newlines, not commas. An argument definition must end with a newline.")
		}
		if nt.kind != tEOF && nt.kind != tCBrace && nt.line == lastLineOfExpr(e) {
			// Something follows on the same line.
			// It will be handled by the caller loop in most cases (single-line
			// detection) but for multiline blocks HCL errors here.
			// We need to know whether the enclosing block is single line,
			// which we don't know yet. Record by peeking: we instead defer
			// this check to a post-validation pass.
			_ = nt
		}
		return at, false, nil
	}
	// Block: labels (strings or idents) then {
	var labels []string
	var labelToks []token
	for {
		t := p.cur()
		if t.kind == tString {
			p.next()
			labels = append(labels, t.strVal)
			labelToks = append(labelToks, t)
			continue
		}
		if t.kind == tIdent {
			p.next()
			labels = append(labels, t.text)
			labelToks = append(labelToks, t)
			continue
		}
		break
	}
	if p.cur().kind != tOBrace {
		t := p.cur()
		if t.kind == tEOF || t.kind == tCBrace {
			return nil, false, p.diag(nameTok, "Argument or block definition required", "An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value.")
		}
		if len(labels) > 0 {
			return nil, false, p.diagRange(nameTok, t, "Invalid block definition", "A block definition must have block content delimited by \"{\" and \"}\", starting on the same line as the block header.")
		}
		return nil, false, p.diag(nameTok, "Argument or block definition required", "An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value.")
	}
	ob := p.next() // {
	inner, err := p.parseBody(false, ob)
	if err != nil {
		return nil, false, err
	}
	cb := p.cur()
	if cb.kind != tCBrace {
		return nil, false, p.diag(ob, "Unclosed configuration block", "There is no closing brace for this block before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.")
	}
	p.next()
	bl := &block{Type: nameTok.text, typeTok: nameTok, Labels: labels, labelToks: labelToks, Body: inner, openBrace: ob, closeBrace: cb}
	bl.singleLine = ob.line == cb.line
	// Validate single-line rules.
	if bl.singleLine {
		if len(inner.Blocks) > 0 && len(inner.Attrs) == 0 {
			nb := inner.Blocks[0]
			return nil, false, p.diag(nb.typeTok, "Argument definition required", fmt.Sprintf("A single-line block definition can contain only a single argument. If you meant to define argument %q, use an equals sign to assign it a value. To define a nested block, place it on a line of its own within its parent block.", nb.Type))
		}
		if len(inner.Attrs) > 1 {
			second := inner.AttrOrder[1]
			return nil, false, p.diag(second.nameTok, "Invalid single-argument block definition", "A single-line block definition must end with a closing brace immediately after its single argument definition.")
		}
		if len(inner.Attrs) == 1 && len(inner.Blocks) > 0 {
			nb := inner.Blocks[0]
			return nil, false, p.diag(nb.typeTok, "Argument definition required", fmt.Sprintf("A single-line block definition can contain only a single argument. If you meant to define argument %q, use an equals sign to assign it a value. To define a nested block, place it on a line of its own within its parent block.", nb.Type))
		}
	}
	return bl, true, nil
}

func lastLineOfExpr(e *expr) int {
	if e == nil {
		return 0
	}
	return e.tok.endLine
}

// Post-validation for missing newline after argument in multiline blocks.
// We do this by scanning the raw source structure: it is handled implicitly
// because after an attribute, if the next item starts on the same line and
// the block is multiline, hashicorp errors. Our parser structure makes this
// hard to check during parsing (the closing brace is not yet seen), so this
// function walks a parsed body and needs tokens. Instead the check is done
// in a second pass over tokens in validateNewlines below.

func (p *parser) parseExpression() (*expr, error) {
	return p.parseConditional()
}

func (p *parser) parseConditional() (*expr, error) {
	e, err := p.parseBinary(0)
	if err != nil {
		return nil, err
	}
	if p.cur().kind == tQuestion {
		q := p.next()
		thenE, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tColon {
			return nil, p.diag(p.cur(), "Missing conditional separator", "Expected a colon separator after the true branch of a conditional expression.")
		}
		p.next()
		elseE, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		return &expr{kind: exCond, tok: q, cond: e, thenE: thenE, elseE: elseE}, nil
	}
	return e, nil
}

var binPrec = map[tokKind]int{
	tOr: 1, tAnd: 2, tEq: 3, tNeq: 3, tLt: 4, tLte: 4, tGt: 4, tGte: 4, tPlus: 5, tMinus: 5, tStar: 6, tSlash: 6, tPercent: 6,
}
var binOpStr = map[tokKind]string{
	tOr: "||", tAnd: "&&", tEq: "==", tNeq: "!=", tLt: "<", tLte: "<=", tGt: ">", tGte: ">=", tPlus: "+", tMinus: "-", tStar: "*", tSlash: "/", tPercent: "%",
}

func (p *parser) parseBinary(minPrec int) (*expr, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.cur()
		prec, ok := binPrec[t.kind]
		if !ok || prec <= minPrec {
			if minPrec == 0 {
				// loop continues at lowest level only
			}
			break
		}
		opTok := p.next()
		right, err := p.parseBinary(prec)
		if err != nil {
			return nil, err
		}
		left = &expr{kind: exBinary, tok: opTok, op: binOpStr[opTok.kind], left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseUnary() (*expr, error) {
	t := p.cur()
	if t.kind == tNot || t.kind == tMinus || t.kind == tPlus {
		op := p.next()
		e, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		opStr := "!"
		if op.kind == tMinus {
			opStr = "-"
		}
		if op.kind == tPlus {
			opStr = "+"
		}
		return &expr{kind: exUnary, tok: op, op: opStr, left: e}, nil
	}
	return p.parsePostfix()
}

func (p *parser) parsePostfix() (*expr, error) {
	e, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.cur()
		if t.kind == tDot {
			// member access on a traversal/expression
			p.next()
			nameTok := p.cur()
			if nameTok.kind != tIdent && nameTok.kind != tNumber {
				return nil, p.diag(nameTok, "Invalid attribute name", "An attribute name is required after a dot.")
			}
			p.next()
			if e.kind == exTraversal {
				e.trav = append(e.trav, nameTok.text)
			} else {
				// wrap; keep as traversal-like via index target
				e = &expr{kind: exTraversal, tok: nameTok, root: "", trav: []string{nameTok.text}, target: e}
			}
			continue
		}
		if t.kind == tOBrack {
			p.next()
			idx, err := p.parseExpression()
			if err != nil {
				return nil, err
			}
			if p.cur().kind != tCBrack {
				return nil, p.diag(p.cur(), "Missing index separator", "Expected a closing bracket to terminate the index expression.")
			}
			cb := p.next()
			e = &expr{kind: exIndex, tok: cb, target: e, index: idx}
			continue
		}
		break
	}
	return e, nil
}

func (p *parser) parsePrimary() (*expr, error) {
	t := p.cur()
	switch t.kind {
	case tEOF:
		return nil, p.diag(t, "Missing expression", "Expected the start of an expression, but found the end of the file.")
	case tNumber:
		p.next()
		return &expr{kind: exNumber, tok: t, numVal: t.text}, nil
	case tString:
		p.next()
		e := &expr{kind: exString, tok: t, strVal: t.strVal}
		for _, part := range t.parts {
			if part.isExpr {
				sub, err := parseExprFragment(part.exprSrc, p.filename, part.line, part.col)
				if err != nil {
					return nil, err
				}
				e.parts = append(e.parts, exprPart{isExpr: true, e: sub})
			} else {
				e.parts = append(e.parts, exprPart{lit: part.lit})
			}
		}
		if len(t.parts) == 0 {
			e.strVal = t.strVal
		}
		return e, nil
	case tOParen:
		open := p.next()
		// check for unbalanced: handled by expecting )
		e, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tCParen {
			return nil, p.diag(p.cur(), "Unbalanced parentheses", "Expected a closing parenthesis to terminate the expression.")
		}
		p.next()
		return &expr{kind: exParen, tok: open, left: e}, nil
	case tOBrack:
		return p.parseListOrFor()
	case tOBrace:
		return p.parseObjectOrFor()
	case tIdent:
		// true/false/null
		if t.text == "true" || t.text == "false" {
			p.next()
			return &expr{kind: exBool, tok: t, boolVal: t.text == "true"}, nil
		}
		if t.text == "null" {
			p.next()
			return &expr{kind: exNull, tok: t}, nil
		}
		// function call?
		if p.peek(1).kind == tOParen {
			nameTok := p.next()
			p.next() // (
			var args []*expr
			for {
				if p.cur().kind == tCParen {
					p.next()
					break
				}
				a, err := p.parseExpression()
				if err != nil {
					return nil, err
				}
				args = append(args, a)
				if p.cur().kind == tEllipsis {
					p.next()
				}
				if p.cur().kind == tComma {
					p.next()
					continue
				}
				if p.cur().kind == tCParen {
					p.next()
					break
				}
				return nil, p.diag(p.cur(), "Missing argument separator", "Expected a comma to mark the beginning of the next argument.")
			}
			return &expr{kind: exFuncCall, tok: nameTok, funcName: nameTok.text, args: args}, nil
		}
		p.next()
		return &expr{kind: exTraversal, tok: t, root: t.text, trav: []string{t.text}}, nil
	case tCBrace, tCBrack, tCParen, tComma, tColon:
		return nil, p.diag(t, "Missing expression", "Expected the start of an expression, but found an invalid expression token.")
	}
	return nil, p.diag(t, "Missing expression", "Expected the start of an expression, but found an invalid expression token.")
	_ = strings.TrimSpace
}

func (p *parser) parseListOrFor() (*expr, error) {
	open := p.next() // [
	// for expression?
	if p.cur().kind == tIdent && p.cur().text == "for" {
		p.next()
		// for val in coll : body if cond
		// or for k, v in coll :
		var keyVar, valVar string
		v1 := p.next() // ident
		valVar = v1.text
		if p.cur().kind == tComma {
			p.next()
			v2 := p.next()
			keyVar = valVar
			valVar = v2.text
		}
		if p.cur().kind != tIdent || p.cur().text != "in" {
			return nil, p.diag(p.cur(), "Invalid 'for' expression", "For expression requires the 'in' keyword after its name declarations.")
		}
		p.next()
		coll, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tColon {
			return nil, p.diag(p.cur(), "Invalid 'for' expression", "For expression requires a colon after the collection expression.")
		}
		p.next()
		bodyE, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		fe := &expr{kind: exForList, tok: open, forKeyVar: keyVar, forValVar: valVar, forColl: coll, forBody: bodyE}
		if p.cur().kind == tIdent && p.cur().text == "if" {
			p.next()
			cond, err := p.parseExpression()
			if err != nil {
				return nil, err
			}
			fe.forCond = cond
		}
		if p.cur().kind != tCBrack {
			return nil, p.diag(p.cur(), "Missing item separator", "Expected a comma to mark the beginning of the next item.")
		}
		p.next()
		return fe, nil
	}
	e := &expr{kind: exList, tok: open}
	for {
		if p.cur().kind == tCBrack {
			p.next()
			break
		}
		if p.cur().kind == tEOF {
			return nil, p.diag(open, "Unclosed list", "There is no closing bracket for this list before the end of the file.")
		}
		elem, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		e.elems = append(e.elems, elem)
		if p.cur().kind == tComma {
			p.next()
			continue
		}
		if p.cur().kind == tCBrack {
			p.next()
			break
		}
		return nil, p.diag(p.cur(), "Missing item separator", "Expected a comma to mark the beginning of the next item.")
	}
	return e, nil
}

func (p *parser) parseObjectOrFor() (*expr, error) {
	open := p.next() // {
	if p.cur().kind == tIdent && p.cur().text == "for" {
		p.next()
		var keyVar, valVar string
		v1 := p.next()
		valVar = v1.text
		if p.cur().kind == tComma {
			p.next()
			v2 := p.next()
			keyVar = valVar
			valVar = v2.text
		}
		if p.cur().kind != tIdent || p.cur().text != "in" {
			return nil, p.diag(p.cur(), "Invalid 'for' expression", "For expression requires the 'in' keyword after its name declarations.")
		}
		p.next()
		coll, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tColon {
			return nil, p.diag(p.cur(), "Invalid 'for' expression", "For expression requires a colon after the collection expression.")
		}
		p.next()
		keyE, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		group := false
		if p.cur().kind == tEllipsis {
			p.next()
			group = true
		}
		if p.cur().kind != tArrow {
			return nil, p.diag(p.cur(), "Invalid 'for' expression", "Key expression is required when building an object.")
		}
		p.next()
		valE, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		fe := &expr{kind: exForObject, tok: open, forKeyVar: keyVar, forValVar: valVar, forColl: coll, forKeyExpr: keyE, forBody: valE, groupEllipsis: group}
		if p.cur().kind == tIdent && p.cur().text == "if" {
			p.next()
			cond, err := p.parseExpression()
			if err != nil {
				return nil, err
			}
			fe.forCond = cond
		}
		if p.cur().kind != tCBrace {
			return nil, p.diag(p.cur(), "Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.")
		}
		p.next()
		return fe, nil
	}
	e := &expr{kind: exObject, tok: open}
	for {
		if p.cur().kind == tCBrace {
			p.next()
			break
		}
		if p.cur().kind == tEOF {
			return nil, p.diag(open, "Unclosed object", "There is no closing brace for this object before the end of the file.")
		}
		// key: ident, string, or (expr) or other expr
		var keyExpr *expr
		var keyName string
		kt := p.cur()
		if kt.kind == tIdent && (p.peek(1).kind == tAssign || p.peek(1).kind == tColon) {
			p.next()
			keyName = kt.text
		} else if kt.kind == tString && (p.peek(1).kind == tAssign || p.peek(1).kind == tColon) {
			p.next()
			keyName = kt.strVal
			keyExpr = &expr{kind: exString, tok: kt, strVal: kt.strVal}
		} else {
			var err error
			keyExpr, err = p.parseExpression()
			if err != nil {
				return nil, err
			}
			if keyExpr.kind == exString {
				keyName = keyExpr.strVal
			} else if keyExpr.kind == exTraversal && len(keyExpr.trav) == 1 {
				keyName = keyExpr.trav[0]
			}
		}
		if p.cur().kind != tAssign && p.cur().kind != tColon {
			return nil, p.diag(p.cur(), "Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.")
		}
		p.next()
		val, err := p.parseExpression()
		if err != nil {
			return nil, err
		}
		e.keys = append(e.keys, keyExpr)
		e.keyNames = append(e.keyNames, keyName)
		e.vals = append(e.vals, val)
		if p.cur().kind == tComma {
			p.next()
			continue
		}
		if p.cur().kind == tCBrace {
			continue
		}
		// newline separated items are allowed in objects
		continue
	}
	return e, nil
}

func parseExprFragment(src, filename string, baseLine, baseCol int) (*expr, error) {
	// If the fragment is a template directive (%{...}), we approximate.
	if strings.HasPrefix(src, "%") {
		return &expr{kind: exString, strVal: ""}, nil
	}
	toks, lexDiags := lexHCL(src, filename)
	if len(lexDiags) > 0 {
		// adjust positions roughly
		for _, d := range lexDiags {
			d.Range.StartLine += baseLine - 1
			d.Range.EndLine += baseLine - 1
			if d.Range.StartLine == baseLine {
				d.Range.StartCol += baseCol - 1
			}
			if d.Range.EndLine == baseLine {
				d.Range.EndCol += baseCol - 1
			}
		}
		return nil, lexDiags
	}
	// adjust token positions on first line
	for i := range toks {
		if toks[i].line == 1 {
			toks[i].col += baseCol - 1
			toks[i].endCol += baseCol - 1
		}
		toks[i].line += baseLine - 1
		toks[i].endLine += baseLine - 1
	}
	p := &parser{toks: toks, filename: filename, src: src}
	e, err := p.parseExpression()
	if err != nil {
		return nil, err
	}
	return e, nil
}
EOF
"}

