{"command":"cat > hcl_eval.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

type valKind int

const (
	vNull valKind = iota
	vString
	vNumber
	vBool
	vList
	vObject
	vTraversal // unresolved reference (for schema specs, etc.)
	vFunc // unresolved function value e.g. sql("...") stored as call
	vUnknown
)

type value struct {
	kind valKind
	str  string // string value or number text
	b    bool
	list []value
	obj  map[string]value
	keys []string
	// traversal
	trav []string
	// function result placeholder
	funcName string
	funcArgs []value
}

func strVal(s string) value { return value{kind: vString, str: s} }
func boolVal(b bool) value  { return value{kind: vBool, b: b} }
func numVal(s string) value { return value{kind: vNumber, str: s} }
func nullVal() value        { return value{kind: vNull} }

func (v value) toString() string {
	switch v.kind {
	case vString:
		return v.str
	case vNumber:
		return v.str
	case vBool:
		if v.b {
			return "true"
		}
		return "false"
	case vNull:
		return ""
	}
	return ""
}

func (v value) truthy() bool {
	return v.kind == vBool && v.b
}

// evalContext provides variables for configuration evaluation.
type evalContext struct {
	vars    map[string]value
	varOrder []string
	hasVars bool
	locals  map[string]value
	hasLocals bool
	localExprs map[string]*attr // for cycle detection
	localsResolving map[string]bool
	atlasEnv string
	filename string
	baseDir  string // directory of the file being evaluated (for file())
}

func (c *evalContext) errorFor(tok token, summary, detail string) error {
	return hclDiags{diagAt(c.filename, tok.line, tok.col, tok.endLine, tok.endCol, summary, detail)}
}

var knownFuncs = map[string]bool{
	"getenv": true, "lower": true, "upper": true, "file": true, "jsonencode": true, "jsondecode": true,
	"format": true, "concat": true, "length": true, "try": true, "tostring": true, "tonumber": true, "tobool": true,
	"join": false, "split": false,
	"trim": true, "replace": true, "substr": true, "contains": true, "keys": true, "values": true,
	"merge": true, "lookup": true, "element": true, "flatten": true, "reverse": true, "sort": true,
	"min": true, "max": true, "abs": true, "ceil": true, "floor": true, "strlen": false,
	"coalesce": false, "timestamp": false, "uuid": false,
}

func evalExpr(e *expr, ctx *evalContext) (value, error) {
	switch e.kind {
	case exString:
		if len(e.parts) == 0 {
			return strVal(e.strVal), nil
		}
		var sb strings.Builder
		for _, part := range e.parts {
			if part.isExpr {
				v, err := evalExpr(part.e, ctx)
				if err != nil {
					return nullVal(), err
				}
				sb.WriteString(v.toString())
			} else {
				sb.WriteString(part.lit)
			}
		}
		return strVal(sb.String()), nil
	case exNumber:
		return numVal(e.numVal), nil
	case exBool:
		return boolVal(e.boolVal), nil
	case exNull:
		return nullVal(), nil
	case exLit:
		return strVal(e.strVal), nil
	case exParen:
		return evalExpr(e.left, ctx)
	case exList:
		var out []value
		for _, el := range e.elems {
			v, err := evalExpr(el, ctx)
			if err != nil {
				return nullVal(), err
			}
			out = append(out, v)
		}
		if out == nil {
			out = []value{}
		}
		return value{kind: vList, list: out}, nil
	case exObject:
		obj := map[string]value{}
		var keys []string
		for i, ve := range e.vals {
			k := ""
			if i < len(e.keyNames) {
				k = e.keyNames[i]
			}
			if k == "" && i < len(e.keys) && e.keys[i] != nil {
				kv, err := evalExpr(e.keys[i], ctx)
				if err != nil {
					return nullVal(), err
				}
				k = kv.toString()
			}
			v, err := evalExpr(ve, ctx)
			if err != nil {
				return nullVal(), err
			}
			if _, ok := obj[k]; !ok {
				keys = append(keys, k)
			}
			obj[k] = v
		}
		return value{kind: vObject, obj: obj, keys: keys}, nil
	case exTraversal:
		return evalTraversal(e, ctx)
	case exFuncCall:
		return evalFuncCall(e, ctx)
	case exBinary:
		return evalBinary(e, ctx)
	case exUnary:
		v, err := evalExpr(e.left, ctx)
		if err != nil {
			return nullVal(), err
		}
		if e.op == "!" {
			return boolVal(!v.truthy()), nil
		}
		if e.op == "-" {
			if v.kind == vNumber {
				f, _ := strconv.ParseFloat(v.str, 64)
				return numVal(formatFloat(-f)), nil
			}
			return v, nil
		}
		return v, nil
	case exCond:
		c, err := evalExpr(e.cond, ctx)
		if err != nil {
			return nullVal(), err
		}
		if c.truthy() {
			return evalExpr(e.thenE, ctx)
		}
		return evalExpr(e.elseE, ctx)
	case exIndex:
		tgt, err := evalExpr(e.target, ctx)
		if err != nil {
			return nullVal(), err
		}
		idx, err := evalExpr(e.index, ctx)
		if err != nil {
			return nullVal(), err
		}
		if tgt.kind == vList {
			n, _ := strconv.Atoi(idx.toString())
			if n >= 0 && n < len(tgt.list) {
				return tgt.list[n], nil
			}
			return nullVal(), nil
		}
		if tgt.kind == vObject {
			if v, ok := tgt.obj[idx.toString()]; ok {
				return v, nil
			}
			return nullVal(), ctx.errorFor(e.index.tok, "Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.", idx.toString()))
		}
		return nullVal(), nil
	case exForList:
		coll, err := evalExpr(e.forColl, ctx)
		if err != nil {
			return nullVal(), err
		}
		var items []value
		var itemKeys []value
		if coll.kind == vList {
			for i, it := range coll.list {
				items = append(items, it)
				itemKeys = append(itemKeys, numVal(strconv.Itoa(i)))
			}
		} else if coll.kind == vObject {
			for _, k := range coll.keys {
				itemKeys = append(itemKeys, strVal(k))
				items = append(items, coll.obj[k])
			}
		}
		var out []value
		for i, it := range items {
			child := ctx.childScope(e.forValVar, it, e.forKeyVar, itemKeys[i])
			if e.forCond != nil {
				cv, err := evalExpr(e.forCond, child)
				if err != nil {
					return nullVal(), err
				}
				if !cv.truthy() {
					continue
				}
			}
			bv, err := evalExpr(e.forBody, child)
			if err != nil {
				return nullVal(), err
			}
			out = append(out, bv)
		}
		if out == nil {
			out = []value{}
		}
		return value{kind: vList, list: out}, nil
	case exForObject:
		coll, err := evalExpr(e.forColl, ctx)
		if err != nil {
			return nullVal(), err
		}
		var items []value
		var itemKeys []value
		if coll.kind == vList {
			for i, it := range coll.list {
				items = append(items, it)
				itemKeys = append(itemKeys, numVal(strconv.Itoa(i)))
			}
		} else if coll.kind == vObject {
			for _, k := range coll.keys {
				itemKeys = append(itemKeys, strVal(k))
				items = append(items, coll.obj[k])
			}
		}
		obj := map[string]value{}
		var keys []string
		for i, it := range items {
			child := ctx.childScope(e.forValVar, it, e.forKeyVar, itemKeys[i])
			if e.forCond != nil {
				cv, err := evalExpr(e.forCond, child)
				if err != nil {
					return nullVal(), err
				}
				if !cv.truthy() {
					continue
				}
			}
			kv, err := evalExpr(e.forKeyExpr, child)
			if err != nil {
				return nullVal(), err
			}
			vv, err := evalExpr(e.forBody, child)
			if err != nil {
				return nullVal(), err
			}
			k := kv.toString()
			if _, ok := obj[k]; !ok {
				keys = append(keys, k)
			}
			obj[k] = vv
		}
		return value{kind: vObject, obj: obj, keys: keys}, nil
	}
	return nullVal(), nil
}

func (c *evalContext) childScope(valVar string, val value, keyVar string, key value) *evalContext {
	child := *c
	// store loop vars in vars map under special handling: we piggyback on locals map? Instead we keep extra map.
	child.loopVars = map[string]value{}
	for k, v := range c.loopVars {
		child.loopVars[k] = v
	}
	if valVar != "" {
		child.loopVars[valVar] = val
	}
	if keyVar != "" {
		child.loopVars[keyVar] = key
	}
	return &child
}

func evalTraversal(e *expr, ctx *evalContext) (value, error) {
	trav := e.trav
	if len(trav) == 0 && e.target != nil {
		// member access on an expression result
		tgt, err := evalExpr(e.target, ctx)
		if err != nil {
			return nullVal(), err
		}
		return tgt, nil
	}
	if len(trav) == 0 {
		return nullVal(), nil
	}
	root := trav[0]
	// loop variables take precedence (single identifier)
	if len(trav) == 1 {
		if ctx.loopVars != nil {
			if v, ok := ctx.loopVars[root]; ok {
				return v, nil
			}
		}
	}
	switch root {
	case "var":
		if !ctx.hasVars || ctx.vars == nil {
			if len(trav) >= 2 {
				// This object does not have... but "var" itself exists as empty object in HCL?
				// Original: referencing var.foo with no variables gives Unsupported attribute.
				return nullVal(), ctx.errorForRangeForAttr(e, 1)
			}
			return value{kind: vObject, obj: map[string]value{}}, nil
		}
		if len(trav) == 1 {
			return value{kind: vObject, obj: ctx.vars}, nil
		}
		v, ok := ctx.vars[trav[1]]
		if !ok {
			return nullVal(), ctx.errorForRangeForAttr(e, 1)
		}
		return traverseValue(v, trav[2:], e, ctx)
	case "local":
		if !ctx.hasLocals {
			// original message: Unknown local; There is no variable named "local".
			// range is of the trav token?? It used the attr expr token covering local.? For our
			// approximation use the traversal token.
			return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, travEndCol(e), "Unknown local", `There is no variable named "local".`)}
		}
		if len(trav) == 1 {
			return value{kind: vObject, obj: ctx.locals}, nil
		}
		name := trav[1]
		v, err := ctx.resolveLocal(name, e)
		if err != nil {
			return nullVal(), err
		}
		return traverseValue(v, trav[2:], e, ctx)
	case "atlas":
		if len(trav) == 1 {
			m := map[string]value{"env": strVal(ctx.atlasEnv)}
			return value{kind: vObject, obj: m, keys: []string{"env"}}, nil
		}
		if trav[1] == "env" {
			return traverseValue(strVal(ctx.atlasEnv), trav[2:], e, ctx)
		}
		return nullVal(), ctx.errorForRangeForAttr(e, 1)
	default:
		if len(trav) == 1 {
			if ctx.loopVars != nil {
				if v, ok := ctx.loopVars[root]; ok {
					return v, nil
				}
			}
			// unknown variable
			return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown variable", fmt.Sprintf("There is no variable named %q.", root))}
		}
		if ctx.loopVars != nil {
			if v, ok := ctx.loopVars[root]; ok {
				return traverseValue(v, trav[1:], e, ctx)
			}
		}
		return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown variable", fmt.Sprintf("There is no variable named %q.", root))}
	}
}

func travEndCol(e *expr) int {
	// approximate end of full traversal: token end + remaining parts lengths
	c := e.tok.endCol
	for _, p := range e.trav {
		c += len(p) + 1
	}
	return c
}

// error for trav[idx] attribute range: the attribute token is not stored per-part
// in our AST, so approximate by locating within the traversal string.
func (c *evalContext) errorForRangeForAttr(e *expr, idx int) error {
	// compute start col: tok col plus sum of previous parts + dots
	start := e.tok.col
	for i := 0; i < idx; i++ {
		start += len(e.trav[i]) + 1
	}
	name := ""
	if idx < len(e.trav) {
		name = e.trav[idx]
	}
	return hclDiags{diagAt(c.filename, e.tok.line, start, e.tok.line, start+len(name), "Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.", name))}
}

func traverseValue(v value, rest []string, e *expr, ctx *evalContext) (value, error) {
	cur := v
	baseIdx := len(e.trav) - len(rest)
	for i, name := range rest {
		if cur.kind == vObject {
			nv, ok := cur.obj[name]
			if !ok {
				return nullVal(), ctx.errorForRangeForAttr(e, baseIdx+i)
			}
			cur = nv
		} else {
			return nullVal(), nil
		}
	}
	return cur, nil
}

func (c *evalContext) resolveLocal(name string, e *expr) (value, error) {
	if v, ok := c.locals[name]; ok {
		return v, nil
	}
	if c.localExprs == nil {
		// locals object exists but attribute missing
		return nullVal(), c.errorForRangeForAttr(e, 1)
	}
	at, ok := c.localExprs[name]
	if !ok {
		return nullVal(), c.errorForRangeForAttr(e, 1)
	}
	if c.localsResolving == nil {
		c.localsResolving = map[string]bool{}
	}
	if c.localsResolving[name] {
		return nullVal(), fmt.Errorf("cyclic reference to %q", "local."+name)
	}
	c.localsResolving[name] = true
	v, err := evalExpr(at.Expr, c)
	delete(c.localsResolving, name)
	if err != nil {
		// cyclic errors come back as plain error from inner resolution
		return nullVal(), err
	}
	if c.locals == nil {
		c.locals = map[string]value{}
	}
	c.locals[name] = v
	return v, nil
}

func evalFuncCall(e *expr, ctx *evalContext) (value, error) {
	name := e.funcName
	// try() special: evaluate lazily
	if name == "try" {
		for _, a := range e.args {
			v, err := evalExpr(a, ctx)
			if err == nil {
				return v, nil
			}
		}
		if len(e.args) > 0 {
			_, err := evalExpr(e.args[0], ctx)
			return nullVal(), err
		}
		return nullVal(), nil
	}
	if !knownFuncs[name] {
		// function name token is e.tok
		return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Call to unknown function", fmt.Sprintf("There is no function named %q.", name))}
	}
	// arity checks for getenv (mimic HCL diagnostics positions)
	if name == "getenv" {
		if len(e.args) == 0 {
			// position of closing paren: approximate using func token end
			col := e.tok.endCol + 1 // after '('? original uses position of ) token
			// We don't have paren token; approximate with endCol+len(name)+1
			_ = col
			return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.endCol+1, e.tok.line, e.tok.endCol+2, "Not enough function arguments", fmt.Sprintf("Function %q expects 1 argument(s). Missing value for \"key\".", name))}
		}
		if len(e.args) > 1 {
			second := e.args[1]
			return nullVal(), hclDiags{diagAt(ctx.filename, second.tok.line, second.tok.endLine, second.tok.line, second.tok.endLine+1, "Too many function arguments", fmt.Sprintf("Function %q expects only 1 argument(s).", name))}
		}
	}
	var args []value
	for _, a := range e.args {
		v, err := evalExpr(a, ctx)
		if err != nil {
			return nullVal(), err
		}
		args = append(args, v)
	}
	switch name {
	case "getenv":
		key := args[0].toString()
		return strVal(os.Getenv(key)), nil
	case "lower":
		return strVal(strings.ToLower(args[0].toString())), nil
	case "upper":
		return strVal(strings.ToUpper(args[0].toString())), nil
	case "file":
		path := args[0].toString()
		full := path
		if ctx.baseDir != "" && !strings.HasPrefix(path, "/") {
			full = ctx.baseDir + "/" + path
		}
		data, err := os.ReadFile(full)
		if err != nil {
			// detail: Call to function "file" failed: open <abs path>: no such file...
			abs := full
			return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Error in function call", fmt.Sprintf("Call to function %q failed: open %s: no such file or directory.", name, abs))}
		}
		return strVal(string(data)), nil
	case "jsonencode":
		return strVal(marshalValueJSON(args[0])), nil
	case "jsondecode":
		// minimal
		return strVal(args[0].toString()), nil
	case "format":
		if len(args) == 0 {
			return strVal(""), nil
		}
		fmtStr := args[0].toString()
		var iargs []interface{}
		for _, a := range args[1:] {
			iargs = append(iargs, a.toString())
		}
		// handle %s/%d basics
		out := fmtStr
		// Use fmt with string args if verbs are %s only; otherwise fallback
		n := strings.Count(fmtStr, "%")
		if n > 0 && n <= len(iargs) {
			out = fmt.Sprintf(fmtStr, iargs[:n]...)
		}
		return strVal(out), nil
	case "concat":
		var out []value
		for _, a := range args {
			if a.kind == vList {
				out = append(out, a.list...)
			}
		}
		if out == nil {
			out = []value{}
		}
		return value{kind: vList, list: out}, nil
	case "length":
		if len(args) > 0 {
			a := args[0]
			if a.kind == vList {
				return numVal(strconv.Itoa(len(a.list))), nil
			}
			if a.kind == vObject {
				return numVal(strconv.Itoa(len(a.obj))), nil
			}
			return nullVal(), hclDiags{diagAt(ctx.filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Error in function call", fmt.Sprintf("Call to function %q failed: collection must be a list, a map or a tuple.", name))}
		}
	case "tostring":
		return strVal(args[0].toString()), nil
	case "tonumber":
		return numVal(args[0].toString()), nil
	case "join":
		// not in known (marked false) - handled above as unknown
	case "merge":
		obj := map[string]value{}
		var keys []string
		for _, a := range args {
			if a.kind == vObject {
				for _, k := range a.keys {
					if _, ok := obj[k]; !ok {
						keys = append(keys, k)
					}
					obj[k] = a.obj[k]
				}
			}
		}
		return value{kind: vObject, obj: obj, keys: keys}, nil
	case "lookup":
		if len(args) >= 2 && args[0].kind == vObject {
			if v, ok := args[0].obj[args[1].toString()]; ok {
				return v, nil
			}
			if len(args) >= 3 {
				return args[2], nil
			}
		}
		return nullVal(), nil
	case "keys":
		if args[0].kind == vObject {
			var out []value
			for _, k := range args[0].keys {
				out = append(out, strVal(k))
			}
			return value{kind: vList, list: out}, nil
		}
	case "values":
		if args[0].kind == vObject {
			var out []value
			for _, k := range args[0].keys {
				out = append(out, args[0].obj[k])
			}
			return value{kind: vList, list: out}, nil
		}
	case "trim":
		return strVal(strings.TrimSpace(args[0].toString())), nil
	case "replace":
		if len(args) >= 3 {
			return strVal(strings.ReplaceAll(args[0].toString(), args[1].toString(), args[2].toString())), nil
		}
	case "contains":
		if len(args) >= 2 && args[0].kind == vList {
			for _, it := range args[0].list {
				if it.toString() == args[1].toString() {
					return boolVal(true), nil
				}
			}
			return boolVal(false), nil
		}
	}
	return strVal(""), nil
}

func marshalValueJSON(v value) string {
	switch v.kind {
	case vString:
		return strconv.Quote(v.str)
	case vNumber:
		return v.str
	case vBool:
		return v.toString()
	case vNull:
		return "null"
	case vList:
		var parts []string
		for _, it := range v.list {
			parts = append(parts, marshalValueJSON(it))
		}
		return "[" + strings.Join(parts, ",") + "]"
	case vObject:
		var parts []string
		for _, k := range v.keys {
			parts = append(parts, strconv.Quote(k)+":"+marshalValueJSON(v.obj[k]))
		}
		return "{" + strings.Join(parts, ",") + "}"
	}
	return `""`
}

func evalBinary(e *expr, ctx *evalContext) (value, error) {
	// short circuit
	if e.op == "&&" {
		l, err := evalExpr(e.left, ctx)
		if err != nil {
			return nullVal(), err
		}
		if !l.truthy() {
			return boolVal(false), nil
		}
		r, err := evalExpr(e.right, ctx)
		if err != nil {
			return nullVal(), err
		}
		return boolVal(r.truthy()), nil
	}
	if e.op == "||" {
		l, err := evalExpr(e.left, ctx)
		if err != nil {
			return nullVal(), err
		}
		if l.truthy() {
			return boolVal(true), nil
		}
		r, err := evalExpr(e.right, ctx)
		if err != nil {
			return nullVal(), err
		}
		return boolVal(r.truthy()), nil
	}
	l, err := evalExpr(e.left, ctx)
	if err != nil {
		return nullVal(), err
	}
	r, err := evalExpr(e.right, ctx)
	if err != nil {
		return nullVal(), err
	}
	switch e.op {
	case "==":
		return boolVal(valuesEqual(l, r)), nil
	case "!=":
		return boolVal(!valuesEqual(l, r)), nil
	case "<", "<=", ">", ">=":
		lf, lok := toFloat(l)
		rf, rok := toFloat(r)
		if lok && rok {
			switch e.op {
			case "<":
				return boolVal(lf < rf), nil
			case "<=":
				return boolVal(lf <= rf), nil
			case ">":
				return boolVal(lf > rf), nil
			case ">=":
				return boolVal(lf >= rf), nil
			}
		}
		ls, rs := l.toString(), r.toString()
		switch e.op {
		case "<":
			return boolVal(ls < rs), nil
		case "<=":
			return boolVal(ls <= rs), nil
		case ">":
			return boolVal(ls > rs), nil
		case ">=":
			return boolVal(ls >= rs), nil
		}
	case "+", "-", "*", "/", "%":
		lf, lok := toFloat(l)
		rf, rok := toFloat(r)
		if lok && rok {
			var res float64
			switch e.op {
			case "+":
				res = lf + rf
			case "-":
				res = lf - rf
			case "*":
				res = lf * rf
			case "/":
				res = lf / rf
			case "%":
				res = math.Mod(lf, rf)
			}
			return numVal(formatFloat(res)), nil
		}
		if e.op == "+" {
			return strVal(l.toString() + r.toString()), nil
		}
	}
	return nullVal(), nil
}

func valuesEqual(a, b value) bool {
	if a.kind != b.kind {
		// numbers/strings comparison coercion
		return a.toString() == b.toString()
	}
	switch a.kind {
	case vBool:
		return a.b == b.b
	case vList:
		if len(a.list) != len(b.list) {
			return false
		}
		for i := range a.list {
			if !valuesEqual(a.list[i], b.list[i]) {
				return false
			}
		}
		return true
	default:
		return a.toString() == b.toString()
	}
}

func toFloat(v value) (float64, bool) {
	if v.kind == vNumber || v.kind == vString {
		f, err := strconv.ParseFloat(v.str, 64)
		return f, err == nil
	}
	return 0, false
}

func formatFloat(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}
EOF
"}

