}

func (s *sqliteDB) Close() {
	if s.db != nil {
		C.sqlite3_close(s.db)
		s.db = nil
	}
}

func (s *sqliteDB) errmsg() string {
	if s.db == nil {
		return ""
	}
	em := C.sqlite3_errmsg(s.db)
	if em == nil {
		return ""
	}
	return C.GoString(em)
}

// Exec executes one or more statements; returns error with sqlite message.
func (s *sqliteDB) Exec(sql string) error {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	rc := C.sqlite3_exec(s.db, csql, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		msg := s.errmsg()
		if errmsg != nil {
			msg = C.GoString(errmsg)
			C.sqlite3_free(unsafe.Pointer(errmsg))
		}
		return fmt.Errorf("%s", msg)
	}
	return nil
}

// ExecStmt executes exactly the first statement (must be single).
func (s *sqliteDB) ExecStmt(sql string) error {
	stmts, err := s.prepareAll(sql)
	if err != nil {
		return err
	}
	defer func() {
		for _, st := range stmts {
			C.sqlite3_finalize(st)
		}
	}()
	for _, st := range stmts {
		for {
			rc := C.sqlite3_step(st)
			if rc == C.SQLITE_DONE {
				break
			}
			if rc == C.SQLITE_ROW {
				continue
			}
			return fmt.Errorf("%s", s.errmsg())
		}
	}
	return nil
}

func (s *sqliteDB) prepareAll(sql string) ([]*C.sqlite3_stmt, error) {
	var stmts []*C.sqlite3_stmt
	rest := sql
	for {
		trimmed := strings.TrimSpace(rest)
		if trimmed == "" {
			break
		}
		csql := C.CString(rest)
		var stmt *C.sqlite3_stmt
		var tail *C.char
		rc := C.sqlite3_prepare_v2(s.db, csql, -1, &stmt, &tail)
		if rc != C.SQLITE_OK {
			msg := s.errmsg()
			C.free(unsafe.Pointer(csql))
			for _, st := range stmts {
				C.sqlite3_finalize(st)
			}
			return nil, fmt.Errorf("%s", msg)
		}
		consumed := 0
		if tail != nil {
			consumed = int(uintptr(unsafe.Pointer(tail)) - uintptr(unsafe.Pointer(csql)))
		}
		C.free(unsafe.Pointer(csql))
		if stmt != nil {
			stmts = append(stmts, stmt)
		}
		if consumed <= 0 || consumed >= len(rest) {
			break
		}
		rest = rest[consumed:]
	}
	return stmts, nil
}

func (s *sqliteDB) Query(sql string) ([]sqliteRow, error) {
	stmts, err := s.prepareAll(sql)
	if err != nil {
		return nil, err
	}
	defer func() {
		for _, st := range stmts {
			C.sqlite3_finalize(st)
		}
	}()
	var rows []sqliteRow
	for _, st := range stmts {
		ncol := int(C.sqlite3_column_count(st))
		var cols []string
		for i := 0; i < ncol; i++ {
			name := C.sqlite3_column_name(st, C.int(i))
			cols = append(cols, C.GoString(name))
		}
		for {
			rc := C.sqlite3_step(st)
			if rc == C.SQLITE_DONE {
				break
			}
			if rc != C.SQLITE_OK && rc != C.SQLITE_ROW {
				return nil, fmt.Errorf("%s", s.errmsg())
			}
			if rc == C.SQLITE_ROW {
				row := sqliteRow{Cols: cols}
				for i := 0; i < ncol; i++ {
					t := C.sqlite3_column_type(st, C.int(i))
					switch t {
					case C.SQLITE_NULL:
						row.Vals = append(row.Vals, nil)
					case C.SQLITE_INTEGER:
						row.Vals = append(row.Vals, int64(C.sqlite3_column_int64(st, C.int(i))))
					case C.SQLITE_FLOAT:
						row.Vals = append(row.Vals, float64(C.sqlite3_column_double(st, C.int(i))))
					case C.SQLITE_BLOB:
						n := int(C.sqlite3_column_bytes(st, C.int(i)))
						ptr := C.sqlite3_column_blob(st, C.int(i))
						if n == 0 || ptr == nil {
							row.Vals = append(row.Vals, []byte{})
						} else {
							row.Vals = append(row.Vals, C.GoBytes(ptr, C.int(n)))
						}
					default:
						txt := C.sqlite3_column_text(st, C.int(i))
						if txt == nil {
							row.Vals = append(row.Vals, "")
						} else {
							row.Vals = append(row.Vals, C.GoString((*C.char)(unsafe.Pointer(txt))))
						}
					}
				}
				rows = append(rows, row)
			}
		}
	}
	return rows, nil
}

func (s *sqliteDB) QueryOne(sql string) (sqliteRow, bool, error) {
	rows, err := s.Query(sql)
	if err != nil {
		return sqliteRow{}, false, err
	}
	if len(rows) == 0 {
		return sqliteRow{}, false, nil
	}
	return rows[0], true, nil
}

func valString(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case []byte:
		return string(x)
	case int64:
		return fmt.Sprintf("%d", x)
	case float64:
		return fmt.Sprintf("%v", x)
	}
	return fmt.Sprintf("%v", v)
}
func valInt(v interface{}, def int64) int64 {
	switch x := v.(type) {
	case int64:
		return x
	case float64:
		return int64(x)
	case string:
		var n int64
		fmt.Sscanf(x, "%d", &n)
		return n
	}
	return def
}
func valBool(v interface{}) bool {
	switch x := v.(type) {
	case int64:
		return x != 0
	case string:
		return x == "1" || x == "true"
	case bool:
		return x
	}
	return false
}
