	i := strings.Index(raw, "://")
	if i < 0 {
		return ""
	}
	return raw[:i]
}

func isKnownDriver(scheme string) bool {
	switch scheme {
	case "sqlite", "sqlite3", "mysql", "mariadb", "postgres", "postgresql", "docker", "libsql":
		return true
	}
	return false
}

func driverName(scheme string) string {
	switch scheme {
	case "sqlite3":
		return "sqlite"
	case "mariadb":
		return "mysql"
	case "postgresql":
		return "postgres"
	}
	return scheme
}

// openDBClient opens a database URL using sqlclient.Open semantics.
// Only sqlite is fully supported; other known drivers attempt a TCP
// connection so network errors match the Go runtime.
type dbClient struct {
	driver   string // normalized name: sqlite, mysql, postgres, docker
	raw      string
	url      *sqlclient.URL
	sqlite   *sqliteDB
	dsn      string // sqlite DSN/filename-ish
	isMemory bool
}

func (c *dbClient) Close() {
	if c != nil && c.sqlite != nil {
		c.sqlite.Close()
		c.sqlite = nil
	}
}

func openDBClient(raw string) (*dbClient, error) {
	scheme := schemeOf(raw)
	if scheme == "" {
		return nil, fmt.Errorf("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	if !isKnownDriver(scheme) {
		return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", scheme)
	}
	if scheme == "docker" {
		return nil, dockerOpenError(raw)
	}
	// Parse the URL (Go syntax errors surface unwrapped).
	cu, err := parseURLForDriver(raw)
	if err != nil {
		return nil, err
	}
	dn := driverName(scheme)
	switch dn {
	case "sqlite":
		dsn, memory, aerr := sqliteDSN(raw, cu)
		if aerr != nil {
			// e.g. invalid uri authority; deferred to inspection stage in
			// the original - but callers that inspect immediately will wrap.
			// Store the error to surface at open time with querying prefix
			// handled by inspect wrappers. We return it directly here and
			// let callers wrap where appropriate.
			return nil, aerr
		}
		db, err := sqliteOpen(dsn)
		if err != nil {
			return nil, err
		}
		return &dbClient{driver: "sqlite", raw: raw, url: cu, sqlite: db, dsn: dsn, isMemory: memory}, nil
	case "mysql":
		if err := dialDriverError(cu, "3306", "mysql: query system variables"); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("mysql: query system variables: connection succeeded but server is not supported by this build")
	case "postgres":
		if err := dialDriverError(cu, "5432", "postgres: scanning system variables"); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("postgres: scanning system variables: connection succeeded but server is not supported by this build")
	case "libsql":
		return nil, libsqlOpenError(raw, cu)
	}
	return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", scheme)
}

// parseURLForDriver parses with Go url.Parse, returning inner errors.
func parseURLForDriver(raw string) (*sqlclient.URL, error) {
	uu, err := url.Parse(raw)
	if err != nil {
		type unwrapper interface{ Unwrap() error }
		if ue, ok := err.(unwrapper); ok && ue.Unwrap() != nil {
			return nil, ue.Unwrap()
		}
		return nil, err
	}
	cu := &sqlclient.URL{URL: uu}
	switch uu.Scheme {
	case "sqlite", "sqlite3", "libsql":
		cu.Schema = "main"
	case "postgres", "postgresql":
		if sp := uu.Query().Get("search_path"); sp != "" {
			parts := strings.Split(sp, ",")
			cu.Schema = strings.TrimSpace(parts[0])
		} else {
			cu.Schema = "public"
		}
	case "mysql", "mariadb":
		// database name is the schema
		cu.Schema = strings.TrimPrefix(uu.Path, "/")
	}
	return cu, nil
}

func dialDriverError(cu *sqlclient.URL, defaultPort, prefix string) error {
	host := cu.Host
	addr := host
	if !strings.Contains(host, ":") {
		addr = host + ":" + defaultPort
	}
	// If host contains a port already it is host:port; url.Host may be
	// "localhost:3306". Dial with a timeout similar to Go SQL drivers.
	conn, err := net.DialTimeout("tcp", addr, 10*time.Second)
	if err != nil {
		return fmt.Errorf("%s: %s", prefix, err.Error())
	}
	conn.Close()
	return nil
}

func dockerOpenError(raw string) error {
	// docker://<image>[/<tag>[/<name>]] - image comes from host component
	rest := strings.TrimPrefix(raw, "docker://")
	image := rest
	if i := strings.Index(rest, "/"); i >= 0 {
		image = rest[:i]
	}
	switch image {
	case "mysql", "mariadb", "postgres", "postgressql", "cockroachdb", "sqlserver", "clickhouse", "sqlite", "libsql":
		// Only mysql/mariadb/postgres are supported in this build; others below.
	}
	switch image {
	case "mysql", "mariadb", "postgres":
		// Check docker binary like the original (exec.LookPath error message).
		_, err := lookPathDocker()
		if err != nil {
			return err
		}
		return fmt.Errorf("docker: not supported in this environment")
	default:
		return fmt.Errorf("unsupported docker image %q", image)
	}
}
