// sqliteDSN derives the sqlite filename/DSN from a sqlite:// URL.
// Behaviour is inferred from the original driver:
//   - the part after "sqlite://" is treated largely as a raw filename
//   - "file:" URIs are passed through to sqlite (file:/path, file:///path)
//   - "file://authority" is an error: invalid uri authority
//   - ?mode=memory (or an empty name) gives an in-memory/ephemeral database
func sqliteDSN(raw string, cu *sqlclient.URL) sqliteDSNResult {
	scheme := cu.Scheme
	rest := raw
	prefix := scheme + "://"
	if strings.HasPrefix(rest, prefix) {
		rest = rest[len(prefix):]
	} else if i := strings.Index(rest, "://"); i >= 0 {
		rest = rest[i+3:]
	}
	// Separate query.
	pathPart := rest
	rawQuery := cu.RawQuery
	if idx := strings.Index(rest, "?"); idx >= 0 {
		pathPart = rest[:idx]
	}
	q, qerr := url.ParseQuery(rawQuery)
	if qerr != nil {
		type unwrapper interface{ Unwrap() error }
		msg := qerr.Error()
		if ue, ok := qerr.(unwrapper); ok && ue.Unwrap() != nil {
			msg = ue.Unwrap().Error()
		}
		return sqliteDSNResult{deferred: fmt.Errorf("%s", msg)}
	}
	res := sqliteDSNResult{}
	// foreign keys pragma params
	for _, key := range []string{"_fk", "_foreign_keys", "foreign_keys"} {
		if vals, ok := q[key]; ok && len(vals) > 0 {
			v := strings.ToLower(vals[0])
			on := v == "1" || v == "on" || v == "true"
			res.fkOn = &on
		}
	}
	mode := q.Get("mode")
	if mode == "memory" {
		res.dsn = ":memory:"
		res.memory = true
		return res
	}
	if mode == "ro" {
		res.readOnly = true
	}
	if pathPart == "" {
		res.dsn = ":memory:"
		res.memory = true
		return res
	}
	if pathPart == ":memory:" {
		res.dsn = ":memory:"
		res.memory = true
		return res
	}
	if strings.HasPrefix(pathPart, "file:") {
		// sqlite URI
		if strings.HasPrefix(pathPart, "file://") {
			after := pathPart[len("file://"):]
			authority := after
			if i := strings.Index(after, "/"); i >= 0 {
				authority = after[:i]
			}
			if authority != "" {
				return sqliteDSNResult{deferred: fmt.Errorf("invalid uri authority: %s", authority)}
			}
			// file:///path -> uri file:///path (sqlite handles)
			res.dsn = pathPart
			// apply query params besides mode via pragma handling; append mode if set
			if mode != "" && mode != "memory" {
				sep := "?"
				if strings.Contains(res.dsn, "?") {
					sep = "&"
				}
				res.dsn += sep + "mode=" + mode
			}
			return res
		}
		// file:/path or file:relative
		res.dsn = pathPart
		if mode != "" && mode != "memory" {
			sep := "?"
			if strings.Contains(res.dsn, "?") {
				sep = "&"
			}
			res.dsn += sep + "mode=" + mode
		}
		return res
	}
	// plain filename
	res.dsn = pathPart
	return res
}

func libsqlOpenError(raw string, cu *sqlclient.URL) error {
	// libsql URLs are converted to https and a POST is issued during
	// inspection; reproduce the Go http error shape by attempting a dial.
