		res.memory = true
		return res
	}
	if strings.HasPrefix(pathPart, "file:") {
		// sqlite URI
		if strings.HasPrefix(pathPart, "file://") {
			after := pathPart[len("file://"):]
			authority := after
			if i := strings.Index(after, "/"); i >= 0 {
				authority = after[:i]
			}
			if authority != "" {
				return sqliteDSNResult{deferred: fmt.Errorf("invalid uri authority: %s", authority)}
			}
			// file:///path -> uri file:///path (sqlite handles)
			res.dsn = pathPart
			// apply query params besides mode via pragma handling; append mode if set
			if mode != "" && mode != "memory" {
				sep := "?"
				if strings.Contains(res.dsn, "?") {
					sep = "&"
				}
				res.dsn += sep + "mode=" + mode
			}
			return res
		}
		// file:/path or file:relative
		res.dsn = pathPart
		if mode != "" && mode != "memory" {
			sep := "?"
			if strings.Contains(res.dsn, "?") {
				sep = "&"
			}
			res.dsn += sep + "mode=" + mode
		}
		return res
	}
	// plain filename
	res.dsn = pathPart
	return res
}

func libsqlOpenError(raw string, cu *sqlclient.URL) error {
	// libsql URLs are converted to https and a POST is issued during
	// inspection; reproduce the Go http error shape by attempting a dial.
	httpsURL := "https://" + cu.Host + cu.Path + "/v2/pipeline"
	// Attempt a TCP dial to host:443 to obtain the same dial error.
	host := cu.Host
	addr := host
	if !strings.Contains(host, ":") {
		addr = host + ":443"
	}
	conn, err := dialTCP(addr)
	if err != nil {
		return fmt.Errorf("sqlite: querying schemas: failed to execute SQL:\nPost %q: %s", httpsURL, err.Error())
	}
	if conn != nil {
		conn.Close()
	}
	return fmt.Errorf("sqlite: querying schemas: failed to execute SQL:\nPost %q: connection succeeded but server is not supported by this build", httpsURL)
}
