func sqliteOpenReadOnly(dsn string) (*sqliteDB, error) {
	var db *C.sqlite3
	cname := C.CString(dsn)
	defer C.free(unsafe.Pointer(cname))
	rc := C.sqlite3_open_v2(cname, &db, C.SQLITE_OPEN_READONLY|C.SQLITE_OPEN_FULLMUTEX, nil)
