func sqliteErrPrefix(err error) error {
	if err == nil {
		return nil
	}
	msg := err.Error()
	if msg == "unable to open database file" {
		msg = "unable to open database file: no such file or directory"
	}
	return fmt.Errorf("sqlite: querying schemas: %s", msg)
}

// inspectSQLiteRealm reads the schema of the sqlite database of the client.
func inspectSQLiteRealm(c *dbClient) (*schema.Realm, error) {
	if c.deferredErr != nil {
		return nil, sqliteErrPrefix(c.deferredErr)
	}
	if c.sqlite == nil {
		return nil, sqliteErrPrefix(fmt.Errorf("unable to open database file: no such file or directory"))
	}
	db := c.sqlite
	// Querying schemas stage.
	_, err := db.Query("SELECT name FROM sqlite_master LIMIT 1")
	if err != nil {
		return nil, sqliteErrPrefix(err)
	}
	rows, err := db.Query("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid")
	if err != nil {
		return nil, sqliteErrPrefix(err)
	}
	realm := &schema.Realm{}
	main := &schema.Schema{Name: "main", Realm: realm}
	realm.Schemas = append(realm.Schemas, main)

	type tblInfo struct {
		t   *schema.Table
		sql string
	}
	var infos []*tblInfo
	for _, r := range rows {
		name := valString(r.Vals[0])
		sqlText := valString(r.Vals[1])
		t := &schema.Table{Name: name, Schema: main}
		main.Tables = append(main.Tables, t)
		infos = append(infos, &tblInfo{t: t, sql: sqlText})
	}
	for _, info := range infos {
		if err := inspectTable(db, info.t, info.sql); err != nil {
			return nil, err
		}
	}
	// Second pass: resolve foreign keys (needs all tables for PK resolution).
	for _, info := range infos {
		if err := inspectForeignKeys(db, info.t, main); err != nil {
			return nil, err
		}
	}
	return realm, nil
}

func quoteLit(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}
func quoteIdent(s string) string {
	return "`" + strings.ReplaceAll(s, "`", "``") + "`"
}

func inspectTable(db *sqliteDB, t *schema.Table, createSQL string) error {
	parsed := parseCreateTable(createSQL)
	t.WithoutRowID = parsed.withoutRowID
	t.Strict = parsed.strict
	rows, err := db.Query("PRAGMA table_xinfo(" + quoteLit(t.Name) + ")")
	if err != nil {
		return sqliteErrPrefix(err)
	}
	type pkcol struct {
		col *schema.Column
		pos int64
	}
	var pks []pkcol
	for _, r := range rows {
		// cid, name, type, notnull, dflt_value, pk, hidden
		name := valString(r.Vals[1])
		typ := valString(r.Vals[2])
		notnull := valInt(r.Vals[3], 0)
		var dflt interface{}
		if len(r.Vals) > 4 {
			dflt = r.Vals[4]
		}
		pk := valInt(r.Vals[5], 0)
		hidden := int64(0)
		if len(r.Vals) > 6 {
			hidden = valInt(r.Vals[6], 0)
		}
		col := &schema.Column{Name: name, Type: schema.ColumnType{Raw: typ}, Null: notnull == 0}
		if dflt != nil {
			col.Default = parseDefaultValue(valString(dflt))
		}
		if cd, ok := parsed.columns[name]; ok {
			col.AutoIncrement = cd.autoIncrement
			if cd.generatedExpr != "" {
				gt := "VIRTUAL"
				if cd.generatedType != "" {
					gt = cd.generatedType
				}
				col.Generated = &schema.Generated{Expr: cd.generatedExpr, Type: gt}
			}
			_ = hidden
		}
		t.Columns = append(t.Columns, col)
		if pk > 0 {
			pks = append(pks, pkcol{col: col, pos: pk})
		}
	}
	// sort pk by pos
	for i := 0; i < len(pks); i++ {
		for j := i + 1; j < len(pks); j++ {
			if pks[j].pos < pks[i].pos {
				pks[i], pks[j] = pks[j], pks[i]
			}
		}
	}
	if len(pks) > 0 {
		pkObj := &schema.PrimaryKey{}
		for _, p := range pks {
			pkObj.Parts = append(pkObj.Parts, &schema.IndexPart{Column: p.col})
		}
		t.PrimaryKey = pkObj
	}
	// checks from CREATE TABLE
	for _, expr := range parsed.checks {
		t.Checks = append(t.Checks, &schema.Check{Expr: expr})
	}
	// indexes
	idxRows, err := db.Query("PRAGMA index_list(" + quoteLit(t.Name) + ")")
	if err != nil {
		return sqliteErrPrefix(err)
	}
	type idxInfo struct {
		name, origin string
		unique       bool
		partial      bool
	}
	var idxs []idxInfo
	for _, r := range idxRows {
		// seq, name, unique, origin, partial
		name := valString(r.Vals[1])
		uniq := valInt(r.Vals[2], 0) != 0
		origin := ""
		if len(r.Vals) > 3 {
			origin = valString(r.Vals[3])
		}
		partial := false
		if len(r.Vals) > 4 {
			partial = valInt(r.Vals[4], 0) != 0
		}
		if origin == "pk" {
			continue
		}
		idxs = append(idxs, idxInfo{name: name, origin: origin, unique: uniq, partial: partial})
	}
	for _, ii := range idxs {
		idx := &schema.Index{Name: ii.name, Unique: ii.unique, Table: t}
		xrows, err := db.Query("PRAGMA index_xinfo(" + quoteLit(ii.name) + ")")
		if err != nil {
			return sqliteErrPrefix(err)
		}
		// get index SQL for expressions / where
		var indexSQL string
		srow, ok, _ := db.QueryOne("SELECT sql FROM sqlite_master WHERE type='index' AND name=" + quoteLit(ii.name))
		if ok && len(srow.Vals) > 0 && srow.Vals[0] != nil {
			indexSQL = valString(srow.Vals[0])
		}
		exprParts := parseIndexExprParts(indexSQL) // parallel to columns in definition
		exprIdx := 0
		_ = exprIdx
		partPos := 0
		for _, xr := range xrows {
			// seqno, cid, name, desc, coll, key
			if len(xr.Vals) > 5 && valInt(xr.Vals[5], 1) == 0 {
				continue // auxiliary (e.g. rowid for without rowid PK indexes)
			}
			cid := valInt(xr.Vals[1], -1)
			cname := valString(xr.Vals[2])
			desc := false
			if len(xr.Vals) > 3 {
				desc = valInt(xr.Vals[3], 0) != 0
			}
			part := &schema.IndexPart{Desc: desc}
			if cid == -1 {
				// expression
				if partPos < len(exprParts) {
					part.Expr = exprParts[partPos]
				}
			} else {
				if c := t.Column(cname); c != nil {
					part.Column = c
				} else {
					part.Column = &schema.Column{Name: cname}
				}
			}
			idx.Parts = append(idx.Parts, part)
			partPos++
		}
		if ii.partial {
			idx.Where = parseIndexWhere(indexSQL)
		}
		t.Indexes = append(t.Indexes, idx)
	}
	return nil
}

func inspectForeignKeys(db *sqliteDB, t *schema.Table, sc *schema.Schema) error {
	rows, err := db.Query("PRAGMA foreign_key_list(" + quoteLit(t.Name) + ")")
	if err != nil {
		return sqliteErrPrefix(err)
	}
	type fkGroup struct {
		id                         int64
		refTableName               string
		onUpdate, onDelete         string
		cols, refCols              []string
	}
	var groups []*fkGroup
	byID := map[int64]*fkGroup{}
	for _, r := range rows {
		// id, seq, table, from, to, on_update, on_delete, match
		id := valInt(r.Vals[0], 0)
		g, ok := byID[id]
		if !ok {
			g = &fkGroup{id: id, refTableName: valString(r.Vals[2]), onUpdate: valString(r.Vals[5]), onDelete: valString(r.Vals[6])}
			byID[id] = g
			groups = append(groups, g)
		}
		g.cols = append(g.cols, valString(r.Vals[3]))
		if r.Vals[4] == nil {
			g.refCols = append(g.refCols, "")
		} else {
			g.refCols = append(g.refCols, valString(r.Vals[4]))
		}
	}
	for _, g := range groups {
		fk := &schema.ForeignKey{Symbol: strconv.FormatInt(g.id, 10), OnUpdate: g.onUpdate, OnDelete: g.onDelete, Table: t}
		for _, cn := range g.cols {
			if c := t.Column(cn); c != nil {
				fk.Columns = append(fk.Columns, c)
			} else {
				fk.Columns = append(fk.Columns, &schema.Column{Name: cn})
			}
		}
		rt := sc.Table(g.refTableName)
		fk.RefTable = rt
		for i, rc := range g.refCols {
			name := rc
			if name == "" {
				// resolve to PK of referenced table
				if rt != nil && rt.PrimaryKey != nil && i < len(rt.PrimaryKey.Parts) && rt.PrimaryKey.Parts[i].Column != nil {
					name = rt.PrimaryKey.Parts[i].Column.Name
				} else {
					name = "rowid"
				}
			}
			if rt != nil {
				if c := rt.Column(name); c != nil {
					fk.RefColumns = append(fk.RefColumns, c)
					continue
				}
			}
			fk.RefColumns = append(fk.RefColumns, &schema.Column{Name: name})
		}
		t.ForeignKeys = append(t.ForeignKeys, fk)
	}
	return nil
}

func parseDefaultValue(s string) *schema.DefaultValue {
	if s == "" {
		return nil
	}
	if strings.EqualFold(s, "NULL") {
		return nil
	}
	// string literal
	if len(s) >= 2 && s[0] == '\'' {
		if strings.HasSuffix(s, "'") {
			unq := strings.ReplaceAll(s[1:len(s)-1], "''", "'")
			return &schema.DefaultValue{Kind: "string", Str: unq}
		}
	}
	if strings.EqualFold(s, "true") || strings.EqualFold(s, "false") {
		return &schema.DefaultValue{Kind: "bool", Str: strings.ToLower(s)}
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return &schema.DefaultValue{Kind: "number", Str: s}
	}
	// expression: strip outer parens if balanced and wraps whole
	expr := s
	if strings.HasPrefix(expr, "(") && strings.HasSuffix(expr, ")") && isBalancedWrap(expr) {
		expr = expr[1 : len(expr)-1]
	}
	return &schema.DefaultValue{Kind: "sql", Str: expr}
}

func isBalancedWrap(s string) bool {
	depth := 0
	inStr := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inStr = false
				}
			}
			continue
		}
		switch c {
		case '\'':
			inStr = true
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 && i != len(s)-1 {
				return false
			}
		}
	}
	return depth == 0
}
EOF
