func inspectForeignKeys(db *sqliteDB, t *schema.Table, sc *schema.Schema) error {
	rows, err := db.Query("PRAGMA foreign_key_list(" + quoteLit(t.Name) + ")")
	if err != nil {
		return sqliteErrPrefix(err)
	}
	type fkGroup struct {
		id                         int64
		refTableName               string
		onUpdate, onDelete         string
		cols, refCols              []string
	}
