}

func parseDefaultValue(s string) *schema.DefaultValue {
	if s == "" {
		return nil
	}
	if strings.EqualFold(s, "NULL") {
		return nil
	}
	// string literal
	if len(s) >= 2 && s[0] == '\'' {
		if strings.HasSuffix(s, "'") {
			unq := strings.ReplaceAll(s[1:len(s)-1], "''", "'")
			return &schema.DefaultValue{Kind: "string", Str: unq}
		}
	}
	if strings.EqualFold(s, "true") || strings.EqualFold(s, "false") {
		return &schema.DefaultValue{Kind: "bool", Str: strings.ToLower(s)}
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return &schema.DefaultValue{Kind: "number", Str: s}
	}
	// expression: strip outer parens if balanced and wraps whole
	expr := s
	if strings.HasPrefix(expr, "(") && strings.HasSuffix(expr, ")") && isBalancedWrap(expr) {
		expr = expr[1 : len(expr)-1]
	}
	return &schema.DefaultValue{Kind: "sql", Str: expr}
}

func isBalancedWrap(s string) bool {
	depth := 0
	inStr := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inStr = false
				}
			}
			continue
		}
		switch c {
		case '\'':
			inStr = true
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 && i != len(s)-1 {
				return false
			}
		}
	}
	return depth == 0
}
