{"command":"cat > sqlparse.go <<'EOF'
package main

import (
	"strings"
)

type sqlTok struct {
	raw, upper, val string
	kind            string // ident, qident, string, number, symbol, word
	start, end      int
}

func tokenizeSQL(s string) []sqlTok {
	var toks []sqlTok
	i := 0
	for i < len(s) {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		if c == '-' && i+1 < len(s) && s[i+1] == '-' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			continue
		}
		if c == '/' && i+1 < len(s) && s[i+1] == '*' {
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				break
			}
			i += 2 + j + 2
			continue
		}
		start := i
		if c == '\'' || c == '"' || c == '`' || c == '[' {
			closeCh := c
			if c == '[' {
				closeCh = ']'
			}
			i++
			var val strings.Builder
			for i < len(s) {
				if s[i] == closeCh {
					if i+1 < len(s) && s[i+1] == closeCh && c != '[' {
						val.WriteByte(closeCh)
						i += 2
						continue
					}
					i++
					break
				}
				val.WriteByte(s[i])
				i++
			}
			kind := "string"
			if c != '\'' {
				kind = "qident"
			}
			toks = append(toks, sqlTok{raw: s[start:i], upper: strings.ToUpper(s[start:i]), val: val.String(), kind: kind, start: start, end: i})
			continue
		}
		if isIdentStart(c) {
			for i < len(s) && (isIdentChar(s[i]) || s[i] == '$') {
				i++
			}
			raw := s[start:i]
			toks = append(toks, sqlTok{raw: raw, upper: strings.ToUpper(raw), val: raw, kind: "word", start: start, end: i})
			continue
		}
		if isDigit(c) {
			for i < len(s) && (isDigit(s[i]) || s[i] == '.' || s[i] == 'e' || s[i] == 'E' || s[i] == '+' || s[i] == '-') {
				// simplistic
				if (s[i] == '+' || s[i] == '-') && !(i > start && (s[i-1] == 'e' || s[i-1] == 'E')) {
					break
				}
				i++
			}
			raw := s[start:i]
			toks = append(toks, sqlTok{raw: raw, upper: raw, val: raw, kind: "number", start: start, end: i})
			continue
		}
		// symbol (single char, combine some operators)
		i++
		if i < len(s) && strings.ContainsRune("=<>!", rune(c)) && s[i] == '=' {
			i++
		} else if c == '<' && i < len(s) && s[i] == '>' {
			i++
		}
		raw := s[start:i]
		toks = append(toks, sqlTok{raw: raw, upper: raw, val: raw, kind: "symbol", start: start, end: i})
	}
	return toks
}

// splitTopLevel splits token slice by commas at paren depth 0.
func splitTopLevel(toks []sqlTok) [][]sqlTok {
	var parts [][]sqlTok
	var cur []sqlTok
	depth := 0
	for _, t := range toks {
		if t.raw == "(" {
			depth++
		} else if t.raw == ")" {
			depth--
		}
		if t.raw == "," && depth == 0 {
			parts = append(parts, cur)
			cur = nil
			continue
		}
		cur = append(cur, t)
	}
	if len(cur) > 0 || len(parts) == 0 {
		parts = append(parts, cur)
	}
	return parts
}

type parsedColumn struct {
	autoIncrement bool
	generatedExpr string
	generatedType string
}
type parsedCreateTable struct {
	columns      map[string]*parsedColumn
	checks       []string
	withoutRowID bool
	strict       bool
}

func rawSlice(s string, toks []sqlTok) string {
	if len(toks) == 0 {
		return ""
	}
	return strings.TrimSpace(s[toks[0].start:toks[len(toks)-1].end])
}

// findMatchingParen returns index of matching ')' for '(' at idx.
func findMatching(toks []sqlTok, idx int) int {
	depth := 0
	for i := idx; i < len(toks); i++ {
		if toks[i].raw == "(" {
			depth++
		} else if toks[i].raw == ")" {
			depth--
			if depth == 0 {
				return i
			}
		}
	}
	return -1
}

func parseCreateTable(sql string) *parsedCreateTable {
	res := &parsedCreateTable{columns: map[string]*parsedColumn{}}
	if strings.TrimSpace(sql) == "" {
		return res
	}
	toks := tokenizeSQL(sql)
	// find first '('
	open := -1
	for i, t := range toks {
		if t.raw == "(" {
			open = i
			break
		}
	}
	if open < 0 {
		return res
	}
	closeI := findMatching(toks, open)
	if closeI < 0 {
		closeI = len(toks)
	}
	// suffix keywords
	for _, t := range toks[closeI+1:] {
		if t.upper == "WITHOUT" || t.upper == "ROWID" {
			res.withoutRowID = true
		}
		if t.upper == "STRICT" {
			res.strict = true
		}
	}
	inside := toks[open+1 : closeI]
	parts := splitTopLevel(inside)
	for _, part := range parts {
		if len(part) == 0 {
			continue
		}
		first := part[0]
		// constraint keywords
		isConstraint := false
		switch first.upper {
		case "PRIMARY", "FOREIGN", "UNIQUE", "CONSTRAINT", "CHECK":
			isConstraint = true
		}
		// find CHECK at top level (depth tracked)
		for i := 0; i < len(part); i++ {
			if part[i].upper == "CHECK" && i+1 < len(part) && part[i+1].raw == "(" {
				m := findMatching(part, i+1)
				if m > i+1 {
