					if part[j].upper == "STORED" || part[j].upper == "VIRTUAL" {
						typ = part[j].upper
						break
					}
					exprToks = append(exprToks, part[j])
				}
				pc.generatedExpr = rawSlice(sql, exprToks)
				pc.generatedType = typ
			}
		}
		res.columns[colName] = pc
	}
	return res
}

func parseIndexExprParts(sql string) []string {
	if strings.TrimSpace(sql) == "" {
		return nil
	}
	toks := tokenizeSQL(sql)
	open := -1
	for i, t := range toks {
		if t.raw == "(" {
			open = i
			break
		}
	}
	if open < 0 {
		return nil
	}
	closeI := findMatching(toks, open)
	if closeI < 0 {
		closeI = len(toks)
	}
	parts := splitTopLevel(toks[open+1 : closeI])
	var out []string
	for _, part := range parts {
		// strip trailing ASC/DESC/COLLATE x
		for len(part) > 0 {
			last := part[len(part)-1]
			if last.upper == "DESC" || last.upper == "ASC" {
				part = part[:len(part)-1]
				continue
			}
			if len(part) >= 2 && part[len(part)-2].upper == "COLLATE" {
				part = part[:len(part)-2]
				continue
			}
			break
		}
		out = append(out, rawSlice(sql, part))
	}
	return out
}

func parseIndexWhere(sql string) string {
	if strings.TrimSpace(sql) == "" {
		return ""
	}
	toks := tokenizeSQL(sql)
	// find closing paren of column list, then WHERE at depth 0 after it
	open := -1
	for i, t := range toks {
		if t.raw == "(" {
			open = i
			break
		}
	}
	if open < 0 {
		return ""
	}
	closeI := findMatching(toks, open)
	if closeI < 0 {
		return ""
	}
	for i := closeI + 1; i < len(toks); i++ {
		if toks[i].upper == "WHERE" {
			return rawSlice(sql, toks[i+1:])
		}
	}
	return ""
}

// splitSQLStatements splits a SQL script into statements by ';' respecting
// strings, quoted identifiers and comments. Returned statements include
// their trailing semicolon if present (trimmed of surrounding whitespace
// and comments are preserved in raw form where feasible).
func splitSQLStatements(script string) []string {
	var stmts []string
	var cur strings.Builder
	i := 0
	s := script
	flush := func() {
		txt := strings.TrimSpace(cur.String())
		cur.Reset()
		if txt != "" {
			stmts = append(stmts, txt)
		}
	}
	for i < len(s) {
		c := s[i]
		if c == '\'' || c == '"' || c == '`' {
			// copy quoted
			cur.WriteByte(c)
			i++
			for i < len(s) {
				cur.WriteByte(s[i])
				if s[i] == c {
					if i+1 < len(s) && s[i+1] == c {
						cur.WriteByte(s[i+1])
						i += 2
						continue
					}
					i++
					break
				}
				i++
			}
			continue
		}
		if c == '[' {
			for i < len(s) {
				cur.WriteByte(s[i])
				if s[i] == ']' {
					i++
					break
				}
				i++
			}
			continue
		}
		if c == '-' && i+1 < len(s) && s[i+1] == '-' {
			for i < len(s) && s[i] != '\n' {
				cur.WriteByte(s[i])
				i++
			}
			continue
		}
		if c == '/' && i+1 < len(s) && s[i+1] == '*' {
			for i < len(s) {
				cur.WriteByte(s[i])
				if s[i] == '*' && i+1 < len(s) && s[i+1] == '/' {
					cur.WriteByte('/')
					i += 2
					break
				}
				i++
			}
			continue
		}
		if c == ';' {
			cur.WriteByte(c)
			i++
			flush()
			continue
		}
		cur.WriteByte(c)
		i++
	}
	flush()
	return stmts
}

// statementTextForError returns the statement text as Atlas presents it in
// errors: it ensures a trailing semicolon (?) Our callers prepare statements
// consistently.
EOF
"}

