package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"atlas/schema"
)

// ---------- HCL type conversion ----------

var hclKnownTypes = map[string]bool{
	"tinyint": true, "smallint": true, "mediumint": true, "int": true, "integer": true,
	"bigint": true, "int2": true, "int8": true, "float": true, "double": true,
	"double_precision": true, "real": true, "decimal": true, "numeric": true,
	"boolean": true, "bool": true, "varchar": true, "character": true,
	"native_character": true, "varying_character": true, "nchar": true, "nvarchar": true,
	"text": true, "clob": true, "blob": true, "date": true, "datetime": true,
	"json": true, "uuid": true, "unsigned_big_int": true,
}

var hclSizeTypes = map[string]bool{
	"varchar": true, "character": true, "native_character": true, "varying_character": true,
	"nchar": true, "nvarchar": true, "text": true, "clob": true,
}

// hclTypeExpr returns the HCL expression for a column type (e.g. `varchar(20)`, `sql("char")`).
func hclTypeExpr(raw string) string {
	if raw == "" {
		return `sql("")`
	}
	base, size := splitTypeSize(raw)
	canon := strings.ReplaceAll(strings.ToLower(strings.TrimSpace(base)), " ", "_")
	// collapse multiple underscores/spaces
	for strings.Contains(canon, "__") {
		canon = strings.ReplaceAll(canon, "__", "_")
	}
	if hclKnownTypes[canon] {
		if size != "" {
			parts := splitSizeParts(size)
			if canon == "decimal" || canon == "numeric" {
				return fmt.Sprintf("%s(%s)", canon, strings.Join(parts, ","))
			}
			if hclSizeTypes[canon] && len(parts) > 0 {
				return fmt.Sprintf("%s(%s)", canon, parts[0])
			}
		}
		return canon
	}
	if canon == "char" {
		return `sql("char")`
	}
	return "sql(" + strconv.Quote(raw) + ")"
}

func splitTypeSize(raw string) (string, string) {
	i := strings.Index(raw, "(")
	if i < 0 {
		return raw, ""
	}
	j := strings.LastIndex(raw, ")")
	if j < i {
		return raw, ""
	}
	return raw[:i], raw[i+1 : j]
}

func splitSizeParts(size string) []string {
	var parts []string
	for _, p := range strings.Split(size, ",") {
		parts = append(parts, strings.TrimSpace(p))
	}
	return parts
}

// sqlTypeName returns the SQL type name as used in CREATE TABLE statements:
// lowercase except custom types preserved, sizes stripped.
func sqlTypeName(raw string) string {
	if raw == "" {
		return ""
	}
	base, _ := splitTypeSize(raw)
	base = strings.TrimSpace(base)
	// Known types are lowercased; unknown/custom preserve case.
	canon := strings.ReplaceAll(strings.ToLower(base), " ", "_")
	if hclKnownTypes[canon] || canon == "char" {
		return strings.ToLower(base)
	}
	// For types rendered as sql("char") etc the sql name is base as stored.
	// For multiword known-ish (double precision), base is lowercase already if known.
	return base
}

// ---------- HCL generation ----------

type hclLine struct {
	text string
	// for attribute alignment: key and value (if attr)
	isAttr   bool
	key, val string
	indent   int
}

type hclBlockWriter struct {
	lines []hclLine
}

func (w *hclBlockWriter) line(indent int, text string) {
	w.lines = append(w.lines, hclLine{text: text, indent: indent})
}
func (w *hclBlockWriter) attr(indent int, key, val string) {
	w.lines = append(w.lines, hclLine{isAttr: true, key: key, val: val, indent: indent})
}
func (w *hclBlockWriter) blank() {
	w.lines = append(w.lines, hclLine{text: "", indent: -1})
}

func (w *hclBlockWriter) render() string {
	// align consecutive attrs at same indent
	var out []string
	i := 0
	for i < len(w.lines) {
		ln := w.lines[i]
		if !ln.isAttr {
			out = append(out, ln.text)
			i++
			continue
		}
		// group
		j := i
		maxKey := 0
		for j < len(w.lines) && w.lines[j].isAttr && w.lines[j].indent == ln.indent {
			if len(w.lines[j].key) > maxKey {
				maxKey = len(w.lines[j].key)
			}
			j++
		}
		for k := i; k < j; k++ {
			a := w.lines[k]
			pad := strings.Repeat(" ", maxKey-len(a.key))
			out = append(out, strings.Repeat("  ", a.indent)+a.key+pad+" = "+a.val)
		}
		i = j
	}
	return strings.Join(out, "\n")
}

func quoteHCL(s string) string { return strconv.Quote(s) }

func realmToHCL(r *schema.Realm) string {
	if r == nil {
		return ""
	}
	var blocks []string
	// Tables first (schema order, table order), then schema blocks.
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			blocks = append(blocks, tableToHCL(t))
		}
	}
	for _, s := range r.Schemas {
		blocks = append(blocks, schemaToHCL(s))
	}
	if len(blocks) == 0 {
		return ""
	}
	return strings.Join(blocks, "\n") + "\n"
}

func schemaToHCL(s *schema.Schema) string {
	w := &hclBlockWriter{}
	w.line(0, fmt.Sprintf("schema %s {", quoteHCL(s.Name)))
	w.line(0, "}")
	return w.render()
}

func tableToHCL(t *schema.Table) string {
	// We build manually with nested writers because alignment groups
	// are local to each block.
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("table %s {\n", quoteHCL(t.Name)))
	// schema attr
	sb.WriteString(fmt.Sprintf("  schema = schema.%s\n", t.Schema.Name))
	for _, c := range t.Columns {
		sb.WriteString(columnToHCL(c, 1))
	}
	if t.PrimaryKey != nil {
		sb.WriteString("  primary_key {\n")
		cols := make([]string, 0, len(t.PrimaryKey.Parts))
		for _, p := range t.PrimaryKey.Parts {
			if p.Column != nil {
				cols = append(cols, "column."+p.Column.Name)
			}
		}
		sb.WriteString(fmt.Sprintf("    columns = [%s]\n", strings.Join(cols, ", ")))
		sb.WriteString("  }\n")
	}
	for _, fk := range t.ForeignKeys {
		sb.WriteString(foreignKeyToHCL(fk, 1))
	}
	for _, idx := range t.Indexes {
		sb.WriteString(indexToHCL(t, idx, 1))
	}
	for _, chk := range t.Checks {
		sb.WriteString("  check {\n")
		// attr alignment single
		sb.WriteString(fmt.Sprintf("    expr = %s\n", quoteHCL(chk.Expr)))
		sb.WriteString("  }\n")
	}
	// table attrs after blocks, aligned as a group if both present
	var attrs []hclLine
	if t.WithoutRowID {
		attrs = append(attrs, hclLine{isAttr: true, key: "without_rowid", val: "true", indent: 1})
	}
	if t.Strict {
		attrs = append(attrs, hclLine{isAttr: true, key: "strict", val: "true", indent: 1})
	}
	if len(attrs) > 0 {
		maxKey := 0
		for _, a := range attrs {
			if len(a.key) > maxKey {
				maxKey = len(a.key)
			}
		}
		for _, a := range attrs {
			sb.WriteString("  " + a.key + strings.Repeat(" ", maxKey-len(a.key)) + " = " + a.val + "\n")
		}
	}
	sb.WriteString("}")
	return sb.String()
}

func columnToHCL(c *schema.Column, indent int) string {
	pad := strings.Repeat("  ", indent)
	inner := strings.Repeat("  ", indent+1)
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("%scolumn %s {\n", pad, quoteHCL(c.Name)))
	// attribute group: null, type, default, auto_increment
	var attrs []hclLine
	attrs = append(attrs, hclLine{isAttr: true, key: "null", val: fmt.Sprintf("%v", c.Null)})
	attrs = append(attrs, hclLine{isAttr: true, key: "type", val: hclTypeExpr(c.Type.Raw)})
	if c.Default != nil {
		attrs = append(attrs, hclLine{isAttr: true, key: "default", val: defaultHCLValue(c.Default)})
	}
	if c.AutoIncrement {
		attrs = append(attrs, hclLine{isAttr: true, key: "auto_increment", val: "true"})
	}
	maxKey := 0
	for _, a := range attrs {
		if len(a.key) > maxKey {
			maxKey = len(a.key)
		}
	}
	for _, a := range attrs {
		sb.WriteString(inner + a.key + strings.Repeat(" ", maxKey-len(a.key)) + " = " + a.val + "\n")
	}
	if c.Generated != nil {
		sb.WriteString(inner + "as {\n")
		// attrs expr, type aligned
		ga := []hclLine{{isAttr: true, key: "expr", val: quoteHCL(c.Generated.Expr)}, {isAttr: true, key: "type", val: c.Generated.Type}}
		mk := 0
		for _, a := range ga {
			if len(a.key) > mk {
				mk = len(a.key)
			}
		}
		for _, a := range ga {
			sb.WriteString(inner + "  " + a.key + strings.Repeat(" ", mk-len(a.key)) + " = " + a.val + "\n")
		}
		sb.WriteString(inner + "}\n")
	}
	sb.WriteString(pad + "}\n")
	return sb.String()
}

func defaultHCLValue(d *schema.DefaultValue) string {
	switch d.Kind {
	case "string":
		return quoteHCL(d.Str)
	case "sql":
		return "sql(" + quoteHCL(d.Str) + ")"
	default:
		return d.Str
	}
}

func foreignKeyToHCL(fk *schema.ForeignKey, indent int) string {
	pad := strings.Repeat("  ", indent)
	inner := strings.Repeat("  ", indent+1)
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("%sforeign_key %s {\n", pad, quoteHCL(fk.Symbol)))
	cols := make([]string, 0, len(fk.Columns))
	for _, c := range fk.Columns {
		cols = append(cols, "column."+c.Name)
	}
	refTable := ""
	if fk.RefTable != nil {
		refTable = fk.RefTable.Name
	}
	refCols := make([]string, 0, len(fk.RefColumns))
	for _, c := range fk.RefColumns {
		refCols = append(refCols, fmt.Sprintf("table.%s.column.%s", refTable, c.Name))
	}
	attrs := []hclLine{
		{isAttr: true, key: "columns", val: "[" + strings.Join(cols, ", ") + "]"},
		{isAttr: true, key: "ref_columns", val: "[" + strings.Join(refCols, ", ") + "]"},
		{isAttr: true, key: "on_update", val: fk.OnUpdate},
		{isAttr: true, key: "on_delete", val: fk.OnDelete},
	}
	mk := 0
	for _, a := range attrs {
		if len(a.key) > mk {
			mk = len(a.key)
		}
	}
	for _, a := range attrs {
		sb.WriteString(inner + a.key + strings.Repeat(" ", mk-len(a.key)) + " = " + a.val + "\n")
	}
	sb.WriteString(pad + "}\n")
	return sb.String()
}

func indexToHCL(t *schema.Table, idx *schema.Index, indent int) string {
	pad := strings.Repeat("  ", indent)
	inner := strings.Repeat("  ", indent+1)
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("%sindex %s {\n", pad, quoteHCL(idx.Name)))
	// decide representation
	useOn := false
	for _, p := range idx.Parts {
		if p.Expr != "" || p.Desc {
			useOn = true
		}
	}
	var attrs []hclLine
	if idx.Unique {
		attrs = append(attrs, hclLine{isAttr: true, key: "unique", val: "true"})
	}
	if !useOn {
		cols := make([]string, 0, len(idx.Parts))
		for _, p := range idx.Parts {
			if p.Column != nil {
				cols = append(cols, "column."+p.Column.Name)
			}
		}
		attrs = append(attrs, hclLine{isAttr: true, key: "columns", val: "[" + strings.Join(cols, ", ") + "]"})
		if idx.Where != "" {
			attrs = append(attrs, hclLine{isAttr: true, key: "where", val: quoteHCL(idx.Where)})
		}
		mk := 0
		for _, a := range attrs {
			if len(a.key) > mk {
				mk = len(a.key)
			}
		}
		for _, a := range attrs {
			sb.WriteString(inner + a.key + strings.Repeat(" ", mk-len(a.key)) + " = " + a.val + "\n")
		}
	} else {
		// unique attr first (its own group unless followed by attrs; in
		// observed output unique stands alone before on blocks)
		for _, a := range attrs {
			sb.WriteString(inner + a.key + " = " + a.val + "\n")
		}
		for _, p := range idx.Parts {
			sb.WriteString(inner + "on {\n")
			var pa []hclLine
			if p.Expr != "" {
				pa = append(pa, hclLine{isAttr: true, key: "expr", val: quoteHCL(p.Expr)})
			} else {
				if p.Desc {
					pa = append(pa, hclLine{isAttr: true, key: "desc", val: "true"})
				}
				if p.Column != nil {
					pa = append(pa, hclLine{isAttr: true, key: "column", val: "column." + p.Column.Name})
				}
			}
			mk := 0
			for _, a := range pa {
				if len(a.key) > mk {
					mk = len(a.key)
				}
			}
			for _, a := range pa {
				sb.WriteString(inner + "  " + a.key + strings.Repeat(" ", mk-len(a.key)) + " = " + a.val + "\n")
			}
			sb.WriteString(inner + "}\n")
		}
		if idx.Where != "" {
			sb.WriteString(inner + "where = " + quoteHCL(idx.Where) + "\n")
		}
	}
	sb.WriteString(pad + "}\n")
	return sb.String()
}

var _ = sort.Strings
EOF
"}

