// inner expression; strings stored unquoted.

func columnSQL(c *schema.Column, t *schema.Table) string {
	var sb strings.Builder
	sb.WriteString(quoteSQLIdent(c.Name))
	typ := sqlTypeName(c.Type.Raw)
	if typ == "" {
		typ = "blob"
	}
	sb.WriteString(" " + typ)
	if c.Null {
		sb.WriteString(" NULL")
	} else {
		sb.WriteString(" NOT NULL")
	}
	if c.Default != nil {
		sb.WriteString(" DEFAULT " + sqlDefault(c.Default))
	}
