	if c.AutoIncrement {
		sb.WriteString(" PRIMARY KEY AUTOINCREMENT")
	}
	if c.Generated != nil {
		expr := stripOuterParens(c.Generated.Expr)
		sb.WriteString(" AS (" + expr + ") " + c.Generated.Type)
	}
	return sb.String()
}

func stripOuterParens(s string) string {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "(") && strings.HasSuffix(s, ")") && isBalancedWrap(s) {
		return s[1 : len(s)-1]
	}
	return s
