	b.WriteString(stmt[:i+1])
	b.WriteString("\n")
	for idx, d := range defs {
		b.WriteString(indent + strings.TrimSpace(d))
		if idx < len(defs)-1 {
			b.WriteString(",")
		}
		b.WriteString("\n")
	}
	b.WriteString(")")
	if j+1 < len(stmt) {
		b.WriteString(stmt[j+1:])
	}
	return b.String()
}

func splitSQLCommaList(s string) []string {
	var parts []string
	depth := 0
	inStr := false
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
