	c := t.PrimaryKey.Parts[0].Column
	return c.AutoIncrement
}

// createTableSQL returns CREATE TABLE statement without trailing semicolon.
func createTableSQL(t *schema.Table, nameOverride string) string {
	name := t.Name
	if nameOverride != "" {
		name = nameOverride
	}
	var defs []string
	for _, c := range t.Columns {
		defs = append(defs, columnSQL(c, t))
	}
	if t.PrimaryKey != nil && !isSinglePKAutoIncrement(t) && len(t.PrimaryKey.Parts) > 0 {
		var cols []string
		for _, p := range t.PrimaryKey.Parts {
			if p.Column != nil {
				cols = append(cols, quoteSQLIdent(p.Column.Name))
			} else if p.Expr != "" {
				cols = append(cols, p.Expr)
			}
		}
		defs = append(defs, "PRIMARY KEY ("+strings.Join(cols, ", ")+")")
	}
	// If a single PK column is autoincrement but PrimaryKey not set (from HCL auto_increment alone),
	// columnSQL already emitted PRIMARY KEY AUTOINCREMENT.
	for _, fk := range t.ForeignKeys {
		var cols, refCols []string
		for _, c := range fk.Columns {
			cols = append(cols, quoteSQLIdent(c.Name))
		}
		for _, c := range fk.RefColumns {
			refCols = append(refCols, quoteSQLIdent(c.Name))
		}
		refTable := ""
		if fk.RefTable != nil {
			refTable = fk.RefTable.Name
		}
		onUpdate := fk.OnUpdate
		if onUpdate == "" {
			onUpdate = "NO ACTION"
		}
		onDelete := fk.OnDelete
		if onDelete == "" {
			onDelete = "NO ACTION"
		}
		// SQL uses underscores in actions? sqlite accepts NO ACTION / SET NULL etc with spaces.
		defs = append(defs, fmt.Sprintf("CONSTRAINT %s FOREIGN KEY (%s) REFERENCES %s (%s) ON UPDATE %s ON DELETE %s",
			quoteSQLIdent(fk.Symbol), strings.Join(cols, ", "), quoteSQLIdent(refTable), strings.Join(refCols, ", "), sqlAction(onUpdate), sqlAction(onDelete)))
	}
	for _, chk := range t.Checks {
		defs = append(defs, "CHECK ("+stripOuterParens(chk.Expr)+")")
	}
	stmt := fmt.Sprintf("CREATE TABLE %s (%s)", quoteSQLIdent(name), strings.Join(defs, ", "))
	var suffix []string
	if t.WithoutRowID {
		suffix = append(suffix, "WITHOUT ROWID")
	}
	if t.Strict {
		suffix = append(suffix, "STRICT")
	}
	if len(suffix) > 0 {
		stmt += " " + strings.Join(suffix, ", ")
	}
	return stmt
}

func sqlAction(a string) string {
	// FK actions in HCL are NO_ACTION, SET_NULL, etc; in SQL they are spaced.
	return strings.ReplaceAll(a, "_", " ")
}

func indexSQLName(t *schema.Table, idx *schema.Index) string {
	if strings.HasPrefix(idx.Name, "sqlite_autoindex_") {
		var cols []string
		for _, p := range idx.Parts {
			if p.Column != nil {
				cols = append(cols, p.Column.Name)
			}
		}
		return t.Name + "_" + strings.Join(cols, "_")
	}
	return idx.Name
}

func createIndexSQL(t *schema.Table, idx *schema.Index) string {
	var parts []string
	for _, p := range idx.Parts {
		var s string
		if p.Expr != "" {
			s = p.Expr
		} else if p.Column != nil {
			s = quoteSQLIdent(p.Column.Name)
		}
		if p.Desc {
			s += " DESC"
		}
		parts = append(parts, s)
	}
	uniq := ""
	if idx.Unique {
		uniq = "UNIQUE "
	}
	stmt := fmt.Sprintf("CREATE %sINDEX %s ON %s (%s)", uniq, quoteSQLIdent(indexSQLName(t, idx)), quoteSQLIdent(t.Name), strings.Join(parts, ", "))
	if idx.Where != "" {
		stmt += " WHERE " + idx.Where
	}
	return stmt
}

// realmToSQLChanges: generate migrate changes for creating all tables in a realm
// (used for `sql` template function on inspect).
func realmSQLPlan(r *schema.Realm, indent string) []*migrate.Change {
	var changes []*migrate.Change
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			changes = append(changes, &migrate.Change{
				Cmd:     formatCreateTableForPlan(createTableSQL(t, ""), indent),
				Comment: fmt.Sprintf("create %q table", t.Name),
				Reverse: "DROP TABLE " + quoteSQLIdent(t.Name),
			})
			for _, idx := range t.Indexes {
				changes = append(changes, &migrate.Change{
					Cmd:     createIndexSQL(t, idx),
					Comment: fmt.Sprintf("create index %q to table: %q", indexSQLName(t, idx), t.Name),
					Reverse: "DROP INDEX " + quoteSQLIdent(indexSQLName(t, idx)),
				})
			}
		}
	}
	return changes
}

// formatCreateTableForPlan: if indent is empty, statement stays on one line;
// otherwise CREATE TABLE is broken with each definition on its own line indented.
func formatCreateTableForPlan(stmt, indent string) string {
	if indent == "" {
		return stmt
	}
	// Only reformat CREATE TABLE ... (a, b, c) [suffix]
	i := strings.Index(stmt, "(")
	j := strings.LastIndex(stmt, ")")
	if i < 0 || j < i || !strings.HasPrefix(stmt, "CREATE TABLE") {
		return stmt
	}
	inside := stmt[i+1 : j]
	defs := splitSQLCommaList(inside)
	var b strings.Builder
	b.WriteString(stmt[:i+1])
	b.WriteString("\n")
	for idx, d := range defs {
		b.WriteString(indent + strings.TrimSpace(d))
		if idx < len(defs)-1 {
			b.WriteString(",")
		}
		b.WriteString("\n")
	}
	b.WriteString(")")
	if j+1 < len(stmt) {
		b.WriteString(stmt[j+1:])
	}
	return b.String()
}

func splitSQLCommaList(s string) []string {
	var parts []string
	depth := 0
	inStr := false
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inStr = false
				}
			}
			continue
		}
		switch c {
		case '\'':
			inStr = true
		case '(':
			depth++
		case ')':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, s[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, s[start:])
	return parts
}

// planToSQLText formats a list of changes as the plan SQL text:
// each change preceded by "-- <Title comment>" and terminated with ;
// separated by blank lines? Our callers decide final layout. This function
// returns the statements in the form used by schema diff (no header):
//   -- Comment\n<stmt>;\n\n  (joined)
func changesToSQLText(changes []*migrate.Change, indent string) string {
	var sb strings.Builder
	for _, ch := range changes {
		comment := commentTitle(ch.Comment)
		if comment != "" {
			sb.WriteString("-- " + comment + "\n")
		}
		cmd := ch.Cmd
		if indent != "" {
			cmd = formatCreateTableForPlan(cmd, indent)
		}
		sb.WriteString(cmd + ";\n")
		// blank line between? Observed outputs have a blank line after each statement block.
		sb.WriteString("\n")
	}
	// The observed output ends with a blank line after the last statement
	// (i.e. ";\n\n" then EOF?) we check via callers trimming.
	return sb.String()
}

// commentTitle capitalizes first letter of a comment phrase and formats
// table/index creation comments specially are already handled by callers
// storing Title-style comments? We store comments lowercase for migrate.Change
// (as in template). For SQL text we need Title form used by Atlas:
// e.g. "create \"users\" table", "drop \"old\" table", "add column ...".
// Atlas prints those with first letter capitalized and create/drop table
// phrasing as stored in our Comment (we store title-case for plan comments
// in some paths). To keep consistent, callers set Comment as lowercase
// phrase and here we capitalize first letter.
func commentTitle(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = []rune(strings.ToUpper(string(r[0])))[0]
	return string(r)
}

var _ = strconv.Quote
EOF
"}

