package main

import (
	"fmt"
	"strings"

	"atlas/migrate"
	"atlas/schema"
)

// canonical type family for comparison purposes
func compareType(raw string) string {
	if raw == "" {
		return "blob"
	}
	base, _ := splitTypeSize(raw)
	canon := strings.ToLower(strings.TrimSpace(base))
	canon = strings.Join(strings.Fields(canon), "_")
	switch canon {
	case "tinyint", "smallint", "mediumint", "int", "integer", "bigint", "int2", "int8":
		return "integer"
	case "text", "varchar", "character", "native_character", "varying_character", "character_varying", "nchar", "nvarchar", "clob", "char":
		return "text"
	case "real", "float", "double", "double_precision":
		return "real"
	case "decimal", "numeric":
		return "decimal"
	case "boolean", "bool":
		return "boolean"
	case "date", "datetime":
		return "date"
	case "blob":
		return "blob"
	}
	// unknown types: compare full raw normalized (lower case for known words?)
	return strings.ToLower(strings.TrimSpace(raw))
}

func defaultsEqual(a, b *schema.DefaultValue) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	if a.Kind != b.Kind {
		// numeric / bool textual comparison maybe across kinds sql vs number?
		// If one is sql with same literal as number, treat similarly.
		return a.Str == b.Str
	}
	if a.Kind == "sql" {
		return stripOuterParens(a.Str) == stripOuterParens(b.Str)
	}
	return a.Str == b.Str
}

func columnsEqual(a, b *schema.Column) bool {
	if compareType(a.Type.Raw) != compareType(b.Type.Raw) {
		return false
	}
	if a.Null != b.Null {
		return false
	}
	if !defaultsEqual(a.Default, b.Default) {
		return false
	}
	if a.AutoIncrement != b.AutoIncrement {
		return false
	}
	if (a.Generated == nil) != (b.Generated == nil) {
		return false
	}
	if a.Generated != nil && b.Generated != nil {
		if stripOuterParens(a.Generated.Expr) != stripOuterParens(b.Generated.Expr) || a.Generated.Type != b.Generated.Type {
			return false
		}
	}
	return true
}

func pkColumnNames(t *schema.Table) []string {
	if t == nil || t.PrimaryKey == nil {
		// If table has an autoincrement single column declared without explicit PK?
		for _, c := range t.Columns {
			if c.AutoIncrement {
				return []string{c.Name}
			}
		}
		return nil
	}
	var names []string
	for _, p := range t.PrimaryKey.Parts {
		if p.Column != nil {
			names = append(names, p.Column.Name)
		}
	}
	return names
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func indexPartsEqual(a, b *schema.Index) bool {
	if len(a.Parts) != len(b.Parts) {
		return false
	}
	for i := range a.Parts {
		pa, pb := a.Parts[i], b.Parts[i]
		if pa.Desc != pb.Desc {
			return false
		}
		if normalizeExpr(pa.Expr) != normalizeExpr(pb.Expr) {
			return false
		}
		an, bn := "", ""
		if pa.Column != nil {
			an = pa.Column.Name
		}
		if pb.Column != nil {
			bn = pb.Column.Name
		}
		if an != bn {
			return false
		}
	}
	return true
}

func normalizeExpr(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

func indexesEqual(a, b *schema.Index) bool {
	return a.Unique == b.Unique && indexPartsEqual(a, b) && normalizeExpr(a.Where) == normalizeExpr(b.Where)
}

func fkEqual(a, b *schema.ForeignKey) bool {
	var ac, bc, ar, br []string
	for _, c := range a.Columns {
		ac = append(ac, c.Name)
	}
	for _, c := range b.Columns {
		bc = append(bc, c.Name)
	}
	for _, c := range a.RefColumns {
		ar = append(ar, c.Name)
	}
	for _, c := range b.RefColumns {
		br = append(br, c.Name)
	}
	at, bt := "", ""
	if a.RefTable != nil {
		at = a.RefTable.Name
	}
	if b.RefTable != nil {
		bt = b.RefTable.Name
	}
	return equalStrings(ac, bc) && equalStrings(ar, br) && at == bt && sqlAction(a.OnUpdate) == sqlAction(b.OnUpdate) && sqlAction(a.OnDelete) == sqlAction(b.OnDelete)
}

// tableChanges computes sub-changes from current (from) to desired (to).
// It returns the list and whether the table needs recreation as a whole.
func tableSubChanges(from, to *schema.Table) ([]schema.Change, bool) {
	var changes []schema.Change
	recreate := false
	// columns
	fromCols := map[string]*schema.Column{}
	for _, c := range from.Columns {
		fromCols[c.Name] = c
	}
	toCols := map[string]*schema.Column{}
	for _, c := range to.Columns {
		toCols[c.Name] = c
	}
	// Added / modified in desired order
	for _, c := range to.Columns {
		fc, ok := fromCols[c.Name]
		if !ok {
			changes = append(changes, &schema.AddColumn{T: to, C: c})
			if c.Generated != nil {
				recreate = true
			}
			continue
		}
		if !columnsEqual(fc, c) {
			changes = append(changes, &schema.ModifyColumn{T: to, C: c})
			recreate = true
		}
	}
	for _, c := range from.Columns {
		if _, ok := toCols[c.Name]; !ok {
			changes = append(changes, &schema.DropColumn{T: from, C: c})
			recreate = true
		}
	}
	// primary key
	if !equalStrings(pkColumnNames(from), pkColumnNames(to)) {
		// Represent as ModifyColumn-ish; recreation is what matters.
		recreate = true
		changes = append(changes, &schema.ModifyColumn{T: to, C: nil})
	}
	// indexes (by name)
	fromIdx := map[string]*schema.Index{}
	for _, idx := range from.Indexes {
		fromIdx[idx.Name] = idx
	}
	toIdx := map[string]*schema.Index{}
	for _, idx := range to.Indexes {
		toIdx[idx.Name] = idx
	}
	for _, idx := range to.Indexes {
		fi, ok := fromIdx[idx.Name]
		if !ok {
			changes = append(changes, &schema.AddIndex{T: to, I: idx})
		} else if !indexesEqual(fi, idx) {
			changes = append(changes, &schema.ModifyIndex{T: to, From: fi, To: idx})
			recreate = true
		}
	}
	for _, idx := range from.Indexes {
		if _, ok := toIdx[idx.Name]; !ok {
			changes = append(changes, &schema.DropIndex{T: from, I: idx})
		}
	}
	// foreign keys by symbol, fall back to positional comparison
	if len(from.ForeignKeys) != len(to.ForeignKeys) {
		// add/drop
		// match by symbol
		fromFK := map[string]*schema.ForeignKey{}
		for _, fk := range from.ForeignKeys {
			fromFK[fk.Symbol] = fk
		}
		matchedFrom := map[string]bool{}
		for _, fk := range to.ForeignKeys {
			if ff, ok := fromFK[fk.Symbol]; ok && fkEqual(ff, fk) {
				matchedFrom[fk.Symbol] = true
				continue
			}
			if ff, ok := fromFK[fk.Symbol]; ok {
				changes = append(changes, &schema.ModifyForeignKey{T: to, From: ff, To: fk})
				matchedFrom[fk.Symbol] = true
			} else {
				changes = append(changes, &schema.AddForeignKey{T: to, FK: fk})
			}
			recreate = true
		}
		for _, fk := range from.ForeignKeys {
			if !matchedFrom[fk.Symbol] {
				// check if matched above by symbol-with-modify
				found := false
				for _, tfk := range to.ForeignKeys {
					if tfk.Symbol == fk.Symbol {
						found = true
					}
				}
				if !found {
					changes = append(changes, &schema.DropForeignKey{T: from, FK: fk})
					recreate = true
				}
			}
		}
	} else {
		for i, fk := range to.ForeignKeys {
			ff := from.ForeignKeys[i]
			if !fkEqual(ff, fk) {
				changes = append(changes, &schema.ModifyForeignKey{T: to, From: ff, To: fk})
				recreate = true
			}
		}
	}
	// checks by normalized expr
	fromChecks := map[string]*schema.Check{}
	for _, c := range from.Checks {
		fromChecks[normalizeExpr(stripOuterParens(c.Expr))] = c
	}
	toChecks := map[string]*schema.Check{}
	for _, c := range to.Checks {
		toChecks[normalizeExpr(stripOuterParens(c.Expr))] = c
	}
	for _, c := range to.Checks {
		if _, ok := fromChecks[normalizeExpr(stripOuterParens(c.Expr))]; !ok {
			changes = append(changes, &schema.AddCheck{T: to, C: c})
			recreate = true
		}
	}
	for _, c := range from.Checks {
		if _, ok := toChecks[normalizeExpr(stripOuterParens(c.Expr))]; !ok {
			changes = append(changes, &schema.DropCheck{T: from, C: c})
			recreate = true
		}
	}
	if from.WithoutRowID != to.WithoutRowID || from.Strict != to.Strict {
		recreate = true
		changes = append(changes, &schema.ModifyColumn{T: to, C: nil})
	}
	_ = recreate
	// recompute recreate based on change types (excluding AddColumn non-generated, AddIndex, DropIndex)
	needRecreate := false
	for _, ch := range changes {
		switch ch.(type) {
		case *schema.AddColumn:
			ac := ch.(*schema.AddColumn)
			if ac.C != nil && ac.C.Generated != nil {
				needRecreate = true
			}
		case *schema.DropColumn, *schema.ModifyColumn, *schema.ModifyIndex, *schema.AddForeignKey, *schema.DropForeignKey, *schema.ModifyForeignKey, *schema.AddCheck, *schema.DropCheck, *schema.ModifyCheck:
			needRecreate = true
		}
	}
	return changes, needRecreate
}

// realmDiff computes schema changes from current to desired realm.
// Only tables in the "main" schema (and schemas wholesale) are handled.
func realmDiff(current, desired *schema.Realm) []schema.Change {
	var changes []schema.Change
	curSchemas := map[string]*schema.Schema{}
	for _, s := range current.Schemas {
		curSchemas[s.Name] = s
	}
	desSchemas := map[string]*schema.Schema{}
	for _, s := range desired.Schemas {
		desSchemas[s.Name] = s
	}
	// schema drops / adds
	for _, s := range current.Schemas {
		if _, ok := desSchemas[s.Name]; !ok {
			changes = append(changes, &schema.DropSchema{S: s})
		}
	}
	for _, s := range desired.Schemas {
		if _, ok := curSchemas[s.Name]; !ok {
			changes = append(changes, &schema.AddSchema{S: s})
		}
	}
	// Table changes for common schemas: iterate current tables in order,
	// emitting drop/modify; then desired additions.
	for _, cs := range current.Schemas {
		ds, ok := desSchemas[cs.Name]
		if !ok {
			continue
		}
		desTables := map[string]*schema.Table{}
		for _, t := range ds.Tables {
			desTables[t.Name] = t
		}
		for _, ct := range cs.Tables {
			dt, ok := desTables[ct.Name]
			if !ok {
				changes = append(changes, &schema.DropTable{T: ct})
				continue
			}
			sub, _ := tableSubChanges(ct, dt)
			if len(sub) > 0 {
				changes = append(changes, &schema.ModifyTable{T: dt, Changes: sub})
			}
		}
	}
	for _, ds := range desired.Schemas {
		cs, ok := curSchemas[ds.Name]
		if !ok {
			continue
		}
		curTables := map[string]*schema.Table{}
		for _, t := range cs.Tables {
			curTables[t.Name] = t
		}
		for _, dt := range ds.Tables {
			if _, ok := curTables[dt.Name]; !ok {
				changes = append(changes, &schema.AddTable{T: dt})
			}
		}
	}
	return changes
}

// ---------- Planner ----------

// planChanges converts schema changes into SQL changes for sqlite.
// indent is "" for one-line create tables or "  " for indented.
func planChanges(current, desired *schema.Realm, changes []schema.Change, indent string) ([]*migrate.Change, error) {
	var out []*migrate.Change
	// track if we need FK pragma wrapper
	for _, ch := range changes {
		switch c := ch.(type) {
		case *schema.DropSchema:
			return nil, fmt.Errorf("unsupported change %T", ch)
		case *schema.AddSchema:
			return nil, fmt.Errorf("unsupported change %T", ch)
		case *schema.DropTable:
			out = append(out, &migrate.Change{
				Cmd:     "DROP TABLE " + quoteSQLIdent(c.T.Name),
				Comment: fmt.Sprintf("drop %q table", c.T.Name),
				Reverse: formatCreateTableForPlan(createTableSQL(c.T, ""), indent),
				Source:  ch,
			})
		case *schema.AddTable:
			out = append(out, createTableChange(c.T, "", indent, ch))
			for _, idx := range c.T.Indexes {
				out = append(out, createIndexChange(c.T, idx, ch))
			}
		case *schema.ModifyTable:
			// find current table
			var curTable *schema.Table
			if current != nil {
				if cs := current.Schema(c.T.Schema.Name); cs != nil {
					curTable = cs.Table(c.T.Name)
				}
			}
			if curTable == nil {
				curTable = c.T
			}
			sub, needRecreate := tableSubChanges(curTable, c.T)
			_ = sub
			if needRecreate {
				out = append(out, recreateTableChanges(curTable, c.T, c, indent)...)
			} else {
				for _, sc := range c.Changes {
					switch sc := sc.(type) {
					case *schema.AddColumn:
						out = append(out, &migrate.Change{
							Cmd:     fmt.Sprintf("ALTER TABLE %s ADD COLUMN %s", quoteSQLIdent(c.T.Name), columnSQL(sc.C, c.T)),
							Comment: fmt.Sprintf("add column %q to table: %q", sc.C.Name, c.T.Name),
							Reverse: fmt.Sprintf("ALTER TABLE %s DROP COLUMN %s", quoteSQLIdent(c.T.Name), quoteSQLIdent(sc.C.Name)),
							Source:  sc,
						})
					case *schema.AddIndex:
						out = append(out, createIndexChange(c.T, sc.I, sc))
					case *schema.DropIndex:
						out = append(out, &migrate.Change{
							Cmd:     "DROP INDEX " + quoteSQLIdent(sc.I.Name),
							Comment: fmt.Sprintf("drop index %q from table: %q", sc.I.Name, c.T.Name),
							Reverse: createIndexSQL(curTable, sc.I),
							Source:  sc,
						})
					}
				}
			}
		}
	}
	if len(out) == 0 {
		return out, nil
	}
	if needsFKPragma(changes, current, desired) {
		res := make([]*migrate.Change, 0, len(out)+2)
		res = append(res, &migrate.Change{Cmd: "PRAGMA foreign_keys = off", Comment: "disable the enforcement of foreign-keys constraints"})
		res = append(res, out...)
		res = append(res, &migrate.Change{Cmd: "PRAGMA foreign_keys = on", Comment: "enable back the enforcement of foreign-keys constraints"})
		return res, nil
	}
	return out, nil
}

func needsFKPragma(changes []schema.Change, current, desired *schema.Realm) bool {
	for _, ch := range changes {
		switch c := ch.(type) {
		case *schema.DropTable:
			_ = c
			return true
		case *schema.ModifyTable:
			var curTable *schema.Table
			if current != nil {
				if cs := current.Schema(c.T.Schema.Name); cs != nil {
					curTable = cs.Table(c.T.Name)
				}
			}
			if curTable != nil {
				_, need := tableSubChanges(curTable, c.T)
				if need {
					return true
				}
			}
		}
	}
	return false
}

func createTableChange(t *schema.Table, nameOverride, indent string, source schema.Change) *migrate.Change {
	name := t.Name
	if nameOverride != "" {
		name = nameOverride
	}
	cmd := createTableSQL(t, nameOverride)
	if indent != "" {
		cmd = formatCreateTableForPlan(cmd, indent)
	}
	return &migrate.Change{
		Cmd:     cmd,
		Comment: fmt.Sprintf("create %q table", name),
		Reverse: "DROP TABLE " + quoteSQLIdent(name),
		Source:  source,
	}
}

func createIndexChange(t *schema.Table, idx *schema.Index, source schema.Change) *migrate.Change {
	var src schema.Change = source
	if _, ok := source.(*schema.ModifyTable); ok {
		src = &schema.AddIndex{T: t, I: idx}
	}
	if at, ok := source.(*schema.AddTable); ok {
		_ = at
		// create table path: source for index created as part of add table
		// in original it is AddIndex as well when we probed? For AddTable
		// indexes the source was not probed; use AddIndex.
		src = &schema.AddIndex{T: t, I: idx}
	}
	return &migrate.Change{
		Cmd:     createIndexSQL(t, idx),
		Comment: fmt.Sprintf("create index %q to table: %q", indexSQLName(t, idx), t.Name),
		Reverse: "DROP INDEX " + quoteSQLIdent(indexSQLName(t, idx)),
		Source:  src,
	}
}

func recreateTableChanges(cur, des *schema.Table, mod *schema.ModifyTable, indent string) []*migrate.Change {
	var out []*migrate.Change
	newName := "new_" + des.Name
	// create new table
	newTable := *des
	newTable.Name = newName
	createCh := createTableChange(&newTable, "", indent, &schema.AddTable{T: &newTable})
	out = append(out, createCh)
	// copy rows: common columns in desired order
	curCols := map[string]bool{}
	for _, c := range cur.Columns {
		curCols[c.Name] = true
	}
	var common []string
	for _, c := range des.Columns {
		if c.Generated != nil {
			continue
		}
		if curCols[c.Name] {
			common = append(common, c.Name)
		}
	}
	if len(common) > 0 {
		var quoted []string
		for _, n := range common {
			quoted = append(quoted, quoteSQLIdent(n))
		}
		out = append(out, &migrate.Change{
			Cmd:     fmt.Sprintf("INSERT INTO %s (%s) SELECT %s FROM %s", quoteSQLIdent(newName), strings.Join(quoted, ", "), strings.Join(quoted, ", "), quoteSQLIdent(cur.Name)),
			Comment: fmt.Sprintf("copy rows from old table %q to new temporary table %q", cur.Name, newName),
		})
	}
	out = append(out, &migrate.Change{
		Cmd:     "DROP TABLE " + quoteSQLIdent(cur.Name),
		Comment: fmt.Sprintf("drop %q table after copying rows", cur.Name),
		Source:  mod,
	})
	out = append(out, &migrate.Change{
		Cmd:     fmt.Sprintf("ALTER TABLE %s RENAME TO %s", quoteSQLIdent(newName), quoteSQLIdent(des.Name)),
		Comment: fmt.Sprintf("rename temporary table %q to %q", newName, des.Name),
		Source:  mod,
	})
	for _, idx := range des.Indexes {
		out = append(out, createIndexChange(des, idx, mod))
	}
	return out
}
