function.arguments:
{"command":"cat > hcl_schema.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"atlas/schema"
)

var typeNoAttrs = map[string]bool{
	"boolean": true, "bool": true, "date": true, "datetime": true, "json": true, "uuid": true,
}
var typeTwoArgs = map[string]bool{
	"real": true, "decimal": true, "numeric": true,
}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	d := make([][]int, la+1)
	for i := range d {
		d[i] = make([]int, lb+1)
		d[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		d[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			d[i][j] = min3(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+cost)
		}
	}
	return d[la][lb]
}
func min3(a, b, c int) int {
	m := a
	if b < m {
		m = b
	}
	if c < m {
		m = c
	}
	return m
}

func suggestType(name string) string {
	// Candidates as in the type registry.
	candidates := []string{"tinyint", "smallint", "mediumint", "int", "integer", "bigint", "int2", "int8", "float", "double", "double_precision", "real", "decimal", "numeric", "boolean", "bool", "varchar", "character", "native_character", "varying_character", "nchar", "nvarchar", "text", "clob", "blob", "date", "datetime", "json", "uuid", "unsigned_big_int"}
	best := ""
	bestDist := 100
	for _, cand := range candidates {
		d := levenshtein(name, cand)
		if d < bestDist {
			bestDist = d
			best = cand
		}
	}
	if bestDist <= 2 {
		return best
	}
	return ""
}

// columnTypeFromExpr interprets a type expression in an HCL schema file.
func columnTypeFromExpr(e *expr, filename string) (string, error) {
	switch e.kind {
	case exTraversal:
		if len(e.trav) == 1 {
			name := e.trav[0]
			if hclKnownTypes[name] {
				return name, nil
			}
			detail := fmt.Sprintf("There is no type named %q.", name)
			if s := suggestType(name); s != "" {
				detail += fmt.Sprintf(" Did you mean %q?", s)
			}
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown column.type", detail)}
		}
		return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type %s", strings.Join(e.trav, "."))
	case exString:
		return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type string")
	case exFuncCall:
		name := e.funcName
		if name == "sql" {
			if len(e.args) > 1 {
				tok := e.args[1].tok
				return "", hclDiags{diagAt(filename, tok.line, tok.col+1, tok.line, tok.col+2, "Too many function arguments", "Function \"sql\" expects only 1 argument(s).")}
			}
			if len(e.args) == 0 {
				return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
			}
			a := e.args[0]
			if a.kind == exString {
				return a.strVal, nil
			}
			if a.kind == exNumber {
				return a.numVal, nil
			}
			// identifiers evaluated as names
			if a.kind == exTraversal {
				return strings.Join(a.trav, "."), nil
			}
			return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
		}
		if !hclKnownTypes[name] {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Call to unknown function", fmt.Sprintf("There is no function named %q.", name))}
		}
		if typeNoAttrs[name] {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Call to unknown function", fmt.Sprintf("Type %q does not accept attributes", name))}
		}
		maxArgs := 1
		if typeTwoArgs[name] {
			maxArgs = 2
		}
		if len(e.args) > maxArgs {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol+1, "Error in function call", fmt.Sprintf("Call to function %q failed: too many arguments for type definition %q.", name, name))}
		}
		// args must be numbers (or negative numbers)
		var parts []string
		for _, a := range e.args {
			switch a.kind {
			case exNumber:
				parts = append(parts, a.numVal)
			case exUnary:
				if a.op == "-" && a.left.kind == exNumber {
					parts = append(parts, "-"+a.left.numVal)
				} else {
					return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
				}
			case exTraversal:
				an := strings.Join(a.trav, ".")
				detail := fmt.Sprintf("There is no type named %q.", an)
				if s := suggestType(an); s != "" {
					detail += fmt.Sprintf(" Did you mean %q?", s)
				}
				return "", hclDiags{diagAt(filename, a.tok.line, a.tok.col, a.tok.endLine, a.tok.endCol, "Unknown column.type", detail)}
			default:
				return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
			}
		}
		if len(parts) == 0 {
			return name, nil
		}
		return fmt.Sprintf("%s(%s)", name, strings.Join(parts, ",")), nil
	}
	return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type string")
}

// literalValue interprets a default/attribute expression without evaluation context.
func literalValue(e *expr) (value, bool) {
	switch e.kind {
	case exString:
		// no interpolation
		if len(e.parts) == 0 {
			return strVal(e.strVal), true
		}
		var sb strings.Builder
		for _, p := range e.parts {
			if p.isExpr {
				return nullVal(), false
			}
			sb.WriteString(p.lit)
		}
		return strVal(sb.String()), true
	case exNumber:
		return numVal(e.numVal), true
	case exBool:
		return boolVal(e.boolVal), true
	case exNull:
		return nullVal(), true
	case exUnary:
		if e.op == "-" && e.left.kind == exNumber {
			return numVal("-" + e.left.numVal), true
		}
		if e.op == "-" && e.left.kind == exString {
			return nullVal(), false
		}
	case exParen:
		return literalValue(e.left)
	case exList:
		var out []value
		for _, el := range e.elems {
			v, ok := literalValue(el)
			if !ok {
				return nullVal(), false
			}
			out = append(out, v)
		}
		return value{kind: vList, list: out}, true
	case exTraversal:
		// bare symbol
		return strVal(strings.Join(e.trav, ".")), true
	case exFuncCall:
		if e.funcName == "sql" && len(e.args) == 1 && e.args[0].kind == exString {
			return value{kind: vFunc, funcName: "sql", funcArgs: []value{strVal(e.args[0].strVal)}}, true
		}
	}
	return nullVal(), false
}

func boolAttr(b *body, name string) (bool, bool) {
	a := b.attr(name)
	if a == nil {
		return false, false
	}
	v, ok := literalValue(a.Expr)
	if ok && v.kind == vBool {
		return v.b, true
	}
	return false, false
}
func stringAttr(b *body, name string) (string, bool) {
	a := b.attr(name)
	if a == nil {
		return "", false
	}
	v, ok := literalValue(a.Expr)
	if ok {
		return v.toString(), true
	}
	return "", false
}

// traversalRefs returns the traversal parts for an expression if it is a reference.
func refParts(e *expr) []string {
	if e == nil {
		return nil
	}
	if e.kind == exTraversal {
		return e.trav
	}
	return nil
}

func refListNames(e *expr, wantPrefix string) []string {
	var out []string
	if e == nil {
		return out
	}
	if e.kind == exList {
		for _, el := range e.elems {
			parts := refParts(el)
			if len(parts) > 0 {
				out = append(out, parts[len(parts)-1])
			}
		}
	}
	return out
}

type refColumn struct {
	table, column string
}

func refListColumns(e *expr) []refColumn {
	var out []refColumn
	if e == nil || e.kind != exList {
		return out
	}
	for _, el := range e.elems {
		parts := refParts(el)
		// table.<t>.column.<c>
		if len(parts) == 4 && parts[0] == "table" && parts[2] == "column" {
			out = append(out, refColumn{table: parts[1], column: parts[3]})
		} else if len(parts) >= 2 {
			out = append(out, refColumn{column: parts[len(parts)-1]})
		}
	}
	return out
}

// hclToRealm converts a parsed HCL schema document to a Realm (unnormalized).
func hclToRealm(doc *body, filename string) (*schema.Realm, error) {
	realm := &schema.Realm{}
	schemasByName := map[string]*schema.Schema{}
	// schema blocks first (in order)
	for _, bl := range doc.blocksOf("schema") {
		if len(bl.Labels) != 1 {
			continue
		}
		s := &schema.Schema{Name: bl.Labels[0], Realm: realm}
		realm.Schemas = append(realm.Schemas, s)
		schemasByName[s.Name] = s
	}
	// tables
	for _, tblBlock := range doc.blocksOf("table") {
		if len(tblBlock.Labels) != 1 {
			continue
		}
		tname := tblBlock.Labels[0]
		// schema reference
		schemaAttr := tblBlock.Body.attr("schema")
		if schemaAttr == nil {
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: type \"schema\" was not found in nil reference", tname)
		}
		parts := refParts(schemaAttr.Expr)
		if parts == nil {
			// string literal or other
			var refStr string
			if schemaAttr.Expr.kind == exString {
				refStr = schemaAttr.Expr.strVal
			} else {
				refStr = ""
			}
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: missing type in reference %q", tname, refStr)
		}
		// parts should be ["schema", "<name>"]
		if len(parts) != 2 || parts[0] != "schema" {
			// e.g. schema = main (undefined traversal)
			// Treat as unsupported attribute error if the second component refers to unknown schema
			// Original: for schema.foo where foo is not a defined schema block, error is Unsupported attribute at that attr token
			// That case is handled below as parts[1] lookup.
			// If parts[0] != schema, mimic missing type error
		}
		schemaName := ""
		if len(parts) >= 2 {
			schemaName = parts[1]
		}
		sc, ok := schemasByName[schemaName]
		if !ok {
			if len(parts) >= 2 && parts[0] == "schema" {
				// Unsupported attribute diagnostics pointing at the schema name token.
				// The token of the traversal is the root; compute range for the last part.
				// We approximate using the attribute expression token.
				tok := schemaAttr.Expr.tok
				// column of schema name: tok.col + len("schema")+1
				startCol := tok.col + len(parts[0]) + 1
				return nil, hclDiags{diagAt(filename, tok.line, startCol, tok.line, startCol+len(schemaName), "Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.", schemaName))}
			}
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: type \"schema\" was not found in nil reference", tname)
		}
		t := &schema.Table{Name: tname, Schema: sc}
		sc.Tables = append(sc.Tables, t)
		if v, ok := boolAttr(tblBlock.Body, "without_rowid"); ok {
			t.WithoutRowID = v
		}
		if v, ok := boolAttr(tblBlock.Body, "strict"); ok {
			t.Strict = v
		}
		// Columns
		for _, colBlock := range tblBlock.Body.blocksOf("column") {
			if len(colBlock.Labels) != 1 {
				continue
			}
			cname := colBlock.Labels[0]
			col := &schema.Column{Name: cname, Null: false}
			typeAttr := colBlock.Body.attr("type")
			if typeAttr == nil {
				return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot convert table %q: specutil: nil type", tname)
			}
			raw, err := columnTypeFromExpr(typeAttr.Expr, filename)
			if err != nil {
				return nil, err
			}
			col.Type.Raw = raw
			if v, ok := boolAttr(colBlock.Body, "null"); ok {
				col.Null = v
			}
			if v, ok := boolAttr(colBlock.Body, "auto_increment"); ok {
				col.AutoIncrement = v
			}
			if dflt := colBlock.Body.attr("default"); dflt != nil {
				if dv, ok := literalValue(dflt.Expr); ok {
					switch dv.kind {
					case vString:
						col.Default = &schema.DefaultValue{Kind: "string", Str: dv.str}
					case vNumber:
						col.Default = &schema.DefaultValue{Kind: "number", Str: dv.str}
					case vBool:
						col.Default = &schema.DefaultValue{Kind: "bool", Str: dv.toString()}
					case vFunc:
						col.Default = &schema.DefaultValue{Kind: "sql", Str: dv.funcArgs[0].str}
					case vNull:
						// no default
					}
				} else if dflt.Expr.kind == exTraversal {
					// e.g. default = true handled; bare symbols?
					col.Default = &schema.DefaultValue{Kind: "sql", Str: strings.Join(dflt.Expr.trav, ".")}
				}
			}
			// generated
			for _, asBlock := range colBlock.Body.blocksOf("as") {
				exprStr, _ := stringAttr(asBlock.Body, "expr")
				typeStr := "VIRTUAL"
				if ta := asBlock.Body.attr("type"); ta != nil {
					if parts := refParts(ta.Expr); len(parts) >= 1 {
						typeStr = parts[len(parts)-1]
					} else if v, ok := literalValue(ta.Expr); ok {
						typeStr = v.toString()
					}
				}
				col.Generated = &schema.Generated{Expr: exprStr, Type: typeStr}
			}
			t.Columns = append(t.Columns, col)
		}
		// primary_key
		for _, pkBlock := range tblBlock.Body.blocksOf("primary_key") {
			if a := pkBlock.Body.attr("columns"); a != nil {
				names := refListNames(a.Expr, "column")
				pk := &schema.PrimaryKey{}
				for _, n := range names {
					if c := t.Column(n); c != nil {
						pk.Parts = append(pk.Parts, &schema.IndexPart{Column: c})
					} else {
						pk.Parts = append(pk.Parts, &schema.IndexPart{Column: &schema.Column{Name: n}})
					}
				}
				t.PrimaryKey = pk
			}
		}
		// indexes
		for _, idxBlock := range tblBlock.Body.blocksOf("index") {
			if len(idxBlock.Labels) != 1 {
				continue
			}
			idx := &schema.Index{Name: idxBlock.Labels[0], Table: t}
			if v, ok := boolAttr(idxBlock.Body, "unique"); ok {
				idx.Unique = v
			}
			if a := idxBlock.Body.attr("columns"); a != nil {
				names := refListNames(a.Expr, "column")
				for _, n := range names {
					if c := t.Column(n); c != nil {
						idx.Parts = append(idx.Parts, &schema.IndexPart{Column: c})
					}
				}
			}
			if w, ok := stringAttr(idxBlock.Body, "where"); ok {
				idx.Where = w
			}
			for _, onBlock := range idxBlock.Body.blocksOf("on") {
				part := &schema.IndexPart{}
				if ca := onBlock.Body.attr("column"); ca != nil {
					names := refParts(ca.Expr)
					if len(names) > 0 {
						if c := t.Column(names[len(names)-1]); c != nil {
							part.Column = c
						}
					}
				}
				if ea := onBlock.Body.attr("expr"); ea != nil {
					if v, ok := literalValue(ea.Expr); ok {
						part.Expr = v.toString()
					}
				}
				if v, ok := boolAttr(onBlock.Body, "desc"); ok {
					part.Desc = v
				}
				idx.Parts = append(idx.Parts, part)
			}
			t.Indexes = append(t.Indexes, idx)
		}
		// foreign keys (resolve ref tables later)
		for _, fkBlock := range tblBlock.Body.blocksOf("foreign_key") {
			if len(fkBlock.Labels) != 1 {
				continue
			}
			fk := &schema.ForeignKey{Symbol: fkBlock.Labels[0], Table: t, OnUpdate: "NO_ACTION", OnDelete: "NO_ACTION"}
			if a := fkBlock.Body.attr("columns"); a != nil {
				for _, n := range refListNames(a.Expr, "column") {
					if c := t.Column(n); c != nil {
						fk.Columns = append(fk.Columns, c)
					}
				}
			}
			if a := fkBlock.Body.attr("ref_columns"); a != nil {
				refs := refListColumns(a.Expr)
				// RefTable resolved after all tables exist.
				for _, r := range refs {
					fk.RefColumns = append(fk.RefColumns, &schema.Column{Name: r.column})
					// stash table name in first ref column type? We'll resolve below using refs list again.
					_ = r
				}
				// Store pending ref info on the foreign key via RefTable placeholder name.
				if len(refs) > 0 && refs[0].table != "" {
					fk.RefTable = &schema.Table{Name: refs[0].table}
				}
			}
			if a := fkBlock.Body.attr("on_update"); a != nil {
				if parts := refParts(a.Expr); len(parts) > 0 {
					fk.OnUpdate = parts[len(parts)-1]
				}
			}
			if a := fkBlock.Body.attr("on_delete"); a != nil {
				if parts := refParts(a.Expr); len(parts) > 0 {
					fk.OnDelete = parts[len(parts)-1]
				}
			}
			t.ForeignKeys = append(t.ForeignKeys, fk)
		}
		// checks
		for _, chkBlock := range tblBlock.Body.blocksOf("check") {
			if es, ok := stringAttr(chkBlock.Body, "expr"); ok {
				t.Checks = append(t.Checks, &schema.Check{Expr: es})
			}
		}
	}
	// views and other block types: view requires 'as'
	for _, vBlock := range doc.blocksOf("view") {
		if len(vBlock.Labels) >= 1 {
			if vBlock.Body.attr("as") == nil {
				return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot convert view %q: missing 'as' definition for view %q", vBlock.Labels[0], vBlock.Labels[0])
			}
		}
	}
	// Resolve foreign key ref tables and ref columns against realm tables.
	for _, s := range realm.Schemas {
		for _, t := range s.Tables {
			for _, fk := range t.ForeignKeys {
				if fk.RefTable != nil {
					if rt := s.Table(fk.RefTable.Name); rt != nil {
						fk.RefTable = rt
						for i, rc := range fk.RefColumns {
							if c := rt.Column(rc.Name); c != nil {
								fk.RefColumns[i] = c
							}
						}
					}
				}
			}
		}
	}
	var _ = strconv.Quote
	return realm, nil
}
EOF
"}

actions.command:
cat > hcl_schema.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"atlas/schema"
)

var typeNoAttrs = map[string]bool{
	"boolean": true, "bool": true, "date": true, "datetime": true, "json": true, "uuid": true,
}
var typeTwoArgs = map[string]bool{
	"real": true, "decimal": true, "numeric": true,
}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	d := make([][]int, la+1)
	for i := range d {
		d[i] = make([]int, lb+1)
		d[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		d[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			d[i][j] = min3(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+cost)
		}
	}
	return d[la][lb]
}
func min3(a, b, c int) int {
	m := a
	if b < m {
		m = b
	}
	if c < m {
		m = c
	}
	return m
}

func suggestType(name string) string {
	// Candidates as in the type registry.
	candidates := []string{"tinyint", "smallint", "mediumint", "int", "integer", "bigint", "int2", "int8", "float", "double", "double_precision", "real", "decimal", "numeric", "boolean", "bool", "varchar", "character", "native_character", "varying_character", "nchar", "nvarchar", "text", "clob", "blob", "date", "datetime", "json", "uuid", "unsigned_big_int"}
	best := ""
	bestDist := 100
	for _, cand := range candidates {
		d := levenshtein(name, cand)
		if d < bestDist {
			bestDist = d
			best = cand
		}
	}
	if bestDist <= 2 {
		return best
	}
	return ""
}

// columnTypeFromExpr interprets a type expression in an HCL schema file.
func columnTypeFromExpr(e *expr, filename string) (string, error) {
	switch e.kind {
	case exTraversal:
		if len(e.trav) == 1 {
			name := e.trav[0]
			if hclKnownTypes[name] {
				return name, nil
			}
			detail := fmt.Sprintf("There is no type named %q.", name)
			if s := suggestType(name); s != "" {
				detail += fmt.Sprintf(" Did you mean %q?", s)
			}
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown column.type", detail)}
		}
		return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type %s", strings.Join(e.trav, "."))
	case exString:
		return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type string")
	case exFuncCall:
		name := e.funcName
		if name == "sql" {
			if len(e.args) > 1 {
				tok := e.args[1].tok
				return "", hclDiags{diagAt(filename, tok.line, tok.col+1, tok.line, tok.col+2, "Too many function arguments", "Function \"sql\" expects only 1 argument(s).")}
			}
			if len(e.args) == 0 {
				return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
			}
			a := e.args[0]
			if a.kind == exString {
				return a.strVal, nil
			}
			if a.kind == exNumber {
				return a.numVal, nil
			}
			// identifiers evaluated as names
			if a.kind == exTraversal {
				return strings.Join(a.trav, "."), nil
			}
			return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
		}
		if !hclKnownTypes[name] {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Call to unknown function", fmt.Sprintf("There is no function named %q.", name))}
		}
		if typeNoAttrs[name] {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Call to unknown function", fmt.Sprintf("Type %q does not accept attributes", name))}
		}
		maxArgs := 1
		if typeTwoArgs[name] {
			maxArgs = 2
		}
		if len(e.args) > maxArgs {
			return "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol+1, "Error in function call", fmt.Sprintf("Call to function %q failed: too many arguments for type definition %q.", name, name))}
		}
		// args must be numbers (or negative numbers)
		var parts []string
		for _, a := range e.args {
			switch a.kind {
			case exNumber:
				parts = append(parts, a.numVal)
			case exUnary:
				if a.op == "-" && a.left.kind == exNumber {
					parts = append(parts, "-"+a.left.numVal)
				} else {
					return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
				}
			case exTraversal:
				an := strings.Join(a.trav, ".")
				detail := fmt.Sprintf("There is no type named %q.", an)
				if s := suggestType(an); s != "" {
					detail += fmt.Sprintf(" Did you mean %q?", s)
				}
				return "", hclDiags{diagAt(filename, a.tok.line, a.tok.col, a.tok.endLine, a.tok.endCol, "Unknown column.type", detail)}
			default:
				return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type")
			}
		}
		if len(parts) == 0 {
			return name, nil
		}
		return fmt.Sprintf("%s(%s)", name, strings.Join(parts, ",")), nil
	}
	return "", fmt.Errorf("schemahcl: failed reading spec as *sqlite.doc: set field \"type\": unexpected type string")
}

// literalValue interprets a default/attribute expression without evaluation context.
func literalValue(e *expr) (value, bool) {
	switch e.kind {
	case exString:
		// no interpolation
		if len(e.parts) == 0 {
			return strVal(e.strVal), true
		}
		var sb strings.Builder
		for _, p := range e.parts {
			if p.isExpr {
				return nullVal(), false
			}
			sb.WriteString(p.lit)
		}
		return strVal(sb.String()), true
	case exNumber:
		return numVal(e.numVal), true
	case exBool:
		return boolVal(e.boolVal), true
	case exNull:
		return nullVal(), true
	case exUnary:
		if e.op == "-" && e.left.kind == exNumber {
			return numVal("-" + e.left.numVal), true
		}
		if e.op == "-" && e.left.kind == exString {
			return nullVal(), false
		}
	case exParen:
		return literalValue(e.left)
	case exList:
		var out []value
		for _, el := range e.elems {
			v, ok := literalValue(el)
			if !ok {
				return nullVal(), false
			}
			out = append(out, v)
		}
		return value{kind: vList, list: out}, true
	case exTraversal:
		// bare symbol
		return strVal(strings.Join(e.trav, ".")), true
	case exFuncCall:
		if e.funcName == "sql" && len(e.args) == 1 && e.args[0].kind == exString {
			return value{kind: vFunc, funcName: "sql", funcArgs: []value{strVal(e.args[0].strVal)}}, true
		}
	}
	return nullVal(), false
}

func boolAttr(b *body, name string) (bool, bool) {
	a := b.attr(name)
	if a == nil {
		return false, false
	}
	v, ok := literalValue(a.Expr)
	if ok && v.kind == vBool {
		return v.b, true
	}
	return false, false
}
func stringAttr(b *body, name string) (string, bool) {
	a := b.attr(name)
	if a == nil {
		return "", false
	}
	v, ok := literalValue(a.Expr)
	if ok {
		return v.toString(), true
	}
	return "", false
}

// traversalRefs returns the traversal parts for an expression if it is a reference.
func refParts(e *expr) []string {
	if e == nil {
		return nil
	}
	if e.kind == exTraversal {
		return e.trav
	}
	return nil
}

func refListNames(e *expr, wantPrefix string) []string {
	var out []string
	if e == nil {
		return out
	}
	if e.kind == exList {
		for _, el := range e.elems {
			parts := refParts(el)
			if len(parts) > 0 {
				out = append(out, parts[len(parts)-1])
			}
		}
	}
	return out
}

type refColumn struct {
	table, column string
}

func refListColumns(e *expr) []refColumn {
	var out []refColumn
	if e == nil || e.kind != exList {
		return out
	}
	for _, el := range e.elems {
		parts := refParts(el)
		// table.<t>.column.<c>
		if len(parts) == 4 && parts[0] == "table" && parts[2] == "column" {
			out = append(out, refColumn{table: parts[1], column: parts[3]})
		} else if len(parts) >= 2 {
			out = append(out, refColumn{column: parts[len(parts)-1]})
		}
	}
	return out
}

// hclToRealm converts a parsed HCL schema document to a Realm (unnormalized).
func hclToRealm(doc *body, filename string) (*schema.Realm, error) {
	realm := &schema.Realm{}
	schemasByName := map[string]*schema.Schema{}
	// schema blocks first (in order)
	for _, bl := range doc.blocksOf("schema") {
		if len(bl.Labels) != 1 {
			continue
		}
		s := &schema.Schema{Name: bl.Labels[0], Realm: realm}
		realm.Schemas = append(realm.Schemas, s)
		schemasByName[s.Name] = s
	}
	// tables
	for _, tblBlock := range doc.blocksOf("table") {
		if len(tblBlock.Labels) != 1 {
			continue
		}
		tname := tblBlock.Labels[0]
		// schema reference
		schemaAttr := tblBlock.Body.attr("schema")
		if schemaAttr == nil {
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: type \"schema\" was not found in nil reference", tname)
		}
		parts := refParts(schemaAttr.Expr)
		if parts == nil {
			// string literal or other
			var refStr string
			if schemaAttr.Expr.kind == exString {
				refStr = schemaAttr.Expr.strVal
			} else {
				refStr = ""
			}
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: missing type in reference %q", tname, refStr)
		}
		// parts should be ["schema", "<name>"]
		if len(parts) != 2 || parts[0] != "schema" {
			// e.g. schema = main (undefined traversal)
			// Treat as unsupported attribute error if the second component refers to unknown schema
			// Original: for schema.foo where foo is not a defined schema block, error is Unsupported attribute at that attr token
			// That case is handled below as parts[1] lookup.
			// If parts[0] != schema, mimic missing type error
		}
		schemaName := ""
		if len(parts) >= 2 {
			schemaName = parts[1]
		}
		sc, ok := schemasByName[schemaName]
		if !ok {
			if len(parts) >= 2 && parts[0] == "schema" {
				// Unsupported attribute diagnostics pointing at the schema name token.
				// The token of the traversal is the root; compute range for the last part.
				// We approximate using the attribute expression token.
				tok := schemaAttr.Expr.tok
				// column of schema name: tok.col + len("schema")+1
				startCol := tok.col + len(parts[0]) + 1
				return nil, hclDiags{diagAt(filename, tok.line, startCol, tok.line, startCol+len(schemaName), "Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.", schemaName))}
			}
			return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot extract schema name for table %q: schemahcl: type \"schema\" was not found in nil reference", tname)
		}
		t := &schema.Table{Name: tname, Schema: sc}
		sc.Tables = append(sc.Tables, t)
		if v, ok := boolAttr(tblBlock.Body, "without_rowid"); ok {
			t.WithoutRowID = v
		}
		if v, ok := boolAttr(tblBlock.Body, "strict"); ok {
			t.Strict = v
		}
		// Columns
		for _, colBlock := range tblBlock.Body.blocksOf("column") {
			if len(colBlock.Labels) != 1 {
				continue
			}
			cname := colBlock.Labels[0]
			col := &schema.Column{Name: cname, Null: false}
			typeAttr := colBlock.Body.attr("type")
			if typeAttr == nil {
				return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot convert table %q: specutil: nil type", tname)
			}
			raw, err := columnTypeFromExpr(typeAttr.Expr, filename)
			if err != nil {
				return nil, err
			}
			col.Type.Raw = raw
			if v, ok := boolAttr(colBlock.Body, "null"); ok {
				col.Null = v
			}
			if v, ok := boolAttr(colBlock.Body, "auto_increment"); ok {
				col.AutoIncrement = v
			}
			if dflt := colBlock.Body.attr("default"); dflt != nil {
				if dv, ok := literalValue(dflt.Expr); ok {
					switch dv.kind {
					case vString:
						col.Default = &schema.DefaultValue{Kind: "string", Str: dv.str}
					case vNumber:
						col.Default = &schema.DefaultValue{Kind: "number", Str: dv.str}
					case vBool:
						col.Default = &schema.DefaultValue{Kind: "bool", Str: dv.toString()}
					case vFunc:
						col.Default = &schema.DefaultValue{Kind: "sql", Str: dv.funcArgs[0].str}
					case vNull:
						// no default
					}
				} else if dflt.Expr.kind == exTraversal {
					// e.g. default = true handled; bare symbols?
					col.Default = &schema.DefaultValue{Kind: "sql", Str: strings.Join(dflt.Expr.trav, ".")}
				}
			}
			// generated
			for _, asBlock := range colBlock.Body.blocksOf("as") {
				exprStr, _ := stringAttr(asBlock.Body, "expr")
				typeStr := "VIRTUAL"
				if ta := asBlock.Body.attr("type"); ta != nil {
					if parts := refParts(ta.Expr); len(parts) >= 1 {
						typeStr = parts[len(parts)-1]
					} else if v, ok := literalValue(ta.Expr); ok {
						typeStr = v.toString()
					}
				}
				col.Generated = &schema.Generated{Expr: exprStr, Type: typeStr}
			}
			t.Columns = append(t.Columns, col)
		}
		// primary_key
		for _, pkBlock := range tblBlock.Body.blocksOf("primary_key") {
			if a := pkBlock.Body.attr("columns"); a != nil {
				names := refListNames(a.Expr, "column")
				pk := &schema.PrimaryKey{}
				for _, n := range names {
					if c := t.Column(n); c != nil {
						pk.Parts = append(pk.Parts, &schema.IndexPart{Column: c})
					} else {
						pk.Parts = append(pk.Parts, &schema.IndexPart{Column: &schema.Column{Name: n}})
					}
				}
				t.PrimaryKey = pk
			}
		}
		// indexes
		for _, idxBlock := range tblBlock.Body.blocksOf("index") {
			if len(idxBlock.Labels) != 1 {
				continue
			}
			idx := &schema.Index{Name: idxBlock.Labels[0], Table: t}
			if v, ok := boolAttr(idxBlock.Body, "unique"); ok {
				idx.Unique = v
			}
			if a := idxBlock.Body.attr("columns"); a != nil {
				names := refListNames(a.Expr, "column")
				for _, n := range names {
					if c := t.Column(n); c != nil {
						idx.Parts = append(idx.Parts, &schema.IndexPart{Column: c})
					}
				}
			}
			if w, ok := stringAttr(idxBlock.Body, "where"); ok {
				idx.Where = w
			}
			for _, onBlock := range idxBlock.Body.blocksOf("on") {
				part := &schema.IndexPart{}
				if ca := onBlock.Body.attr("column"); ca != nil {
					names := refParts(ca.Expr)
					if len(names) > 0 {
						if c := t.Column(names[len(names)-1]); c != nil {
							part.Column = c
						}
					}
				}
				if ea := onBlock.Body.attr("expr"); ea != nil {
					if v, ok := literalValue(ea.Expr); ok {
						part.Expr = v.toString()
					}
				}
				if v, ok := boolAttr(onBlock.Body, "desc"); ok {
					part.Desc = v
				}
				idx.Parts = append(idx.Parts, part)
			}
			t.Indexes = append(t.Indexes, idx)
		}
		// foreign keys (resolve ref tables later)
		for _, fkBlock := range tblBlock.Body.blocksOf("foreign_key") {
			if len(fkBlock.Labels) != 1 {
				continue
			}
			fk := &schema.ForeignKey{Symbol: fkBlock.Labels[0], Table: t, OnUpdate: "NO_ACTION", OnDelete: "NO_ACTION"}
			if a := fkBlock.Body.attr("columns"); a != nil {
				for _, n := range refListNames(a.Expr, "column") {
					if c := t.Column(n); c != nil {
						fk.Columns = append(fk.Columns, c)
					}
				}
			}
			if a := fkBlock.Body.attr("ref_columns"); a != nil {
				refs := refListColumns(a.Expr)
				// RefTable resolved after all tables exist.
				for _, r := range refs {
					fk.RefColumns = append(fk.RefColumns, &schema.Column{Name: r.column})
					// stash table name in first ref column type? We'll resolve below using refs list again.
					_ = r
				}
				// Store pending ref info on the foreign key via RefTable placeholder name.
				if len(refs) > 0 && refs[0].table != "" {
					fk.RefTable = &schema.Table{Name: refs[0].table}
				}
			}
			if a := fkBlock.Body.attr("on_update"); a != nil {
				if parts := refParts(a.Expr); len(parts) > 0 {
					fk.OnUpdate = parts[len(parts)-1]
				}
			}
			if a := fkBlock.Body.attr("on_delete"); a != nil {
				if parts := refParts(a.Expr); len(parts) > 0 {
					fk.OnDelete = parts[len(parts)-1]
				}
			}
			t.ForeignKeys = append(t.ForeignKeys, fk)
		}
		// checks
		for _, chkBlock := range tblBlock.Body.blocksOf("check") {
			if es, ok := stringAttr(chkBlock.Body, "expr"); ok {
				t.Checks = append(t.Checks, &schema.Check{Expr: es})
			}
		}
	}
	// views and other block types: view requires 'as'
	for _, vBlock := range doc.blocksOf("view") {
		if len(vBlock.Labels) >= 1 {
			if vBlock.Body.attr("as") == nil {
				return nil, fmt.Errorf("sqlite: failed converting to *schema.Realm: cannot convert view %q: missing 'as' definition for view %q", vBlock.Labels[0], vBlock.Labels[0])
			}
		}
	}
	// Resolve foreign key ref tables and ref columns against realm tables.
	for _, s := range realm.Schemas {
		for _, t := range s.Tables {
			for _, fk := range t.ForeignKeys {
				if fk.RefTable != nil {
					if rt := s.Table(fk.RefTable.Name); rt != nil {
						fk.RefTable = rt
						for i, rc := range fk.RefColumns {
							if c := rt.Column(rc.Name); c != nil {
								fk.RefColumns[i] = c
							}
						}
					}
				}
			}
		}
	}
	var _ = strconv.Quote
	return realm, nil
}
EOF

