package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// community texts
const communityErrorText = "You're running the community build of Atlas, which may differ from the official version.\nIf this error persists, try installing the official version as a troubleshooting step:\n\n  curl -sSf https://atlasgo.sh | sh\n\nMore installation options: https://atlasgo.io/docs#installation\n"

const communityNoticeText = "Notice: This Atlas edition lacks support for features such as checkpoints,\ntesting, down migrations, and more. Additionally, advanced database objects such as views, \ntriggers, and stored procedures are not supported. To read more: https://atlasgo.io/community-edition\n\nTo install the non-community version of Atlas, use the following command:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nOr, visit the website to see all installation options:\n\n\thttps://atlasgo.io/docs#installation\n\n"

const communityInstallText = "\nTo install the non-community version of Atlas, use the following command:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nOr, visit the website to see all installation options:\n\n\thttps://atlasgo.io/docs#installation\n"

type abortError struct {
	msg string
}

func (e *abortError) Error() string { return e.msg }

func communityAbort(cmdName, flag string) error {
	return &abortError{msg: fmt.Sprintf("Abort: 'atlas %s %s' is not supported by the community version.\n%s\n", cmdName, flag, communityInstallText)}
}

type silentError struct{}

func (e *silentError) Error() string { return "" }

// shouldPrintCommunityNotice / error helpers implement the once-per-period
// suggestion files under ~/.atlas .

func atlasHomeDir() (string, bool) {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return "", false
	}
	return filepath.Join(home, ".atlas"), true
}

// readSuggestionFile parses a {"key": "RFC3339 time"} file.
// Returns (zeroTime, ok) where ok=false means the file could not be
// read/parsed as JSON with a parsable time (in which case no suggestion
// is shown). A missing file or a parsed object without the key yields
// the zero time and ok=true.
func readSuggestionFile(path, key string) (time.Time, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return time.Time{}, true
		}
		return time.Time{}, false
	}
	// parse minimal JSON object
	// values are strings
	m, perr := parseSimpleJSONObject(string(data))
	if perr != nil {
		return time.Time{}, false
	}
	v, ok := m[key]
	if !ok {
		return time.Time{}, true
	}
	if v == "" {
		return time.Time{}, false
	}
	t, terr := time.Parse(time.RFC3339Nano, v)
	if terr != nil {
		// try RFC3339
		t2, terr2 := time.Parse(time.RFC3339, v)
		if terr2 != nil {
			return time.Time{}, false
		}
		t = t2
	}
	return t, true
}

func parseSimpleJSONObject(s string) (map[string]string, error) {
	s = strings.TrimSpace(s)
	if !strings.HasPrefix(s, "{") || !strings.HasSuffix(s, "}") {
		return nil, fmt.Errorf("not an object")
	}
	inner := strings.TrimSpace(s[1 : len(s)-1])
	out := map[string]string{}
	if inner == "" {
		return out, nil
	}
	// split top level commas (values are simple strings/numbers here)
	var parts []string
	depth := 0
	inStr := false
	start := 0
	for i := 0; i < len(inner); i++ {
		c := inner[i]
		if inStr {
			if c == '\\' {
				i++
			} else if c == '"' {
				inStr = false
			}
			continue
		}
		switch c {
		case '"':
			inStr = true
		case '{', '[':
			depth++
		case '}', ']':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, inner[start:i])
				start = i + 1
			}
		}
	}
	parts = append(parts, inner[start:])
	for _, part := range parts {
		kv := strings.SplitN(part, ":", 2)
		if len(kv) != 2 {
			return nil, fmt.Errorf("invalid object")
		}
