package main

import (
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

type varFlag struct {
	values []string
	kv     map[string]string
	order  []string
}

func (v *varFlag) String() string {
	if v == nil || len(v.values) == 0 {
		return "[]"
	}
	return fmt.Sprintf("%v", v.values)
}
func (v *varFlag) Set(s string) error {
	i := strings.Index(s, "=")
	if i < 0 {
		return fmt.Errorf("variables must be format as key=value, got: %q", s)
	}
	if v.kv == nil {
		v.kv = map[string]string{}
	}
	k := s[:i]
	if _, ok := v.kv[k]; !ok {
		v.order = append(v.order, k)
	}
	v.kv[k] = s[i+1:]
	v.values = append(v.values, s)
	return nil
}
func (v *varFlag) Type() string { return "<name>=<value>" }

type envConfig struct {
	Name           string
	URL            string
	Dev            string
	Schemas        []string
	Src            []string
	MigrationDir   string
	MigrationFormat string
	Attrs          map[string]value
}

type project struct {
	envs       map[string]*envConfig
	envOrder   []string
	vars       map[string]value
	selected   *envConfig
	filename   string
}

type globals struct {
	configFile string
	envName    string
	vars       varFlag
	proj       *project
}

var globalState = &globals{}

// shouldLoadConfig reports whether config loading is triggered.
func shouldLoadConfig(cmd flagGetter) bool {
	if globalState.envName != "" {
		return true
	}
	if cmd != nil && cmd.flagChanged("config") {
		return true
	}
	return false
}

type flagGetter interface {
	flagChanged(name string) bool
}

// cmdFlagAdapter adapts a cobra command to flagGetter in commands.go.

func loadProject(cmd flagGetter) error {
	if globalState.proj != nil {
		return nil
	}
	cfgURL := globalState.configFile
	if !strings.Contains(cfgURL, "://") {
		return fmt.Errorf("missing scheme for config file. Did you mean file://%s?", cfgURL)
	}
	uu, err := url.Parse(cfgURL)
	if err != nil {
		return err
	}
	if uu.Scheme != "file" {
		return fmt.Errorf("unsupported config file driver %q", uu.Scheme)
	}
	path := uu.Host + uu.Path
	fi, err := os.Stat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("config file %q was not found: stat %s: no such file or directory", path, path)
		}
		return fmt.Errorf("config file %q was not found: %s", path, err.Error())
	}
	if fi.IsDir() {
		return hclDiags{{Range: hclRange{}, Summary: "Failed to read file", Detail: fmt.Sprintf("The configuration file %q could not be read.", path)}}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return hclDiags{{Range: hclRange{}, Summary: "Failed to read file", Detail: fmt.Sprintf("The configuration file %q could not be read.", path)}}
	}
	doc, err := parseHCLFile(string(data), path)
	if err != nil {
		return err
	}
	proj, err := evaluateProject(doc, path)
	if err != nil {
		return err
	}
	globalState.proj = proj
	// select env if requested
	if globalState.envName != "" {
		name := globalState.envName
		var matches []*envConfig
		// envOrder preserves duplicates detection: evaluateProject stores by name but
		// we need counts. proj.envCounts holds counts.
		_ = matches
		count := proj.envCounts[name]
		if count > 1 {
			return fmt.Errorf("multiple envs found for %q", name)
		}
		env, ok := proj.envs[name]
		if !ok {
			return fmt.Errorf("env %q not defined in config file", name)
		}
		globalState.proj.selected = env
	}
	return nil
}

// evaluateProject parses variables, locals and (lazily) env definitions.
// Variables and locals are evaluated eagerly; env bodies are evaluated
// only when we need their raw attribute values for selection. To mirror
// the original, env attributes are evaluated during project loading for
// the selected env only - but evaluateProject does not know selection,
// so it evaluates all env attribute expressions that are literals/traversals
// into values via evalEnvBody for each env, catching errors only for the
// selected one later. Instead: we store raw env blocks and evaluate on demand
// in evaluateProject after determining selected name from globalState.

type projectRaw struct {
	doc      *body
	filename string
}

func evaluateProject(doc *body, filename string) (*project, error) {
	proj := &project{envs: map[string]*envConfig{}, vars: map[string]value{}, filename: filename, envCounts: map[string]int{}}
	baseDir := filepath.Dir(filename)
	ctx := &evalContext{filename: filename, baseDir: baseDir, vars: map[string]value{}, hasVars: true, locals: map[string]value{}}

	// Variables.
	type varDef struct {
		name    string
		typeStr string
		elemType string
		defExpr *expr
		hasDef  bool
		block   *block
	}
	var varDefs []*varDef
	seenVar := map[string]*varDef{}
	for _, vb := range doc.blocksOf("variable") {
		if len(vb.Labels) != 1 {
			continue
		}
		name := vb.Labels[0]
		// unsupported nested blocks
		if len(vb.Body.Blocks) > 0 {
			nb := vb.Body.Blocks[0]
			return nil, hclDiags{diagAt(filename, nb.typeTok.line, nb.typeTok.col, nb.typeTok.endLine, nb.typeTok.endCol, "Unsupported block type", fmt.Sprintf("Blocks of type %q are not expected here.", nb.Type))}
		}
		typeAttr := vb.Body.attr("type")
		if typeAttr == nil {
			return nil, hclDiags{diagAt(filename, vb.openBrace.line, vb.openBrace.col, vb.openBrace.line, vb.openBrace.col, "Missing required argument", "The argument \"type\" is required, but no definition was found.")}
		}
		typeStr, elem, err := parseVarType(typeAttr.Expr, filename)
		if err != nil {
			return nil, err
		}
		vd := &varDef{name: name, typeStr: typeStr, elemType: elem, block: vb}
		if da := vb.Body.attr("default"); da != nil {
			vd.defExpr = da.Expr
			vd.hasDef = true
		}
		if prev, ok := seenVar[name]; ok {
			// duplicate variable blocks: the later one replaces earlier? Original allowed.
			_ = prev
			// replace in list
			for i, d := range varDefs {
				if d.name == name {
					varDefs[i] = vd
				}
			}
		} else {
			varDefs = append(varDefs, vd)
		}
		seenVar[name] = vd
	}
	// Resolve variable values
	varsCtx := &evalContext{filename: filename, baseDir: baseDir, vars: map[string]value{}, hasVars: true}
	for _, vd := range varDefs {
		var val value
		var has bool
		if globalState.vars.kv != nil {
			if ov, ok := globalState.vars.kv[vd.name]; ok {
				val = strVal(ov)
				has = true
			}
		}
		if !has && vd.hasDef {
			dv, err := evalExpr(vd.defExpr, varsCtx)
			if err != nil {
				return nil, err
			}
			val = dv
			has = true
		}
		if !has {
			return nil, fmt.Errorf("missing value for required variable %q", vd.name)
		}
		conv, err := convertVarValue(vd.name, vd.typeStr, vd.elemType, val)
		if err != nil {
			return nil, err
		}
		proj.vars[vd.name] = conv
	}
	ctx.vars = proj.vars

	// Locals (eager)
	localExprs := map[string]*attr{}
	var localOrder []string
	for _, lb := range doc.blocksOf("locals") {
		for _, at := range lb.Body.AttrOrder {
			if _, exists := localExprs[at.Name]; !exists {
				localOrder = append(localOrder, at.Name)
			}
			localExprs[at.Name] = at
		}
	}
	if len(localExprs) > 0 {
		ctx.hasLocals = true
		ctx.localExprs = localExprs
		ctx.locals = map[string]value{}
		for _, name := range localOrder {
			if _, done := ctx.locals[name]; done {
				continue
			}
			ctx.localsResolving = map[string]bool{name: true}
			v, err := evalExpr(localExprs[name].Expr, ctx)
			ctx.localsResolving = nil
			if err != nil {
				return nil, err
			}
			ctx.locals[name] = v
		}
	}
	proj.evalCtx = ctx

	// Envs: record raw blocks; evaluate only selected later in loadProject path.
	// But evaluateProject is called before selection handling in loadProject;
	// globalState.envName is known here, so evaluate that env now.
	for _, eb := range doc.blocksOf("env") {
		if len(eb.Labels) != 1 {
			continue
		}
		name := eb.Labels[0]
		proj.envCounts[name]++
		if proj.envs[name] == nil {
			proj.envs[name] = &envConfig{Name: name, Attrs: map[string]value{}}
			proj.envOrder = append(proj.envOrder, name)
		}
		// store block for later evaluation (last/first?) Keep first matching block.
		if proj.envBlocks[name] == nil {
			proj.envBlocks[name] = eb
		}
	}
	// Evaluate selected env attributes if an env is requested (or even if not, when
	// this is called with a selection already set). If none selected, skip.
	selectedName := globalState.envName
	if selectedName != "" {
		if blk, ok := proj.envBlocks[selectedName]; ok {
			env, err := evaluateEnvBlock(blk, proj, filename, baseDir)
			if err != nil {
				return nil, err
			}
			proj.envs[selectedName] = env
		}
	}
	return proj, nil
}

func parseVarType(e *expr, filename string) (string, string, error) {
	switch e.kind {
	case exTraversal:
		if len(e.trav) == 1 {
			name := e.trav[0]
			switch name {
			case "string", "number", "bool", "list", "map", "set":
				return name, "", nil
			default:
				detail := fmt.Sprintf("There is no variable named %q.", name)
				if s := suggestVarType(name); s != "" {
					detail += fmt.Sprintf(" Did you mean %q?", s)
				}
				return "", "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown variable", detail)}
			}
		}
		return "", "", fmt.Errorf("invalid type for variable")
	case exFuncCall:
		if e.funcName == "list" || e.funcName == "map" || e.funcName == "set" {
			elem := ""
			if len(e.args) == 1 && e.args[0].kind == exTraversal && len(e.args[0].trav) == 1 {
				elem = e.args[0].trav[0]
			}
			return e.funcName, elem, nil
		}
		detail := fmt.Sprintf("There is no variable named %q.", e.funcName)
		return "", "", hclDiags{diagAt(filename, e.tok.line, e.tok.col, e.tok.endLine, e.tok.endCol, "Unknown variable", detail)}
	case exString:
		return "", "", fmt.Errorf("invalid type %q for variable", e.strVal)
	}
	return "", "", fmt.Errorf("invalid type for variable")
}

func suggestVarType(name string) string {
	candidates := []string{"string", "number", "bool", "list", "map", "set", "int", "integer", "text", "float", "double", "date", "datetime", "blob", "json", "uuid", "tinyint", "smallint", "bigint"}
	best := ""
	bestD := 100
	for _, c := range candidates {
		d := levenshtein(name, c)
		if d < bestD {
			bestD = d
			best = c
		}
	}
	if bestD <= 2 {
		return best
	}
	return ""
}

// convertVarValue converts a raw variable value to its declared type.
func convertVarValue(name, typeStr, elem string, v value) (value, error) {
	switch typeStr {
	case "string":
		// cty converts numbers/bools to string
		return strVal(v.toString()), nil
	case "number":
		if v.kind == vNumber {
			return v, nil
		}
		if v.kind == vString {
			if _, err := parseNumber(v.str); err == nil {
				return numVal(v.str), nil
			}
		}
		return nullVal(), fmt.Errorf("variable %q: a number is required", name)
	case "bool":
		if v.kind == vBool {
			return v, nil
		}
		if v.kind == vString && (v.str == "true" || v.str == "false") {
			return boolVal(v.str == "true"), nil
		}
		return nullVal(), fmt.Errorf("variable %q: a bool is required", name)
	case "list", "set":
		if v.kind != vList {
			return nullVal(), fmt.Errorf("variable %q: list is required", name)
		}
		// convert elements if elem is primitive
		for i, el := range v.list {
			cv, err := convertVarValue(name, elem, "", el)
			if err == nil && elem != "" {
				v.list[i] = cv
			}
		}
		return v, nil
	case "map":
		if v.kind != vObject {
			return nullVal(), fmt.Errorf("variable %q: map is required", name)
		}
		return v, nil
	}
	return v, nil
}

func parseNumber(s string) (float64, error) {
	var f float64
	_, err := fmt.Sscanf(s, "%g", &f)
	// stricter: use strconv
	return parseFloatStrict(s)
}

func evaluateEnvBlock(blk *block, proj *project, filename, baseDir string) (*envConfig, error) {
	env := &envConfig{Name: blk.Labels[0], Attrs: map[string]value{}}
	ctx := proj.evalCtx
	ctx.atlasEnv = blk.Labels[0]
	// Evaluate attributes in order.
	for _, at := range blk.Body.AttrOrder {
		v, err := evalExpr(at.Expr, ctx)
		if err != nil {
			return nil, err
		}
		env.Attrs[at.Name] = v
	}
	// Decode known fields.
	if v, ok := env.Attrs["url"]; ok {
		if v.kind != vString {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: value of attr \"url\" cannot be read as string: string value is required")
		}
		env.URL = v.str
	}
	if v, ok := env.Attrs["dev"]; ok {
		if v.kind != vString {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: value of attr \"dev\" cannot be read as string: string value is required")
		}
		env.Dev = v.str
	}
	if v, ok := env.Attrs["schemas"]; ok {
		if v.kind != vList {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: schemahcl: field is of type slice but attr \"schemas\" is type: %s", valueTypeName(v))
		}
		for _, el := range v.list {
			env.Schemas = append(env.Schemas, el.toString())
		}
	}
	if v, ok := env.Attrs["schema"]; ok {
		// schema as a single value is decoded as *cmdapi.Schema (object)
		if v.kind != vObject && v.kind != vList {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: set field \"schema\": converting cty.Value to *cmdapi.Schema: object or tuple value is required")
		}
		if v.kind == vList && len(v.list) > 0 {
			for _, el := range v.list {
				env.Schemas = append(env.Schemas, el.toString())
			}
		}
	}
	if v, ok := env.Attrs["src"]; ok {
		if v.kind == vString {
			env.Src = []string{v.str}
		} else if v.kind == vList {
			for _, el := range v.list {
				env.Src = append(env.Src, el.toString())
			}
		} else {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: schemahcl: field is of type slice but attr \"src\" is type: %s", valueTypeName(v))
		}
	}
	if v, ok := env.Attrs["migration"]; ok {
		if v.kind != vObject {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: set field \"migration\": converting cty.Value to *cmdapi.Migration: object or tuple value is required")
		}
		if len(v.keys) > 0 {
			return nil, fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: set field \"migration\": converting cty.Value to *cmdapi.Migration: unsupported attribute %q", v.keys[0])
		}
	}
	// Nested blocks: migration { dir = ..., format = ... }
	for _, mb := range blk.Body.blocksOf("migration") {
		for _, at := range mb.Body.AttrOrder {
			v, err := evalExpr(at.Expr, ctx)
			if err != nil {
				return nil, err
			}
			switch at.Name {
			case "dir":
				env.MigrationDir = v.toString()
			case "format":
				env.MigrationFormat = v.toString()
			}
		}
	}
	return env, nil
}

func valueTypeName(v value) string {
	switch v.kind {
	case vString:
		return "string"
	case vNumber:
		return "number"
	case vBool:
		return "bool"
	case vList:
		return "tuple"
	case vObject:
		return "object"
	case vNull:
		return "null"
	}
	return "string"
}
EOF
"}

