// cmdFlagAdapter adapts a cobra command to flagGetter in commands.go.

func loadProject(cmd flagGetter) error {
	if globalState.proj != nil {
		return nil
	}
	cfgURL := globalState.configFile
	if !strings.Contains(cfgURL, "://") {
		return fmt.Errorf("missing scheme for config file. Did you mean file://%s?", cfgURL)
	}
	uu, err := url.Parse(cfgURL)
	if err != nil {
		return err
	}
	if uu.Scheme != "file" {
		return fmt.Errorf("unsupported config file driver %q", uu.Scheme)
	}
	path := uu.Host + uu.Path
	fi, err := os.Stat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("config file %q was not found: stat %s: no such file or directory", path, path)
		}
		return fmt.Errorf("config file %q was not found: %s", path, err.Error())
	}
	if fi.IsDir() {
		return hclDiags{{Range: hclRange{}, Summary: "Failed to read file", Detail: fmt.Sprintf("The configuration file %q could not be read.", path)}}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return hclDiags{{Range: hclRange{}, Summary: "Failed to read file", Detail: fmt.Sprintf("The configuration file %q could not be read.", path)}}
	}
	doc, err := parseHCLFile(string(data), path)
	if err != nil {
		return err
	}
	proj, err := evaluateProject(doc, path)
	if err != nil {
		return err
	}
	globalState.proj = proj
	// select env if requested
	if globalState.envName != "" {
		name := globalState.envName
		var matches []*envConfig
		// envOrder preserves duplicates detection: evaluateProject stores by name but
		// we need counts. proj.envCounts holds counts.
		_ = matches
		count := proj.envCounts[name]
		if count > 1 {
			return fmt.Errorf("multiple envs found for %q", name)
		}
		env, ok := proj.envs[name]
		if !ok {
			return fmt.Errorf("env %q not defined in config file", name)
		}
		globalState.proj.selected = env
	}
	return nil
}

