{"command":"cat > commands.go <<'EOF'
package main

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// flag adapter helpers

type cobraFlagGetter struct{ cmd *cobra.Command }

func (a cobraFlagGetter) flagChanged(name string) bool {
	if a.cmd == nil {
		return false
	}
	if f := lookupFlag(a.cmd, name); f != nil {
		return f.Changed
	}
	return false
}

func lookupFlag(cmd *cobra.Command, name string) *pflag.Flag {
	if f := cmd.Flags().Lookup(name); f != nil {
		return f
	}
	if f := cmd.InheritedFlags().Lookup(name); f != nil {
		return f
	}
	if f := cmd.PersistentFlags().Lookup(name); f != nil {
		return f
	}
	if cmd.Parent() != nil {
		if f := cmd.Parent().PersistentFlags().Lookup(name); f != nil {
			return f
		}
	}
	return nil
}

func flagChanged(cmd *cobra.Command, name string) bool {
	f := lookupFlag(cmd, name)
	return f != nil && f.Changed
}

func getStringFlag(cmd *cobra.Command, name string) string {
	f := lookupFlag(cmd, name)
	if f == nil {
		return ""
	}
	return f.Value.String()
}

func setFlagIfNotChanged(cmd *cobra.Command, name, value string) {
	if value == "" {
		return
	}
	f := lookupFlag(cmd, name)
	if f == nil || f.Changed {
		return
	}
	_ = f.Value.Set(value)
	f.Changed = true
}

func setSliceFlagIfNotChanged(cmd *cobra.Command, name string, values []string) {
	if len(values) == 0 {
		return
	}
	f := lookupFlag(cmd, name)
	if f == nil || f.Changed {
		return
	}
	// only for slice-typed flags
	t := f.Value.Type()
	if t != "stringSlice" && t != "stringArray" {
		return
	}
	for _, v := range values {
		_ = f.Value.Set(v)
	}
	f.Changed = true
}

func parentPersistentPreRun(cmd *cobra.Command, args []string) error {
	if !shouldLoadConfig(cobraFlagGetter{cmd}) {
		return nil
	}
	if err := loadProject(cobraFlagGetter{cmd}); err != nil {
		return err
	}
	applyEnvToCommand(cmd)
	return nil
}

func applyEnvToCommand(cmd *cobra.Command) {
	if globalState.proj == nil || globalState.proj.selected == nil {
		return
	}
	env := globalState.proj.selected
	setFlagIfNotChanged(cmd, "url", env.URL)
	setFlagIfNotChanged(cmd, "dev-url", env.Dev)
	setSliceFlagIfNotChanged(cmd, "schema", env.Schemas)
	setSliceFlagIfNotChanged(cmd, "schemas", env.Schemas)
	setSliceFlagIfNotChanged(cmd, "to", env.Src)
	setFlagIfNotChanged(cmd, "dir", env.MigrationDir)
	if env.MigrationFormat != "" {
		setFlagIfNotChanged(cmd, "dir-format", env.MigrationFormat)
	}
	if v, ok := env.Attrs["revisions_schema"]; ok {
		setFlagIfNotChanged(cmd, "revisions-schema", v.toString())
	}
	if v, ok := env.Attrs["revisions-schema"]; ok {
		setFlagIfNotChanged(cmd, "revisions-schema", v.toString())
	}
}

func addGlobalFlags(cmd *cobra.Command) {
	cmd.PersistentFlags().StringVarP(&globalState.configFile, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	cmd.PersistentFlags().StringVar(&globalState.envName, "env", "", "set which env from the config file to use")
	cmd.PersistentFlags().Var(&globalState.vars, "var", "input variables")
}

func init() {
	rootCmd = &cobra.Command{
		Use:           "atlas",
		Short:         "Manage your database schema as code",
		SilenceUsage:  true,
		SilenceErrors: true,
	}
	versionCmd := &cobra.Command{
		Use:   "version",
		Short: "Prints this Atlas CLI version information.",
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Fprintln(cmd.OutOrStdout(), "atlas unofficial version - development")
