			fmt.Fprintln(cmd.OutOrStdout(), "To download an official version, visit: https://atlasgo.io/getting-started#installation")
		},
	}
	licenseCmd := &cobra.Command{
		Use:   "license",
		Short: "Display license information",
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Fprintln(cmd.OutOrStdout(), "LICENSE")
			fmt.Fprintln(cmd.OutOrStdout(), "Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.")
		},
	}
	migrateCmd := &cobra.Command{
		Use:               "migrate",
		Short:             "Manage versioned migration files",
		Long:              "'atlas migrate' wraps several sub-commands for migration management.",
		PersistentPreRunE: parentPersistentPreRun,
		Run: func(cmd *cobra.Command, args []string) {
			_ = cmd.Help()
		},
	}
	addGlobalFlags(migrateCmd)
	schemaCmd := &cobra.Command{
		Use:               "schema",
		Short:             "Work with atlas schemas.",
		Long:              "The `atlas schema` command groups subcommands working with declarative Atlas schemas.",
		PersistentPreRunE: parentPersistentPreRun,
		Run: func(cmd *cobra.Command, args []string) {
			_ = cmd.Help()
		},
	}
	addGlobalFlags(schemaCmd)

	rootCmd.AddCommand(versionCmd)
	rootCmd.AddCommand(licenseCmd)
	rootCmd.AddCommand(migrateCmd)
	rootCmd.AddCommand(schemaCmd)
	rootCmd.AddCommand(newCompletionCommand())

	// migrate subcommands
	migrateCmd.AddCommand(newMigrateApplyCmd())
	migrateCmd.AddCommand(newMigrateDiffCmd())
	migrateCmd.AddCommand(newMigrateHashCmd())
	migrateCmd.AddCommand(newMigrateImportCmd())
	migrateCmd.AddCommand(newMigrateLintCmd())
	migrateCmd.AddCommand(newMigrateNewCmd())
	migrateCmd.AddCommand(newMigrateSetCmd())
	migrateCmd.AddCommand(newMigrateStatusCmd())
	migrateCmd.AddCommand(newMigrateValidateCmd())

	// schema subcommands
	schemaCmd.AddCommand(newSchemaApplyCmd())
	schemaCmd.AddCommand(newSchemaCleanCmd())
	schemaCmd.AddCommand(newSchemaDiffCmd())
	schemaCmd.AddCommand(newSchemaFmtCmd())
	schemaCmd.AddCommand(newSchemaInspectCmd())

	// completion command's parent run should print help
	_ = strings.TrimSpace
}
EOF
