function.arguments:
{"command":"cat > state.go <<'EOF'
package main

import (
	"fmt"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"atlas/schema"
)

type stateKind int

const (
	kindDB stateKind = iota
	kindHCL
	kindSQL
	kindMigration
)

type stateClass struct {
	raw       string
	scheme    string
	isFile    bool
	filePath  string // filesystem path
	versionQ  string
	kind      stateKind
	files     []stateFile // expanded files (for file/dir)
	isDir     bool
	dirPath   string // path as provided (for error messages)
}

type stateFile struct {
	path string // fs path
	name string // basename
	kind stateKind // HCL or SQL
}

func innerURLError(err error) error {
	type unwrapper interface{ Unwrap() error }
	if ue, ok := err.(unwrapper); ok && ue.Unwrap() != nil {
		return ue.Unwrap()
	}
	return err
}

// classifyStateURLs validates URLs and returns classifications. It stats file
// paths and expands directories, but does not read state yet.
func classifyStateURLs(urls []string) ([]*stateClass, error) {
	var classes []*stateClass
	var nonEmpty []string
	for _, u := range urls {
		if u != "" {
			nonEmpty = append(nonEmpty, u)
		}
	}
	if len(nonEmpty) == 0 {
		return nil, fmt.Errorf("at least one url is required")
	}
	for _, raw := range nonEmpty {
		sc, err := classifyStateURL(raw)
		if err != nil {
			return nil, err
		}
		classes = append(classes, sc)
	}
	// mixed schemes check
	var schemes []string
	seen := map[string]bool{}
	for _, sc := range classes {
		if !seen[sc.scheme] {
			seen[sc.scheme] = true
			schemes = append(schemes, sc.scheme)
		}
	}
	if len(schemes) > 1 {
		var quoted []string
		for _, s := range schemes {
			quoted = append(quoted, fmt.Sprintf("%q", s))
		}
		joined := strings.Join(quoted, ", ")
		if len(quoted) == 2 {
			joined = quoted[0] + " and " + quoted[1]
		}
		return nil, fmt.Errorf("got mixed --to url schemes: %s, the desired state must be provided from a single kind of source", joined)
	}
	return classes, nil
}

func classifyStateURL(raw string) (*stateClass, error) {
	if !strings.Contains(raw, "://") {
		return nil, fmt.Errorf("missing scheme. Did you mean file://%s?", raw)
	}
	uu, err := url.Parse(raw)
	if err != nil {
		return nil, innerURLError(err)
	}
	scheme := uu.Scheme
	if scheme == "atlas" {
		return nil, fmt.Errorf("atlas remote state is not supported by the community version of Atlas.\n\nInstall the non-community version instead:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nFor more installtion options, see: https://atlasgo.io/docs#installation\n")
	}
	sc := &stateClass{raw: raw, scheme: scheme, versionQ: uu.Query().Get("version")}
	if scheme == "file" {
		sc.isFile = true
		fp := uu.Host + uu.Path
		sc.filePath = fp
		fi, err := os.Stat(fp)
		if err != nil {
			if os.IsNotExist(err) {
				return nil, fmt.Errorf("stat %s: no such file or directory", fp)
			}
			return nil, err
		}
		if fi.IsDir() {
			sc.isDir = true
			sc.dirPath = fp
			if err := expandDir(sc); err != nil {
				return nil, err
			}
		} else {
			ext := strings.ToLower(filepath.Ext(fp))
			name := filepath.Base(fp)
			switch ext {
			case ".hcl":
				sc.kind = kindHCL
				sc.files = []stateFile{{path: fp, name: name, kind: kindHCL}}
			case ".sql":
				sc.kind = kindSQL
				sc.files = []stateFile{{path: fp, name: name, kind: kindSQL}}
			default:
				return nil, fmt.Errorf("unknown schema file: %q", name)
			}
		}
		return sc, nil
	}
	if isKnownDriver(scheme) || scheme == "docker" {
		sc.kind = kindDB
		return sc, nil
	}
	return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", scheme)
}

func expandDir(sc *stateClass) error {
	entries, err := os.ReadDir(sc.filePath)
	if err != nil {
		return err
	}
	var files []stateFile
	hasSQL, hasHCL := false, false
	var firstSQL, firstHCL string
	hasSum := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if name == "atlas.sum" {
			hasSum = true
			continue
		}
		ext := strings.ToLower(filepath.Ext(name))
		switch ext {
		case ".sql":
			hasSQL = true
			if firstSQL == "" {
				firstSQL = name
			}
			files = append(files, stateFile{path: filepath.Join(sc.filePath, name), name: name, kind: kindSQL})
		case ".hcl":
			hasHCL = true
			if firstHCL == "" {
				firstHCL = name
			}
			files = append(files, stateFile{path: filepath.Join(sc.filePath, name), name: name, kind: kindHCL})
		}
	}
	if hasSQL && hasHCL {
		// names in encounter (sorted) order
		var ordered []string
		for _, f := range files {
			if f.kind == kindSQL && f.name == firstSQL {
				ordered = append(ordered, fmt.Sprintf("%q", firstSQL))
			}
			if f.kind == kindHCL && f.name == firstHCL {
				ordered = append(ordered, fmt.Sprintf("%q", firstHCL))
			}
		}
		if len(ordered) != 2 {
			ordered = []string{fmt.Sprintf("%q", firstHCL), fmt.Sprintf("%q", firstSQL)}
		}
		return fmt.Errorf("ambiguous schema: both SQL and HCL files found: %s, %s", ordered[0], ordered[1])
	}
	if hasSum || filepath.Base(sc.filePath) == "migrations" {
		// migration directory: keep SQL files as migration files
		sc.kind = kindMigration
		var mfiles []stateFile
		for _, f := range files {
			if f.kind == kindSQL {
				mfiles = append(mfiles, f)
			}
		}
		sc.files = mfiles
		return nil
	}
	if !hasSQL && !hasHCL {
		return fmt.Errorf("%q contains neither SQL nor HCL files", sc.dirPath)
	}
	if hasHCL {
		sc.kind = kindHCL
	} else {
		sc.kind = kindSQL
	}
	sc.files = files
	return nil
}

func classesNeedDev(classes []*stateClass) (hasFile, hasSQL bool) {
	for _, sc := range classes {
		if sc.isFile {
			hasFile = true
			if sc.kind == kindSQL || sc.kind == kindMigration {
				hasSQL = true
			}
		}
	}
	return
}

// openDevClient opens a dev-url client (sqlclient semantics).
func openDevClient(devRaw string) (*dbClient, error) {
	return openDBClient(devRaw)
}

// cleanDev drops all tables in a sqlite dev database.
func cleanDev(dev *dbClient) error {
	if dev == nil || dev.sqlite == nil {
		return nil
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		return err
	}
	var tables []string
	for _, s := range realm.Schemas {
		for _, t := range s.Tables {
			tables = append(tables, t.Name)
		}
	}
	if len(tables) == 0 {
		return nil
	}
	_ = dev.sqlite.Exec("PRAGMA foreign_keys = off")
	for _, t := range tables {
		if err := dev.sqlite.Exec("DROP TABLE IF EXISTS " + quoteSQLIdent(t)); err != nil {
			_ = dev.sqlite.Exec("PRAGMA foreign_keys = on")
			return err
		}
	}
	_ = dev.sqlite.Exec("PRAGMA foreign_keys = on")
	return nil
}

// createRealmOnDev creates the given realm's tables on the dev DB and returns
// the normalized (re-inspected) realm.
func createRealmOnDev(dev *dbClient, realm *schema.Realm) (*schema.Realm, error) {
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	if dev.driver == "sqlite" {
		if len(realm.Schemas) > 1 {
			return nil, fmt.Errorf("cannot use HCL with more than 1 schema when dev-url is limited to schema %q", "main")
		}
		if len(realm.Schemas) == 1 && realm.Schemas[0].Name != "main" {
			return nil, fmt.Errorf("mismatched HCL and database schemas: %q <> %q", "main", realm.Schemas[0].Name)
		}
	}
	changes := realmSQLPlan(realm, "")
	for _, ch := range changes {
		if err := dev.sqlite.Exec(ch.Cmd); err != nil {
			_ = cleanDev(dev)
			return nil, fmt.Errorf("sqlite: %s", err.Error())
		}
	}
	normalized, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return normalized, nil
}

// readState reads the realm for classified URLs.
// dev may be nil when no file state is present.
func readState(classes []*stateClass, dev *dbClient, schemas []string, excludes []string) (*schema.Realm, *dbClient, error) {
	// DB state (single kind enforced)
	if len(classes) > 0 && !classes[0].isFile {
		// multiple DB urls? inspect and merge (usually one)
		var merged *schema.Realm
		var lastClient *dbClient
		for _, sc := range classes {
			client, err := openDBClient(sc.raw)
			if err != nil {
				return nil, nil, err
			}
			lastClient = client
			if client.driver != "sqlite" {
				// other drivers: openDBClient already attempted connection and
				// would have errored; this is a fallback.
				return nil, nil, fmt.Errorf("%s: not supported in this build", client.driver)
			}
			realm, err := inspectSQLiteRealm(client)
			if err != nil {
				return nil, nil, err
			}
			applyExcludes(realm, excludes)
			if merged == nil {
				merged = realm
			} else {
				merged = mergeRealms(merged, realm)
			}
		}
		return merged, lastClient, nil
	}
	// File states.
	// Determine overall kind from classes (all file, same scheme but kinds may differ e.g. hcl file + sql file?)
	// classifyStateURLs only checks scheme mixing; HCL+SQL files together are ambiguous.
	var hclFiles, sqlFiles []stateFile
	var migrationDirs []*stateClass
	for _, sc := range classes {
		switch sc.kind {
		case kindHCL:
			hclFiles = append(hclFiles, sc.files...)
		case kindSQL:
			sqlFiles = append(sqlFiles, sc.files...)
		case kindMigration:
			migrationDirs = append(migrationDirs, sc)
		}
	}
	if len(hclFiles) > 0 && len(sqlFiles) > 0 {
		// first encountered of each in class order
		var names []string
		names = append(names, fmt.Sprintf("%q", hclFiles[0].name), fmt.Sprintf("%q", sqlFiles[0].name))
		return nil, nil, fmt.Errorf("ambiguous schema: both SQL and HCL files found: %s, %s", names[0], names[1])
	}
	if len(migrationDirs) > 0 {
		if dev == nil {
			return nil, nil, fmt.Errorf("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
		}
		sc := migrationDirs[0]
		realm, err := readMigrationDirState(sc, dev)
		if err != nil {
			return nil, nil, err
		}
		applyExcludes(realm, excludes)
		return realm, nil, nil
	}
	if len(hclFiles) > 0 {
		if dev == nil {
			return nil, nil, fmt.Errorf("--dev-url cannot be empty")
		}
		realm, err := readHCLFiles(hclFiles, schemas)
		if err != nil {
			return nil, nil, err
		}
		normalized, err := createRealmOnDev(dev, realm)
		if err != nil {
			return nil, nil, err
		}
		applyExcludes(normalized, excludes)
		return normalized, nil, nil
	}
	if len(sqlFiles) > 0 {
		if dev == nil {
			return nil, nil, fmt.Errorf("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
		}
		realm, err := readSQLFilesOnDev(sqlFiles, dev)
		if err != nil {
			return nil, nil, err
		}
		applyExcludes(realm, excludes)
		return realm, nil, nil
	}
	return &schema.Realm{}, nil, nil
}

func mergeRealms(a, b *schema.Realm) *schema.Realm {
	for _, bs := range b.Schemas {
		if as := a.Schema(bs.Name); as != nil {
			as.Tables = append(as.Tables, bs.Tables...)
			// fix schema pointers
			for _, t := range bs.Tables {
				t.Schema = as
			}
		} else {
			bs.Realm = a
			a.Schemas = append(a.Schemas, bs)
		}
	}
	return a
}

func readHCLFiles(files []stateFile, schemas []string) (*schema.Realm, error) {
	merged := &schema.Realm{}
	byName := map[string]*schema.Schema{}
	var hclPaths []string
	for _, f := range files {
		hclPaths = append(hclPaths, f.name)
		data, err := os.ReadFile(f.path)
		if err != nil {
			return nil, err
		}
		doc, err := parseHCLFile(string(data), f.name)
		if err != nil {
			return nil, err
		}
		realm, err := hclToRealm(doc, f.name)
		if err != nil {
			return nil, err
		}
		for _, s := range realm.Schemas {
			if existing, ok := byName[s.Name]; ok {
				for _, t := range s.Tables {
					t.Schema = existing
					existing.Tables = append(existing.Tables, t)
				}
			} else {
				s.Realm = merged
				merged.Schemas = append(merged.Schemas, s)
				byName[s.Name] = s
			}
		}
	}
	// requested schemas check
	if len(schemas) > 0 {
		for _, s := range merged.Schemas {
			found := false
			for _, req := range schemas {
				if req == s.Name {
					found = true
				}
			}
			if !found {
				var quoted []string
				for _, p := range hclPaths {
					quoted = append(quoted, fmt.Sprintf("%q", p))
				}
				return nil, fmt.Errorf("schema %q from paths [%s] is not requested (all schemas in HCL must be requested)", s.Name, strings.Join(quoted, " "))
			}
		}
	}
	return merged, nil
}

func readSQLFilesOnDev(files []stateFile, dev *dbClient) (*schema.Realm, error) {
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	for _, f := range files {
		data, err := os.ReadFile(f.path)
		if err != nil {
			return nil, err
		}
		stmts := splitSQLStatements(string(data))
		for _, stmt := range stmts {
			if err := dev.sqlite.Exec(stmt); err != nil {
				return nil, fmt.Errorf("read state from %q: executing statement: %q: %s", f.name, ensureSemicolon(stmt), trimSQLError(err))
			}
		}
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return realm, nil
}

func ensureSemicolon(s string) string {
	s = strings.TrimSpace(s)
	if strings.HasSuffix(s, ";") {
		return s
	}
	return s + ";"
}

func trimSQLError(err error) string {
	return err.Error()
}

// readMigrationDirState validates and replays a migration directory on dev.
func readMigrationDirState(sc *stateClass, dev *dbClient) (*schema.Realm, error) {
	dirPath := sc.filePath
	// Validate checksum
	files, err := loadMigrationDir(dirPath, sc.versionQ)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: read migration directory state: %w", err)
	}
	_ = files
	dir, err := openMigrationDir(sc.raw)
	_ = dir
	if err != nil {
		return nil, err
	}
	mfiles, verr := dirFilesValidate(dirPath)
	if verr != nil {
		return nil, fmt.Errorf("sql/migrate: read migration directory state: sql/migrate: validate migration directory: %s", verr.Error())
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	for _, mf := range mfiles {
		if sc.versionQ != "" && mf.Version() > sc.versionQ {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dirPath, mf.Name))
		if err != nil {
			return nil, err
		}
		stmts := splitSQLStatements(string(data))
		for _, stmt := range stmts {
			if err := dev.sqlite.Exec(stmt); err != nil {
				_ = cleanDev(dev)
				return nil, fmt.Errorf("sql/migrate: read migration directory state: sql/migrate: executing statement %q from version %q: %s", ensureSemicolon(stmt), mf.Version(), trimSQLError(err))
			}
		}
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return realm, nil
}

// applyExcludes filters a realm by exclude patterns.
func applyExcludes(r *schema.Realm, patterns []string) {
	if r == nil || len(patterns) == 0 {
		return
	}
	for _, s := range r.Schemas {
		var kept []*schema.Table
		for _, t := range s.Tables {
			if tableExcluded(t, patterns) {
				continue
			}
			filterTableContents(t, patterns)
			kept = append(kept, t)
		}
		s.Tables = kept
	}
}

func globMatch(pattern, name string) bool {
	ok, err := path.Match(pattern, name)
	return err == nil && ok
}

func tableExcluded(t *schema.Table, patterns []string) bool {
	for _, p := range patterns {
		parts := strings.Split(p, ".")
		if len(parts) == 1 && globMatch(parts[0], t.Name) {
			return true
		}
	}
	return false
}

func filterTableContents(t *schema.Table, patterns []string) {
	var twoPart []string
	for _, p := range patterns {
		parts := strings.Split(p, ".")
		if len(parts) == 2 && globMatch(parts[0], t.Name) {
			twoPart = append(twoPart, parts[1])
		}
	}
	if len(twoPart) == 0 {
		return
	}
	matches := func(name string) bool {
		for _, pat := range twoPart {
			if globMatch(pat, name) {
				return true
			}
		}
		return false
	}
	var cols []*schema.Column
	removedCols := map[string]bool{}
	for _, c := range t.Columns {
		if matches(c.Name) {
			removedCols[c.Name] = true
			continue
		}
		cols = append(cols, c)
	}
	// If a primary key column was removed, the pk is altered: keep parts as-is
	// (observed index references dangling columns); for columns the table
	// simply loses them.
	t.Columns = cols
	var idxs []*schema.Index
	for _, idx := range t.Indexes {
		if matches(idx.Name) {
			continue
		}
		idxs = append(idxs, idx)
	}
	t.Indexes = idxs
	var fks []*schema.ForeignKey
	for _, fk := range t.ForeignKeys {
		if matches(fk.Symbol) {
			continue
		}
		fks = append(fks, fk)
	}
	t.ForeignKeys = fks
	var checks []*schema.Check
	for _, chk := range t.Checks {
		// checks have no name; patterns like "*" match all under users.* (already handled
		// since "*" in twoPart matches any name; for checks we treat "*" as match)
		if len(twoPart) > 0 {
			for _, pat := range twoPart {
				if pat == "*" {
					checks = nil
					goto checksDone
				}
			}
		}
		checks = append(checks, chk)
	}
checksDone:
	t.Checks = checks
	_ = removedCols
	var _ = sort.Strings
}
EOF
"}

