package main

import (
	"fmt"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"atlas/schema"
)

type stateKind int

const (
	kindDB stateKind = iota
	kindHCL
	kindSQL
	kindMigration
)

type stateClass struct {
	raw       string
	scheme    string
	isFile    bool
	filePath  string // filesystem path
	versionQ  string
	kind      stateKind
	files     []stateFile // expanded files (for file/dir)
	isDir     bool
	dirPath   string // path as provided (for error messages)
}

type stateFile struct {
	path string // fs path
	name string // basename
	kind stateKind // HCL or SQL
}

func innerURLError(err error) error {
	type unwrapper interface{ Unwrap() error }
	if ue, ok := err.(unwrapper); ok && ue.Unwrap() != nil {
		return ue.Unwrap()
	}
	return err
}

// classifyStateURLs validates URLs and returns classifications. It stats file
// paths and expands directories, but does not read state yet.
func classifyStateURLs(urls []string) ([]*stateClass, error) {
	var classes []*stateClass
	var nonEmpty []string
	for _, u := range urls {
		if u != "" {
			nonEmpty = append(nonEmpty, u)
		}
	}
	if len(nonEmpty) == 0 {
		return nil, fmt.Errorf("at least one url is required")
	}
	for _, raw := range nonEmpty {
		sc, err := classifyStateURL(raw)
		if err != nil {
			return nil, err
		}
		classes = append(classes, sc)
	}
	// mixed schemes check
	var schemes []string
	seen := map[string]bool{}
	for _, sc := range classes {
		if !seen[sc.scheme] {
			seen[sc.scheme] = true
			schemes = append(schemes, sc.scheme)
		}
	}
	if len(schemes) > 1 {
		var quoted []string
		for _, s := range schemes {
			quoted = append(quoted, fmt.Sprintf("%q", s))
		}
		joined := strings.Join(quoted, ", ")
		if len(quoted) == 2 {
			joined = quoted[0] + " and " + quoted[1]
		}
		return nil, fmt.Errorf("got mixed --to url schemes: %s, the desired state must be provided from a single kind of source", joined)
	}
	return classes, nil
}

func classifyStateURL(raw string) (*stateClass, error) {
	if !strings.Contains(raw, "://") {
		return nil, fmt.Errorf("missing scheme. Did you mean file://%s?", raw)
	}
	uu, err := url.Parse(raw)
	if err != nil {
		return nil, innerURLError(err)
	}
	scheme := uu.Scheme
	if scheme == "atlas" {
		return nil, fmt.Errorf("atlas remote state is not supported by the community version of Atlas.\n\nInstall the non-community version instead:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nFor more installtion options, see: https://atlasgo.io/docs#installation\n")
	}
	sc := &stateClass{raw: raw, scheme: scheme, versionQ: uu.Query().Get("version")}
	if scheme == "file" {
		sc.isFile = true
		fp := uu.Host + uu.Path
		sc.filePath = fp
		fi, err := os.Stat(fp)
		if err != nil {
			if os.IsNotExist(err) {
				return nil, fmt.Errorf("stat %s: no such file or directory", fp)
			}
			return nil, err
		}
		if fi.IsDir() {
			sc.isDir = true
			sc.dirPath = fp
			if err := expandDir(sc); err != nil {
				return nil, err
			}
		} else {
			ext := strings.ToLower(filepath.Ext(fp))
			name := filepath.Base(fp)
			switch ext {
			case ".hcl":
				sc.kind = kindHCL
				sc.files = []stateFile{{path: fp, name: name, kind: kindHCL}}
			case ".sql":
				sc.kind = kindSQL
				sc.files = []stateFile{{path: fp, name: name, kind: kindSQL}}
			default:
				return nil, fmt.Errorf("unknown schema file: %q", name)
			}
		}
		return sc, nil
	}
	if isKnownDriver(scheme) || scheme == "docker" {
		sc.kind = kindDB
		return sc, nil
	}
	return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", scheme)
}

func expandDir(sc *stateClass) error {
	entries, err := os.ReadDir(sc.filePath)
	if err != nil {
		return err
	}
	var files []stateFile
	hasSQL, hasHCL := false, false
	var firstSQL, firstHCL string
	hasSum := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if name == "atlas.sum" {
			hasSum = true
			continue
		}
		ext := strings.ToLower(filepath.Ext(name))
		switch ext {
		case ".sql":
			hasSQL = true
			if firstSQL == "" {
				firstSQL = name
			}
			files = append(files, stateFile{path: filepath.Join(sc.filePath, name), name: name, kind: kindSQL})
		case ".hcl":
			hasHCL = true
			if firstHCL == "" {
				firstHCL = name
			}
			files = append(files, stateFile{path: filepath.Join(sc.filePath, name), name: name, kind: kindHCL})
		}
	}
	if hasSQL && hasHCL {
		// names in encounter (sorted) order
		var ordered []string
		for _, f := range files {
			if f.kind == kindSQL && f.name == firstSQL {
				ordered = append(ordered, fmt.Sprintf("%q", firstSQL))
			}
			if f.kind == kindHCL && f.name == firstHCL {
				ordered = append(ordered, fmt.Sprintf("%q", firstHCL))
			}
		}
		if len(ordered) != 2 {
			ordered = []string{fmt.Sprintf("%q", firstHCL), fmt.Sprintf("%q", firstSQL)}
		}
		return fmt.Errorf("ambiguous schema: both SQL and HCL files found: %s, %s", ordered[0], ordered[1])
	}
	if hasSum || filepath.Base(sc.filePath) == "migrations" {
		// migration directory: keep SQL files as migration files
		sc.kind = kindMigration
		var mfiles []stateFile
		for _, f := range files {
			if f.kind == kindSQL {
				mfiles = append(mfiles, f)
			}
		}
		sc.files = mfiles
		return nil
	}
	if !hasSQL && !hasHCL {
		return fmt.Errorf("%q contains neither SQL nor HCL files", sc.dirPath)
	}
	if hasHCL {
		sc.kind = kindHCL
	} else {
		sc.kind = kindSQL
	}
	sc.files = files
	return nil
}

func classesNeedDev(classes []*stateClass) (hasFile, hasSQL bool) {
	for _, sc := range classes {
		if sc.isFile {
			hasFile = true
			if sc.kind == kindSQL || sc.kind == kindMigration {
				hasSQL = true
			}
		}
	}
	return
}

// openDevClient opens a dev-url client (sqlclient semantics).
func openDevClient(devRaw string) (*dbClient, error) {
	return openDBClient(devRaw)
}

// cleanDev drops all tables in a sqlite dev database.
func cleanDev(dev *dbClient) error {
	if dev == nil || dev.sqlite == nil {
		return nil
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		return err
	}
	var tables []string
	for _, s := range realm.Schemas {
		for _, t := range s.Tables {
			tables = append(tables, t.Name)
		}
	}
	if len(tables) == 0 {
		return nil
	}
	_ = dev.sqlite.Exec("PRAGMA foreign_keys = off")
	for _, t := range tables {
		if err := dev.sqlite.Exec("DROP TABLE IF EXISTS " + quoteSQLIdent(t)); err != nil {
			_ = dev.sqlite.Exec("PRAGMA foreign_keys = on")
			return err
		}
	}
	_ = dev.sqlite.Exec("PRAGMA foreign_keys = on")
	return nil
}

// createRealmOnDev creates the given realm's tables on the dev DB and returns
// the normalized (re-inspected) realm.
func createRealmOnDev(dev *dbClient, realm *schema.Realm) (*schema.Realm, error) {
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	if dev.driver == "sqlite" {
		if len(realm.Schemas) > 1 {
			return nil, fmt.Errorf("cannot use HCL with more than 1 schema when dev-url is limited to schema %q", "main")
		}
		if len(realm.Schemas) == 1 && realm.Schemas[0].Name != "main" {
			return nil, fmt.Errorf("mismatched HCL and database schemas: %q <> %q", "main", realm.Schemas[0].Name)
		}
	}
	changes := realmSQLPlan(realm, "")
	for _, ch := range changes {
		if err := dev.sqlite.Exec(ch.Cmd); err != nil {
			_ = cleanDev(dev)
			return nil, fmt.Errorf("sqlite: %s", err.Error())
		}
	}
	normalized, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return normalized, nil
}

// readState reads the realm for classified URLs.
// dev may be nil when no file state is present.
func readState(classes []*stateClass, dev *dbClient, schemas []string, excludes []string) (*schema.Realm, *dbClient, error) {
	// DB state (single kind enforced)
	if len(classes) > 0 && !classes[0].isFile {
		// multiple DB urls? inspect and merge (usually one)
		var merged *schema.Realm
		var lastClient *dbClient
		for _, sc := range classes {
			client, err := openDBClient(sc.raw)
			if err != nil {
				return nil, nil, err
			}
			lastClient = client
			if client.driver != "sqlite" {
				// other drivers: openDBClient already attempted connection and
				// would have errored; this is a fallback.
				return nil, nil, fmt.Errorf("%s: not supported in this build", client.driver)
			}
			realm, err := inspectSQLiteRealm(client)
			if err != nil {
				return nil, nil, err
			}
			applyExcludes(realm, excludes)
			if merged == nil {
				merged = realm
			} else {
				merged = mergeRealms(merged, realm)
			}
		}
		return merged, lastClient, nil
	}
	// File states.
	// Determine overall kind from classes (all file, same scheme but kinds may differ e.g. hcl file + sql file?)
	// classifyStateURLs only checks scheme mixing; HCL+SQL files together are ambiguous.
	var hclFiles, sqlFiles []stateFile
	var migrationDirs []*stateClass
	for _, sc := range classes {
		switch sc.kind {
		case kindHCL:
			hclFiles = append(hclFiles, sc.files...)
		case kindSQL:
			sqlFiles = append(sqlFiles, sc.files...)
		case kindMigration:
			migrationDirs = append(migrationDirs, sc)
		}
	}
	if len(hclFiles) > 0 && len(sqlFiles) > 0 {
		// first encountered of each in class order
		var names []string
