	"os"
	"path/filepath"
	"sort"
	"strings"

	"atlas/migrate"
)

var knownDirFormats = map[string]bool{
	"atlas": true, "goose": true, "flyway": true, "liquibase": true, "dbmate": true,
}

type migrationDir struct {
	path   string
	rawURL string
	format string
	files  []*migrate.File // sorted
}

func (d *migrationDir) filePath(name string) string { return filepath.Join(d.path, name) }

// parseMigrationDirURL parses a --dir style URL.
func parseMigrationDirURL(raw string) (path string, format string, err error) {
	if !strings.Contains(raw, "://") {
		return "", "", fmt.Errorf("missing scheme for dir url. Did you mean \"file://%s\"? ", raw)
	}
	uu, err := url.Parse(raw)
	if err != nil {
		return "", "", innerURLError(err)
	}
	if uu.Scheme != "file" {
		return "", "", fmt.Errorf("unsupported driver %q", uu.Scheme)
	}
	path = uu.Host + uu.Path
	format = uu.Query().Get("format")
	return path, format, nil
}

func openMigrationDirRaw(raw string) (*migrationDir, error) {
	return openMigrationDirWithFormat(raw, "atlas")
}

// openMigrationDir opens and lists a migration directory given a URL.
// dirFormatFlag is the --dir-format flag value; a "format" query parameter
// in the URL takes precedence.
func openMigrationDirWithFormat(raw, dirFormat string) (*migrationDir, error) {
	path, qformat, err := parseMigrationDirURL(raw)
	if err != nil {
		return nil, err
	}
	format := dirFormat
	if qformat != "" {
		format = qformat
	}
	if format == "" {
		format = "atlas"
	}
	if !knownDirFormats[format] {
		return nil, fmt.Errorf("unknown dir format %q", format)
	}
	fi, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: stat %s: no such file or directory", path)
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("sql/migrate: %q is not a dir", path)
	}
	d := &migrationDir{path: path, rawURL: raw, format: format}
	files, err := d.listFiles()
	if err != nil {
		return nil, err
	}
	d.files = files
	return d, nil
}

func (d *migrationDir) listFiles() ([]*migrate.File, error) {
	entries, err := os.ReadDir(d.path)
	if err != nil {
		return nil, err
	}
	var files []*migrate.File
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if name == "atlas.sum" {
			continue
		}
		if !d.includeFile(name) {
			continue
		}
		data, err := os.ReadFile(filepath.Join(d.path, name))
		if err != nil {
			return nil, err
		}
		files = append(files, &migrate.File{Name: name, Text: string(data)})
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Name < files[j].Name })
	return files, nil
}

func (d *migrationDir) includeFile(name string) bool {
	switch d.format {
	case "flyway":
		// Versioned migrations only: V<version>__<desc>.sql ; undo (U) and
		// repeatable (R) files are not treated as migrations for hashing.
		return strings.HasPrefix(name, "V") && strings.HasSuffix(name, ".sql")
	default:
		return strings.HasSuffix(name, ".sql")
	}
}

// refresh re-lists files from disk.
func (d *migrationDir) refresh() error {
	files, err := d.listFiles()
	if err != nil {
		return err
	}
	d.files = files
	return nil
}

// hashFile computes the atlas.sum contents for the directory's files.
type hashEntry struct {
	Name string
	Hash string // base64
}

func computeHash(files []*migrate.File) (total string, entries []hashEntry, fullText string) {
	cum := sha256.New()
	overall := sha256.New()
	for _, f := range files {
		cum.Write([]byte(f.Name))
		cum.Write([]byte(f.Text))
		per := base64.StdEncoding.EncodeToString(cum.Sum(nil))
		entries = append(entries, hashEntry{Name: f.Name, Hash: per})
		overall.Write([]byte(f.Name + per))
	}
	total = base64.StdEncoding.EncodeToString(overall.Sum(nil))
	var sb strings.Builder
	sb.WriteString("h1:" + total + "\n")
	for _, e := range entries {
		sb.WriteString(fmt.Sprintf("%s h1:%s\n", e.Name, e.Hash))
	}
	return total, entries, sb.String()
}

func (d *migrationDir) writeHash() error {
	if err := d.refresh(); err != nil {
		return err
	}
	_, _, text := computeHash(d.files)
	return os.WriteFile(filepath.Join(d.path, "atlas.sum"), []byte(text), 0o644)
}

// parsed sum file
type sumFile struct {
	total   string
	entries []hashEntry
	raw     string
}

var (
	errChecksumNotFound = fmt.Errorf("checksum file not found")
	errChecksumMismatch = fmt.Errorf("checksum mismatch")
	errChecksumFormat   = fmt.Errorf("checksum file format invalid")
)

func parseSumFile(data string) (*sumFile, error) {
	// Distinguish format-invalid: any line after the first that is not
	// "<name> h1:<hash>" triggers format invalid (when there is at least
	// a total line and entries).
	lines := strings.Split(data, "\n")
	// remove trailing empty line from final newline
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	if len(lines) == 0 {
		return &sumFile{total: ""}, nil
	}
	sf := &sumFile{raw: data}
	first := lines[0]
	if strings.HasPrefix(first, "h1:") {
		sf.total = strings.TrimPrefix(first, "h1:")
	} else {
		sf.total = first
		return sf, nil
	}
	for _, ln := range lines[1:] {
		if ln == "" {
			continue
		}
		parts := strings.SplitN(ln, " h1:", 2)
		if len(parts) != 2 || parts[0] == "" || parts[1] == "" || strings.Contains(parts[0], " ") {
			return nil, errChecksumFormat
		}
		sf.entries = append(sf.entries, hashEntry{Name: parts[0], Hash: parts[1]})
	}
	return sf, nil
}

// validate checks atlas.sum against the directory content.
// It returns (discrepancyLine, discrepancyText, err) where err is one of the checksum errors.
// discrepancyText like: "20240101000000_a.sql was edited" with line number.
func (d *migrationDir) validateSum() (discLine int, discText string, err error) {
	data, rerr := os.ReadFile(filepath.Join(d.path, "atlas.sum"))
	if rerr != nil {
		return 0, "", errChecksumNotFound
	}
	sf, perr := parseSumFile(string(data))
	if perr != nil {
		return 0, "", perr
	}
	if err := d.refresh(); err != nil {
		return 0, "", err
	}
	computedTotal, computedEntries, _ := computeHash(d.files)
	// Internal consistency of the stored file: total derived from entries.
	overall := sha256.New()
	for _, e := range sf.entries {
		overall.Write([]byte(e.Name + e.Hash))
	}
	derivedTotal := base64.StdEncoding.EncodeToString(overall.Sum(nil))
	mismatch := false
	if sf.total != derivedTotal {
		// Only considered if there are entries or the total is otherwise wrong:
		// For an empty migration dir, derived is the empty hash and a valid file matches.
		mismatch = true
	}
	if sf.total != computedTotal {
		mismatch = true
	}
	if len(sf.entries) != len(computedEntries) {
		mismatch = true
	} else {
		for i := range sf.entries {
			if sf.entries[i] != computedEntries[i] {
				mismatch = true
			}
		}
	}
	if !mismatch {
		return 0, "", nil
	}
	// Discrepancies only when stored total differs from computed total.
	if sf.total != computedTotal {
		discLine, discText = firstDiscrepancy(sf.entries, computedEntries)
	}
	return discLine, discText, errChecksumMismatch
}

func firstDiscrepancy(stored, computed []hashEntry) (int, string) {
	// Walk jointly.
	i, j := 0, 0
	for i < len(stored) || j < len(computed) {
		if i < len(stored) && j < len(computed) && stored[i].Name == computed[j].Name && stored[i].Hash == computed[j].Hash {
			i++
			j++
			continue
		}
		// stored exhausted -> computed added
		if i >= len(stored) {
			return j + 2, fmt.Sprintf("%s was added", computed[j].Name)
		}
		if j >= len(computed) {
			return i + 2, fmt.Sprintf("%s was removed", stored[i].Name)
		}
		if stored[i].Name == computed[j].Name {
			return j + 2, fmt.Sprintf("%s was edited", computed[j].Name)
		}
		// Names differ: decide added vs removed by lookahead.
		storedInComputed := false
		for k := j; k < len(computed); k++ {
			if computed[k].Name == stored[i].Name {
				storedInComputed = true
			}
		}
		computedInStored := false
		for k := i; k < len(stored); k++ {
			if stored[k].Name == computed[j].Name {
				computedInStored = true
			}
		}
		if storedInComputed && !computedInStored {
			return j + 2, fmt.Sprintf("%s was added", computed[j].Name)
		}
		// default (including rename): removed
		return i + 2, fmt.Sprintf("%s was removed", stored[i].Name)
	}
	return 0, ""
}

// dirFilesValidate used by state reading: returns error with unprefixed message
// ("checksum file not found" / "checksum mismatch" / "checksum file format invalid")
func dirFilesValidate(path string) error {
	d := &migrationDir{path: path, format: "atlas"}
	_, _, err := d.validateSum()
	return err
}

// loadMigrationDir is a small helper used by state.go; it validates the URL is
// a dir and returns its files. Errors are raw (callers prefix).
func loadMigrationDir(path, version string) ([]*migrate.File, error) {
	d := &migrationDir{path: path, format: "atlas"}
	files, err := d.listFiles()
	if err != nil {
		return nil, err
	}
	_ = version
	return files, nil
}

func openMigrationDir(raw string) (*migrationDir, error) {
	// Used by state reading where the dir was referred to as file://... :
	// path may be a plain filesystem path.
	if strings.Contains(raw, "://") {
		return openMigrationDirRaw(raw)
	}
	d := &migrationDir{path: raw, rawURL: raw, format: "atlas"}
	files, err := d.listFiles()
	if err != nil {
		return nil, err
	}
	d.files = files
	return d, nil
}

var _ = io.EOF
EOF
"}

