package main

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"strings"
	"time"

	"atlas/migrate"
)

const revisionsTableSQL = "CREATE TABLE `atlas_schema_revisions` (`version` text NOT NULL, `description` text NOT NULL, `type` integer NOT NULL DEFAULT (2), `applied` integer NOT NULL DEFAULT (0), `total` integer NOT NULL DEFAULT (0), `executed_at` datetime NOT NULL, `execution_time` integer NOT NULL, `error` text NULL, `error_stmt` text NULL, `hash` text NOT NULL, `partial_hashes` json NULL, `operator_version` text NOT NULL, PRIMARY KEY (`version`))"

type revision struct {
	Version       string
	Description   string
	Type          int64
	Applied       int64
	Total         int64
	ExecutedAt    string
	ExecutionTime int64
	Error         string
	ErrorStmt     string
	Hash          string
	PartialHashes string // raw text/blob
}

func fileHash(f *migrate.File) string {
	h := sha256.Sum256([]byte(f.Name + f.Text))
	return base64.StdEncoding.EncodeToString(h[:])
}

func stmtHash(stmt string) string {
	h := sha256.Sum256([]byte(stmt))
	return "h1:" + base64.StdEncoding.EncodeToString(h[:])
}

// ensureRevisionsTable creates the revisions table if needed and returns revisions.
// For sqlite, a separate revisions schema is only rejected when writing (apply/set);
// here we always use the main schema table.
func ensureRevisionsTable(c *dbClient) ([]*revision, error) {
	if c.deferredErr != nil {
		return nil, sqliteErrPrefix(c.deferredErr)
	}
	if c.sqlite == nil {
		return nil, sqliteErrPrefix(fmt.Errorf("unable to open database file: no such file or directory"))
	}
	// The original first inspects schemas (surfacing open errors with that prefix).
	if _, err := inspectSQLiteRealm(c); err != nil {
		return nil, err
	}
	if err := c.sqlite.Exec(revisionsTableSQL); err != nil {
		// If the table already exists, Exec returns "table already exists"
		if strings.Contains(err.Error(), "already exists") {
			// ok
		} else {
			return nil, err
		}
	}
	return readRevisions(c)
}

func revisionsTableExists(c *dbClient) bool {
	if c.sqlite == nil {
		return false
	}
	row, ok, err := c.sqlite.QueryOne("SELECT name FROM sqlite_master WHERE type='table' AND name='atlas_schema_revisions'")
	return err == nil && ok && len(row.Vals) > 0
}

func readRevisions(c *dbClient) ([]*revision, error) {
	if !revisionsTableExists(c) {
		return nil, nil
	}
	rows, err := c.sqlite.Query("SELECT version, description, type, applied, total, executed_at, execution_time, error, error_stmt, hash, partial_hashes FROM atlas_schema_revisions")
	if err != nil {
		return nil, err
	}
	var revs []*revision
	for _, r := range rows {
		rev := &revision{
			Version:       valString(r.Vals[0]),
			Description:   valString(r.Vals[1]),
			Type:          valInt(r.Vals[2], 0),
			Applied:       valInt(r.Vals[3], 0),
			Total:         valInt(r.Vals[4], 0),
			ExecutedAt:    valString(r.Vals[5]),
			ExecutionTime: valInt(r.Vals[6], 0),
			Error:         valString(r.Vals[7]),
			ErrorStmt:     valString(r.Vals[8]),
			Hash:          valString(r.Vals[9]),
		}
		if len(r.Vals) > 10 && r.Vals[10] != nil {
			rev.PartialHashes = valString(r.Vals[10])
		}
		revs = append(revs, rev)
	}
	return revs, nil
}

func sqlQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func insertRevision(c *dbClient, rev *revision, partialHashes []string) error {
	ph := "null"
	if partialHashes != nil {
		// JSON array of hashes
		var parts []string
		for _, h := range partialHashes {
			parts = append(parts, fmt.Sprintf("%q", h))
		}
		ph = "[" + strings.Join(parts, ",") + "]"
		// stored as blob in original; CAST to blob below
	}
	// Use CAST('...' AS BLOB) for partial_hashes to mimic blob storage of 'null'/JSON.
	phExpr := fmt.Sprintf("CAST(%s AS BLOB)", sqlQuote(ph))
	if partialHashes == nil {
		phExpr = "CAST('null' AS BLOB)"
	} else if len(partialHashes) == 0 {
		phExpr = "CAST('[]' AS BLOB)"
		// For partial errors with 0 applied statements, original may store []? We'll use this.
		ph = "[]"
		phExpr = "CAST('[]' AS BLOB)"
	}
	q := fmt.Sprintf("INSERT OR REPLACE INTO atlas_schema_revisions (version, description, type, applied, total, executed_at, execution_time, error, error_stmt, hash, partial_hashes, operator_version) VALUES (%s, %s, %d, %d, %d, %s, %d, %s, %s, %s, %s, %s)",
		sqlQuote(rev.Version), sqlQuote(rev.Description), rev.Type, rev.Applied, rev.Total, sqlQuote(rev.ExecutedAt), rev.ExecutionTime, sqlQuote(rev.Error), sqlQuote(rev.ErrorStmt), sqlQuote(rev.Hash), phExpr, sqlQuote("Atlas CLI - development"))
	_ = ph
	return c.sqlite.Exec(q)
}

func deleteRevision(c *dbClient, version string) error {
	return c.sqlite.Exec("DELETE FROM atlas_schema_revisions WHERE version = " + sqlQuote(version))
}

func nowTimestamp() string {
	return time.Now().UTC().Format("2006-01-02 15:04:05.999999999+00:00")
}

// statementsForFile splits a migration file's content according to its format.
func statementsForFile(f *migrate.File, format string) []string {
	content := f.Text
	switch format {
	case "goose":
		content = extractGooseUp(content)
	case "dbmate":
		content = extractDbmateUp(content)
	}
	stmts := splitSQLStatements(content)
	// Ensure each statement ends with ;
	for i, s := range stmts {
		stmts[i] = ensureSemicolon(s)
	}
	// Filter out pure comment statements? splitSQL returns comments attached.
	// Remove statements that are only comments/empty after stripping comments.
	var out []string
	for _, s := range stmts {
		if strings.TrimSpace(stripSQLComments(s)) == "" || strings.TrimSpace(stripSQLComments(s)) == ";" {
			continue
		}
		out = append(out, s)
	}
	return out
}

func stripSQLComments(s string) string {
	var b strings.Builder
	lines := strings.Split(s, "\n")
	for _, ln := range lines {
		t := strings.TrimSpace(ln)
		if strings.HasPrefix(t, "--") {
			continue
		}
		b.WriteString(ln + "\n")
	}
	return b.String()
}

func extractGooseUp(content string) string {
	// content between -- +goose Up and -- +goose Down
	lines := strings.Split(content, "\n")
	var out []string
	inUp := false
	for _, ln := range lines {
		t := strings.TrimSpace(ln)
		if strings.HasPrefix(t, "-- +goose Up") {
			inUp = true
			continue
		}
		if strings.HasPrefix(t, "-- +goose Down") {
			break
		}
		if strings.HasPrefix(t, "-- +goose StatementBegin") || strings.HasPrefix(t, "-- +goose StatementEnd") {
			continue
		}
		if inUp {
			out = append(out, ln)
		}
	}
	if !inUp && len(out) == 0 {
		// No goose markers: whole content
		return content
	}
	return strings.Join(out, "\n")
}

func extractDbmateUp(content string) string {
	lines := strings.Split(content, "\n")
	var out []string
	inUp := false
	saw := false
	for _, ln := range lines {
		t := strings.TrimSpace(ln)
		if strings.HasPrefix(t, "-- migrate:up") {
			inUp = true
			saw = true
			continue
		}
		if strings.HasPrefix(t, "-- migrate:down") {
			break
		}
		if inUp {
			out = append(out, ln)
		}
	}
	if !saw {
		return content
	}
	return strings.Join(out, "\n")
}
EOF
"}

