{"command":"cat > prompt.go <<'EOF'
package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"syscall"
	"unsafe"
)

var errInterrupt = errors.New("interrupt")

func optionLine(idx, sel int, options []string) string {
	if idx == sel {
		return fmt.Sprintf("  \x1b[1m▸\x1b[0m \x1b[4m%s\x1b[0m", options[idx])
	}
	return "    " + options[idx]
}

func renderInitial(out io.Writer, sel int, options []string) {
	fmt.Fprint(out, "\x1b[?25l")
	fmt.Fprint(out, "\x1b[2K\n\x1b[34m?\x1b[0m Are you sure?: \n")
	fmt.Fprint(out, "\x1b[2K\n"+optionLine(0, sel, options)+"\n")
	fmt.Fprint(out, "\x1b[2K\n"+optionLine(1, sel, options)+"\n")
}

func renderAgain(out io.Writer, sel int, options []string) {
	fmt.Fprint(out, "\x1b[1A\x1b[1A\x1b[1A")
	fmt.Fprint(out, "\x1b[2K\n\x1b[34m?\x1b[0m Are you sure?: \x1b[1B")
	fmt.Fprint(out, "\x1b[2K\n"+optionLine(0, sel, options)+"\x1b[1B")
	fmt.Fprint(out, "\x1b[2K\n"+optionLine(1, sel, options)+"\x1b[1B")
	fmt.Fprint(out, "\x1b[1A")
}

func renderCleanup(out io.Writer) {
	fmt.Fprint(out, "\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[2K\n")
}

func renderFinal(out io.Writer, selected string) {
	fmt.Fprintf(out, "\x1b[32m\x1b[32m✔\x1b[0m \x1b[2m%s\x1b[0m\n", selected)
	fmt.Fprint(out, "\x1b[?25h")
}

// termios handling for TTY stdin
type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

const ioctlReadTermios = 0x5401  // TCGETS
const ioctlWriteTermios = 0x5402 // TCSETS

func makeRaw(fd uintptr) (*termios, error) {
	var old termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(ioctlReadTermios), uintptr(unsafe.Pointer(&old)))
	if errno != 0 {
		return nil, errno
	}
	newState := old
	// ICANON | ECHO | ISIG etc off (cfmakeraw approximation)
	newState.Iflag &^= 0x1 | 0x2 | 0x10 | 0x20 | 0x40 | 0x100
	newState.Oflag &^= 0x1
	newState.Lflag &^= 0x2 | 0x1 | 0x8 | 0x8000
	newState.Cflag = (newState.Cflag &^ 0x100) | 0x30
	newState.Cc[6] = 1  // VMIN
	newState.Cc[5] = 0  // VTIME
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(&newState)))
	if errno != 0 {
		return nil, errno
	}
	return &old, nil
}

func restoreTerm(fd uintptr, old *termios) {
	syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(old)))
}

// promptSelect shows the Apply/Abort prompt. It returns (0=Apply,1=Abort,error).
// On ^D/EOF the error is fmt.Errorf("^D"); on Ctrl-C errInterrupt.
func promptSelect(in io.Reader, out io.Writer) (int, error) {
	options := []string{"Apply", "Abort"}
	// If stdin is a terminal, set raw mode.
	if f, ok := in.(*os.File); ok {
		if fi, err := f.Stat(); err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			if old, err := makeRaw(f.Fd()); err == nil {
				defer restoreTerm(f.Fd(), old)
			}
		}
	}
	r := bufio.NewReader(in)
	sel := 0
	renderInitial(out, sel, options)
	for {
		b, err := r.ReadByte()
		if err != nil {
			renderCleanup(out)
			fmt.Fprint(out, "\x1b[?25h")
			return 0, fmt.Errorf("^D")
		}
		switch b {
		case 3: // Ctrl-C
			renderCleanup(out)
			fmt.Fprint(out, "\x1b[?25h")
			return 1, errInterrupt
		case 4: // Ctrl-D
			renderCleanup(out)
			fmt.Fprint(out, "\x1b[?25h")
			return 0, fmt.Errorf("^D")
		case '\n', '\r':
			// Consume a following \n if \r\n? Survey reads runes; \r is Enter and the \n would
			// be an extra... In piped input \r\n gave a single final selection, so treat \r as enter
			// and do not process a trailing \n separately (we return immediately).
			renderAgain(out, sel, options)
			renderCleanup(out)
			renderFinal(out, options[sel])
			return sel, nil
		case 27: // ESC
			// Try to read sequence
			b2, err := r.ReadByte()
			if err != nil {
				renderCleanup(out)
				fmt.Fprint(out, "\x1b[?25h")
				return 0, fmt.Errorf("^D")
			}
			if b2 == '[' || b2 == 'O' {
				b3, err := r.ReadByte()
				if err != nil {
					renderCleanup(out)
					fmt.Fprint(out, "\x1b[?25h")
					return 0, fmt.Errorf("^D")
				}
				switch b3 {
				case 'B': // down
					sel = (sel + 1) % len(options)
				case 'A': // up
					sel = (sel - 1 + len(options)) % len(options)
				}
				renderAgain(out, sel, options)
				continue
			}
			renderAgain(out, sel, options)
			continue
		case 'j':
			sel = (sel + 1) % len(options)
			renderAgain(out, sel, options)
		case 'k':
			sel = (sel - 1 + len(options)) % len(options)
			renderAgain(out, sel, options)
		default:
			renderAgain(out, sel, options)
		}
	}
}
EOF
"}

