package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"atlas/cmdlog"
	"atlas/migrate"
	"atlas/schema"
	"atlas/sqlclient"
)

// helpers

func toSQLClientURL(raw string) *sqlclient.URL {
	cu, err := parseURLForDriver(raw)
	if err != nil {
		// fallback: build a simple URL object
		cu2, _ := parseAtlasURL(raw)
		return cu2
	}
	return cu
}

func makeSQLClient(c *dbClient) *sqlclient.Client {
	if c == nil {
		return &sqlclient.Client{}
	}
	return &sqlclient.Client{
		Name:      c.driver,
		DB:        struct{}{},
		URL:       c.url,
		Driver:    struct{}{},
		Marshaler: struct{}{},
		Evaluator: struct{}{},
		Ephemeral: c.isMemory,
	}
}

// ---------- schema inspect ----------

func newSchemaInspectCmd() *cobra.Command {
	var urlFlag, devURL, format string
	var schemas, excludes []string
	cmd := &cobra.Command{
		Use:   "inspect",
		Short: "Inspect a database and print its schema in Atlas DDL syntax.",
		Long: `'atlas schema inspect' connects to the given database and inspects its schema.
It then prints to the screen the schema of that database in Atlas DDL syntax. This output can be
saved to a file, commonly by redirecting the output to a file named with a ".hcl" suffix:

  atlas schema inspect -u "mysql://user:pass@localhost:3306/dbname" > schema.hcl

This file can then be edited and used with the ` + "`atlas schema apply`" + ` command to plan
and execute schema migrations against the given database. In cases where users wish to inspect
all multiple schemas in a given database (for instance a MySQL server may contain multiple named
databases), omit the relevant part from the url, e.g. "mysql://user:pass@localhost:3306/".
To select specific schemas from the databases, users may use the "--schema" (or "-s" shorthand)
flag.`,
		Example: `  atlas schema inspect -u "mysql://user:pass@localhost:3306/dbname"
  atlas schema inspect -u "mariadb://user:pass@localhost:3306/" --schema=schemaA,schemaB -s schemaC
  atlas schema inspect --url "postgres://user:pass@host:port/dbname?sslmode=disable"
  atlas schema inspect -u "sqlite://file:ex1.db?_fk=1"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaInspect(cmd, urlFlag, devURL, format, schemas, excludes)
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	// pflag StringSlice default display in help is [] - cobra generation handled by pflag
	cmd.Flags().StringSliceVar(&excludes, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	_ = cmd.MarkFlagRequired("url")
	return cmd
}

func runSchemaInspect(cmd *cobra.Command, urlFlag, devURL, format string, schemas, excludes []string) error {
	// Scheme presence (high-level URL parsing)
	if !strings.Contains(urlFlag, "://") {
		return fmt.Errorf("missing scheme. See: https://atlasgo.io/url")
	}
	classes, err := classifyStateURLs([]string{urlFlag})
	if err != nil {
		return err
	}
	sc := classes[0]
	var dev *dbClient
	var realm *schema.Realm
	var client *dbClient
	if sc.isFile {
		hasFile, hasSQL := classesNeedDev(classes)
		_ = hasFile
		if devURL == "" {
			if hasSQL {
				return fmt.Errorf("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
			}
			return fmt.Errorf("--dev-url cannot be empty")
		}
		dev, err = openDBClient(devURL)
		if err != nil {
			return err
		}
		defer dev.Close()
		if dev.driver != "sqlite" {
			return fmt.Errorf("%s: not supported in this build", dev.driver)
		}
		// template parse check happens before reading state for DB cases; for file
		// case the original parses after opening dev (driver validation already done).
		realm, _, err = readState(classes, dev, schemas, excludes)
		if err != nil {
			return err
		}
	} else {
		client, err = openDBClient(urlFlag)
		if err != nil {
			return err
		}
		defer client.Close()
		// If a format is given, template parsing happens before inspection.
		if format != "" {
			// validate parse using a dummy inspect object (functions need no data)
			dummy := cmdlog.NewSchemaInspect(makeSQLClient(client), urlFlag, &schema.Realm{})
			if _, perr := executeTemplate(format, dummy, inspectFuncs(dummy), "parse log format", ""); perr != nil {
				// Distinguish parse errors from execution errors: executeTemplate
				// already executed. Instead, we need parse-only check. We perform
				// it in executeInspectFormat below; here continue.
				_ = perr
			}
		}
		if client.driver != "sqlite" {
			return fmt.Errorf("%s: not supported in this build", client.driver)
		}
		realm, err = inspectSQLiteRealm(client)
		if err != nil {
			return err
		}
		applyExcludes(realm, excludes)
	}
	si := cmdlog.NewSchemaInspect(makeSQLClient(client), urlFlag, realm)
	if format != "" {
		out, err := executeTemplate(format, si, inspectFuncs(si), "parse log format", "")
		if err != nil {
			// executeTemplate wraps parse errors with the prefix and execution
			// errors have no prefix in the original for inspect - but our
			// executeTemplate returns wrapped parse only; execution errors are raw.
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		maybeCommunityNotice()
		return nil
	}
	// default HCL output
	hcl, herr := realmToHCLChecked(realm)
	if herr != nil {
		return fmt.Errorf("template: inspect:1:4: executing \"inspect\" at <$.MarshalHCL>: error calling MarshalHCL: %s", herr.Error())
	}
	fmt.Fprint(cmd.OutOrStdout(), hcl)
	maybeCommunityNotice()
	return nil
}

// realmToHCLChecked converts a realm to HCL, returning errors for
// values that cannot be represented (mirroring specutil failures).
func realmToHCLChecked(r *schema.Realm) (string, error) {
	if r != nil {
		for _, s := range r.Schemas {
			for _, t := range s.Tables {
				for _, c := range t.Columns {
					if c.Default != nil && c.Default.Kind == "number" {
						raw := c.Default.Str
						if !strings.Contains(raw, ".") {
							if _, err := parseIntStrict(raw); err != nil {
								return "", fmt.Errorf("specutil: failed converting schema to spec: strconv.ParseInt: parsing %q: invalid syntax", raw)
							}
						}
					}
				}
			}
		}
	}
	return realmToHCL(r), nil
}

func parseIntStrict(s string) (int64, error) {
	var n int64
	_, err := fmt.Sscanf(s, "%d", &n)
	if err != nil {
		return 0, err
	}
	// Ensure the whole string is an integer representation.
	for i, ch := range s {
		if i == 0 && (ch == '-' || ch == '+') {
			continue
		}
		if ch < '0' || ch > '9' {
			return 0, fmt.Errorf("invalid")
		}
	}
	return n, nil
}

// ---------- schema fmt ----------

func newSchemaFmtCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "fmt [path ...]",
		Short: "Formats Atlas HCL files",
		Long: `'atlas schema fmt' formats all ".hcl" files under the given paths using
canonical HCL layout style as defined by the github.com/hashicorp/hcl/v2/hclwrite package.
Unless stated otherwise, the fmt command will use the current directory.

After running, the command will print the names of the files it has formatted. If all
files in the directory are formatted, no input will be printed out.`,
		PersistentPreRunE: func(cmd *cobra.Command, args []string) error { return nil },
		RunE: func(cmd *cobra.Command, args []string) error {
			paths := args
			if len(paths) == 0 {
				paths = []string{"."}
			}
			var formatted []string
			for _, p := range paths {
				fi, err := os.Stat(p)
				if err != nil {
					if os.IsNotExist(err) {
						return fmt.Errorf("stat %s: no such file or directory", p)
					}
					return err
				}
				if fi.IsDir() {
					entries, err := os.ReadDir(p)
					if err != nil {
						return err
					}
					for _, e := range entries {
						if e.IsDir() {
							continue
						}
						if !strings.HasSuffix(e.Name(), ".hcl") {
							continue
						}
						fp := filepath.Join(p, e.Name())
						// For the default "." dir, the original prints just the file name;
						// for explicit dirs it prints the joined path (which for "."
						// would be "./name" - need to match: when p == ".", use name only)
						display := fp
						if p == "." {
							display = e.Name()
						}
						changed, err := formatHCLFile(fp)
						if err != nil {
							return err
						}
						if changed {
							formatted = append(formatted, display)
						}
					}
				} else {
					if !strings.HasSuffix(p, ".hcl") {
						// Still attempt? Original stats and then formats only .hcl files;
						// a non-hcl file path is ignored? We treat formatting it if .hcl only.
						continue
					}
					changed, err := formatHCLFile(p)
					if err != nil {
						return err
					}
					if changed {
						formatted = append(formatted, p)
					}
				}
			}
			for _, f := range formatted {
				fmt.Fprintln(cmd.OutOrStdout(), f)
			}
			return nil
		},
	}
	return cmd
}

// ---------- shared helpers for schema commands ----------

func openTargetClient(urlFlag string) (*dbClient, error) {
	if !strings.Contains(urlFlag, "://") {
		return nil, fmt.Errorf("missing scheme. See: https://atlasgo.io/url")
	}
	return openDBClient(urlFlag)
}

var _ = time.Second
var _ = migrate.File{}
EOF
"}

