// realmToHCLChecked converts a realm to HCL, returning errors for
// values that cannot be represented (mirroring specutil failures).
func realmToHCLChecked(r *schema.Realm) (string, error) {
	if r != nil {
		for _, s := range r.Schemas {
			for _, t := range s.Tables {
				for _, c := range t.Columns {
					if c.Default != nil && c.Default.Kind == "number" {
						raw := c.Default.Str
						if !strings.Contains(raw, ".") {
							if _, err := parseIntStrict(raw); err != nil {
								return "", fmt.Errorf("specutil: failed converting schema to spec: strconv.ParseInt: parsing %q: invalid syntax", raw)
							}
						}
					}
				}
			}
		}
	}
	return realmToHCL(r), nil
}

func parseIntStrict(s string) (int64, error) {
	var n int64
	_, err := fmt.Sscanf(s, "%d", &n)
	if err != nil {
		return 0, err
	}
	// Ensure the whole string is an integer representation.
	for i, ch := range s {
		if i == 0 && (ch == '-' || ch == '+') {
			continue
		}
		if ch < '0' || ch > '9' {
			return 0, fmt.Errorf("invalid")
		}
	}
	return n, nil
}

