			if valid && nonComment == 1 {
				info.isAttr = true
				info.attrKeyLen = len(keyText)
				// position of '=' in joined
				attrEqPos = strings.Index(joined, " =")
				_ = attrEqPos
			}
		}
		infos = append(infos, info)
		depth += netOpen
		if depth < 0 {
			depth = 0
		}
	}
	// attribute alignment for consecutive attr lines at same indent
	for i := 0; i < len(infos); {
		if !infos[i].isAttr {
			i++
			continue
		}
		j := i
		maxKey := 0
		for j < len(infos) && infos[j].isAttr && infos[j].indent == infos[i].indent {
			if infos[j].attrKeyLen > maxKey {
				maxKey = infos[j].attrKeyLen
			}
			j++
		}
		if j-i > 1 {
			for k := i; k < j; k++ {
				// pad before " ="
				txt := infos[k].text
				idx := strings.Index(txt, " = ")
				if idx < 0 {
					continue
				}
				// key portion after indent
				keyLen := infos[k].attrKeyLen
				pad := maxKey - keyLen
				if pad > 0 {
					// insert pad spaces before the space-equals
					infos[k].text = txt[:idx] + strings.Repeat(" ", pad) + txt[idx:]
				}
			}
		}
		i = j
	}
	var out []string
	for _, info := range infos {
		out = append(out, info.text)
	}
	res := strings.Join(out, "\n")
	if hadFinalNL {
		res += "\n"
	}
	return res
}

func formatHCLFile(path string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := formatHCL(string(data))
	if formatted == string(data) {
		return false, nil
	}
	if err := os.WriteFile(path, []byte(formatted), 0o644); err != nil {
		return false, err
	}
	return true, nil
}
EOF

