{"command":"cat > hcl_format.go <<'EOF'
package main

import (
	"os"
	"strings"
)

// Token for formatting purposes.
type fmtTok struct {
	text string
	kind string // ident, string, number, symbol, comment
}

func isSymChar(c byte) bool {
	return strings.ContainsRune("{}[]()=.,:?!<>+-*/%&|", rune(c))
}

func tokenizeLineForFmt(line string, inBlockComment *bool) []fmtTok {
	var toks []fmtTok
	i := 0
	for i < len(line) {
		if *inBlockComment {
			j := strings.Index(line[i:], "*/")
			if j < 0 {
				toks = append(toks, fmtTok{text: line[i:], kind: "comment"})
				return toks
			}
			end := i + j + 2
			toks = append(toks, fmtTok{text: line[i:end], kind: "comment"})
			i = end
			*inBlockComment = false
			continue
		}
		c := line[i]
		if c == ' ' || c == '\t' || c == '\r' {
			i++
			continue
		}
		if c == '#' || (c == '/' && i+1 < len(line) && line[i+1] == '/') {
			toks = append(toks, fmtTok{text: line[i:], kind: "comment"})
			break
		}
		if c == '/' && i+1 < len(line) && line[i+1] == '*' {
			j := strings.Index(line[i+2:], "*/")
			if j < 0 {
				toks = append(toks, fmtTok{text: line[i:], kind: "comment"})
				*inBlockComment = true
				break
			}
			end := i + 2 + j + 2
			toks = append(toks, fmtTok{text: line[i:end], kind: "comment"})
			i = end
			continue
		}
		if c == '"' {
			j := i + 1
			for j < len(line) {
				if line[j] == '\\' {
					j += 2
					continue
				}
				if line[j] == '"' {
					j++
					break
				}
				j++
			}
			if j > len(line) {
				j = len(line)
			}
			toks = append(toks, fmtTok{text: line[i:j], kind: "string"})
			i = j
			continue
		}
		if isIdentStart(c) {
			j := i
			for j < len(line) && isIdentChar(line[j]) {
				j++
			}
			toks = append(toks, fmtTok{text: line[i:j], kind: "ident"})
			i = j
			continue
		}
		if isDigit(c) {
			j := i
			for j < len(line) && (isDigit(line[j]) || line[j] == '.' || line[j] == 'e' || line[j] == 'E') {
				// stop before member dot
				if line[j] == '.' && (j+1 >= len(line) || !isDigit(line[j+1])) {
					break
				}
				j++
			}
			toks = append(toks, fmtTok{text: line[i:j], kind: "number"})
			i = j
			continue
		}
		// operators / symbols, combine
		if i+2 < len(line) && line[i:i+3] == "..." {
			toks = append(toks, fmtTok{text: "...", kind: "symbol"})
			i += 3
			continue
		}
		if i+1 < len(line) {
			two := line[i : i+2]
			if two == "==" || two == "!=" || two == "<=" || two == ">=" || two == "&&" || two == "||" || two == "=>" || two == "<<" {
				toks = append(toks, fmtTok{text: two, kind: "symbol"})
				i += 2
				continue
			}
			// heredoc marker handling: << or <<- followed by ident is kept as a token in caller
		}
		toks = append(toks, fmtTok{text: string(c), kind: "symbol"})
		i++
	}
	return toks
}

func isBinaryOp(t string) bool {
	switch t {
	case "=", "==", "!=", "<", "<=", ">", ">=", "&&", "||", "+", "-", "*", "/", "%", "?", ":", "=>":
		return true
	}
	return false
}

// joinFmtTokens reconstructs a line's code with canonical spacing.
func joinFmtTokens(toks []fmtTok) string {
	var sb strings.Builder
	for i, tok := range toks {
		if i == 0 {
			sb.WriteString(tok.text)
			continue
		}
		prev := toks[i-1]
		needSpace := false
		switch {
		case tok.text == "," || tok.text == ")" || tok.text == "]" || tok.text == "." || tok.text == "...":
			needSpace = false
		case prev.text == "(" || prev.text == "[" || prev.text == "." || prev.text == "...":
			needSpace = false
		case tok.text == "(" && (prev.kind == "ident"):
			needSpace = false // function call
		case tok.text == "[" && (prev.kind == "ident" || prev.text == "]" || prev.text == ")"):
			needSpace = false // index
		case tok.kind == "comment":
			needSpace = true
		case prev.kind == "comment":
			needSpace = true
		case isBinaryOp(tok.text) || isBinaryOp(prev.text):
			// unary minus/plus/not handled below
			if tok.text == "-" || tok.text == "+" {
				// binary if previous is a value
				if prev.kind == "ident" || prev.kind == "number" || prev.kind == "string" || prev.text == ")" || prev.text == "]" {
					needSpace = true
				} else {
					needSpace = false
				}
			} else if prev.text == "-" || prev.text == "+" || prev.text == "!" {
				// after unary: no space if unary context, but our prev op
				// spacing would have set; detect: if the token before prev
				// is a value, prev was binary and needs space
				if i >= 2 && (toks[i-2].kind == "ident" || toks[i-2].kind == "number" || toks[i-2].kind == "string" || toks[i-2].text == ")" || toks[i-2].text == "]") {
					needSpace = true
				} else {
					needSpace = false
				}
				if tok.text == "!" {
					needSpace = false
				}
			} else {
				needSpace = true
			}
		case tok.text == "{":
			needSpace = true
		case prev.text == "{":
			needSpace = tok.text != "}"
		case tok.text == "}":
			needSpace = prev.text != "{"
		case tok.text == "(":
			needSpace = false
		case prev.text == ",":
			needSpace = true
		default:
			needSpace = true
		}
		// special: '!' unary no space after handled by next iteration logic; if tok is '!'
		if tok.text == "!" {
			if prev.kind == "ident" || prev.kind == "number" {
				needSpace = true
			} else {
				// unary context: space may be due to '=' before
				needSpace = isBinaryOp(prev.text)
			}
		}
		if needSpace {
			sb.WriteString(" ")
		}
		sb.WriteString(tok.text)
	}
	return sb.String()
}

// formatHCL formats HCL content (hclwrite.Format-like, line based).
func formatHCL(content string) string {
	if content == "" {
		return content
	}
	hadFinalNL := strings.HasSuffix(content, "\n")
	body := strings.TrimSuffix(content, "\n")
	lines := strings.Split(body, "\n")
	type lineInfo struct {
		text       string
		isBlank    bool
		isAttr     bool
		attrEqIdx  int // byte index of '=' in formatted text (within content, without indent)
		attrKeyLen int
		indent     int
	}
	var infos []lineInfo
	depth := 0
	inBlockComment := false
	inHeredoc := ""
	for _, rawLine := range lines {
		if inHeredoc != "" {
			infos = append(infos, lineInfo{text: rawLine})
			if strings.TrimSpace(rawLine) == inHeredoc {
				inHeredoc = ""
			}
			continue
		}
		trimmed := strings.TrimSpace(rawLine)
		if trimmed == "" {
			infos = append(infos, lineInfo{text: "", isBlank: true})
			continue
		}
		toks := tokenizeLineForFmt(rawLine, &inBlockComment)
		if len(toks) == 0 {
			infos = append(infos, lineInfo{text: "", isBlank: true})
			continue
		}
		// leading closers reduce indent
		leadingClosers := 0
		for _, t := range toks {
			if t.text == "}" || t.text == "]" || t.text == ")" {
				leadingClosers++
			} else {
				break
			}
		}
		effDepth := depth - leadingClosers
		if effDepth < 0 {
			effDepth = 0
		}
		joined := joinFmtTokens(toks)
		// detect heredoc start
		if idx := strings.Index(joined, "<<"); idx >= 0 {
			rest := strings.TrimSpace(joined[idx+2:])
			rest = strings.TrimPrefix(rest, "-")
			// marker up to space
			marker := strings.Fields(rest)
			if len(marker) > 0 {
				inHeredoc = marker[0]
			}
		}
		// update depth by net opens in this line (excluding heredoc contents)
		netOpen := 0
		for _, t := range toks {
			if t.kind == "comment" {
				continue
			}
			switch t.text {
			case "{", "[", "(":
				netOpen++
			case "}", "]", ")":
				netOpen--
			}
		}
		info := lineInfo{text: strings.Repeat("  ", effDepth) + joined, indent: effDepth}
		// attr detection: find top-level = token (= only, not ==/=>) at bracket depth 0
		d := 0
		isAttr := false
		var attrEqPos int
		var keyText string
		// reconstruct position: we search tokens; key text is tokens before '=' joined
		var preToks []fmtTok
		for _, t := range toks {
			if t.kind == "comment" && len(preToks) == 0 {
				preToks = append(preToks, t)
				continue
			}
			if d == 0 && t.text == "=" {
				isAttr = true
				keyText = joinFmtTokens(preToks)
				break
			}
			switch t.text {
			case "{", "[", "(":
				d++
			case "}", "]", ")":
				d--
			}
			preToks = append(preToks, t)
		}
		if isAttr {
			// key must be plausible: single ident or comment prefix+ident
			valid := false
			nonComment := 0
			for _, t := range preToks {
				if t.kind != "comment" {
					nonComment++
					if t.kind == "ident" {
						valid = true
					}
				}
			}
			if valid && nonComment == 1 {
				info.isAttr = true
				info.attrKeyLen = len(keyText)
				// position of '=' in joined
				attrEqPos = strings.Index(joined, " =")
				_ = attrEqPos
			}
		}
		infos = append(infos, info)
		depth += netOpen
		if depth < 0 {
			depth = 0
		}
	}
	// attribute alignment for consecutive attr lines at same indent
	for i := 0; i < len(infos); {
		if !infos[i].isAttr {
			i++
			continue
		}
		j := i
		maxKey := 0
		for j < len(infos) && infos[j].isAttr && infos[j].indent == infos[i].indent {
			if infos[j].attrKeyLen > maxKey {
				maxKey = infos[j].attrKeyLen
			}
			j++
		}
		if j-i > 1 {
			for k := i; k < j; k++ {
				// pad before " ="
				txt := infos[k].text
				idx := strings.Index(txt, " = ")
				if idx < 0 {
					continue
				}
				// key portion after indent
				keyLen := infos[k].attrKeyLen
				pad := maxKey - keyLen
				if pad > 0 {
					// insert pad spaces before the space-equals
					infos[k].text = txt[:idx] + strings.Repeat(" ", pad) + txt[idx:]
				}
			}
		}
		i = j
	}
	var out []string
	for _, info := range infos {
		out = append(out, info.text)
	}
	res := strings.Join(out, "\n")
	if hadFinalNL {
		res += "\n"
	}
	return res
}

func formatHCLFile(path string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := formatHCL(string(data))
	if formatted == string(data) {
		return false, nil
	}
	if err := os.WriteFile(path, []byte(formatted), 0o644); err != nil {
		return false, err
	}
	return true, nil
}
EOF
"}

{"command":"cat > commands_schema2.go <<'EOF'
package main

import (
	"fmt"
	"strings"
	"text/template"
	"time"

	"github.com/spf13/cobra"

	"atlas/cmdlog"
	"atlas/schema"
)

// ---------- schema apply ----------

func newSchemaApplyCmd() *cobra.Command {
	var urlFlag, devURL, format, txMode, plan string
	var to, exclude, include, schemas []string
	var dryRun, autoApprove, edit bool
	var lockTimeout time.Duration
	var fileFlag string
	cmd := &cobra.Command{
		Use:   "apply",
		Short: "Apply an atlas schema to a target database.",
		Long: `'atlas schema apply' plans and executes a database migration to bring a given
database to the state described in the provided Atlas schema. Before running the
migration, Atlas will print the migration plan and prompt the user for approval.

The schema is provided by one or more URLs (to a HCL file or 
directory, database or migration directory) using the "--to, -t" flag:
  atlas schema apply -u URL --to "file://file1.hcl" --to "file://file2.hcl"
  atlas schema apply -u URL --to "file://schema/" --to "file://override.hcl"

As a convenience, schema URLs may also be provided via an environment definition in
the project file (see: https://atlasgo.io/cli/projects).

If run with the "--dry-run" flag, atlas will exit after printing out the planned
migration.`,
		Example: `  atlas schema apply -u "mysql://user:pass@localhost/dbname" --to "file://atlas.hcl"
  atlas schema apply -u "mysql://localhost" --to "file://schema.sql" --dev-url "docker://mysql/8/dev"
  atlas schema apply --env local --dev-url "docker://postgres/15/dev?search_path=public" --dry-run
  atlas schema apply -u "sqlite://file.db" --to "file://schema.sql" --dev-url "sqlite://dev?mode=memory"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaApply(cmd, applyArgs{
				url: urlFlag, devURL: devURL, format: format, txMode: txMode, plan: plan,
				to: to, exclude: exclude, include: include, schemas: schemas,
				dryRun: dryRun, autoApprove: autoApprove, edit: edit, file: fileFlag,
			})
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringSliceVar(&to, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringSliceVar(&exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringSliceVar(&include, "include", nil, "list of glob patterns used to select which resources to keep in inspection")
	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().BoolVar(&autoApprove, "auto-approve", false, "apply changes without prompting for approval")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&txMode, "tx-mode", "file", "set transaction mode [none, file]")
	cmd.Flags().StringVar(&plan, "plan", "", "URL to a pre-planned migration (e.g., atlas://repo/plans/name)")
	cmd.Flags().BoolVar(&edit, "edit", false, "open the generated SQL in an editor")
	cmd.Flags().DurationVar(&lockTimeout, "lock-timeout", 10*time.Second, "set how long to wait for the database lock")
	cmd.Flags().StringVar(&fileFlag, "file", "", "")
	_ = cmd.Flags().MarkHidden("file")
	cmd.MarkFlagsMutuallyExclusive("edit", "plan")
	cmd.MarkFlagsMutuallyExclusive("file", "to")
	_ = lockTimeout
	return cmd
}

type applyArgs struct {
	url, devURL, format, txMode, plan, file string
	to, exclude, include, schemas           []string
	dryRun, autoApprove, edit               bool
}

func runSchemaApply(cmd *cobra.Command, a applyArgs) error {
	// Community restrictions (order: plan, edit, include)
	if a.plan != "" {
		return communityAbort("schema apply", "--plan")
	}
	if a.edit {
		return communityAbort("schema apply", "--edit")
	}
	if len(a.include) > 0 {
		return communityAbort("schema apply", "--include")
	}
	if a.url == "" {
		return fmt.Errorf("required flag(s) \"url\" not set")
	}
	desiredURLs := a.to
	if a.file != "" {
		f := a.file
		if !strings.Contains(f, "://") {
			f = "file://" + f
		}
		desiredURLs = []string{f}
	}
	if len(desiredURLs) == 0 {
		return fmt.Errorf("one of flag(s) \"file\" or \"to\" is required")
	}
	if a.txMode != "none" && a.txMode != "file" {
		return fmt.Errorf("unknown tx-mode %q", a.txMode)
	}
	if a.format != "" && !a.dryRun && !a.autoApprove {
		return fmt.Errorf("--log and --format can only be used with --dry-run or --auto-approve")
	}
	// Target URL: file targets are treated as needing a dev database.
	if schemeOf(a.url) == "file" {
		return fmt.Errorf("--dev-url cannot be empty")
	}
	target, err := openTargetClient(a.url)
	if err != nil {
		return err
	}
	defer target.Close()
	if target.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", target.driver)
	}
	// Desired state classification (apply-specific missing scheme handling)
	classes, err := classifyApplyDesired(desiredURLs)
	if err != nil {
		return err
	}
	// Template parse (before reading desired) if format set
	var tmpl *template.Template
	if a.format != "" {
		dummy := cmdlog.NewSchemaApply(cmdlog.Env{Driver: target.driver, URL: target.url}, nil)
		t, perr := parseTemplateOnly(a.format, jsonOnlyFuncs(), "parse log format")
		if perr != nil {
			return perr
		}
		_ = dummy
		tmpl = t
	}
	// Dev handling
	dev, err := resolveDevForState(classes, a.devURL, target)
	if err != nil {
		return err
	}
	if dev != nil {
		defer dev.Close()
	}
	desired, _, err := readState(classes, dev, a.schemas, a.exclude)
	if err != nil {
		return err
	}
	current, err := inspectSQLiteRealm(target)
	if err != nil {
		return err
	}
	applyExcludes(current, a.exclude)
	changes := realmDiff(current, desired)
	sqlChanges, err := planChanges(current, desired, changes, "  ")
	if err != nil {
		return err
	}
	// Format mode
	if a.format != "" {
		log := cmdlog.NewSchemaApply(cmdlog.Env{Driver: target.driver, URL: target.url}, &cmdlog.Changes{})
		if a.dryRun {
			if len(sqlChanges) > 0 {
				log.Changes.Pending = sqlChanges
			}
			out, err := executeParsedTemplate(tmpl, log, "")
			if err != nil {
				return err
			}
			fmt.Fprint(cmd.OutOrStdout(), out)
			maybeCommunityNotice()
			return nil
		}
		// auto-approve: execute first
		if len(sqlChanges) > 0 {
			if err := executeChanges(target, sqlChanges, a.txMode); err != nil {
				return err
			}
			log.Changes.Applied = sqlChanges
		}
		out, err := executeParsedTemplate(tmpl, log, "")
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		maybeCommunityNotice()
		return nil
	}
	if len(sqlChanges) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schema is synced, no changes to be made")
		maybeCommunityNotice()
		return nil
	}
	// Print plan
	fmt.Fprintln(cmd.OutOrStdout(), "-- Planned Changes:")
	fmt.Fprint(cmd.OutOrStdout(), changesToSQLText(sqlChanges, ""))
	if a.dryRun {
		maybeCommunityNotice()
		return nil
	}
	if !a.autoApprove {
		sel, perr := promptSelect(cmd.InOrStdin(), cmd.OutOrStdout())
		if perr != nil {
			if perr == errInterrupt {
				return nil
			}
			return perr
		}
		if sel == 1 {
			// Abort
			return nil
		}
	}
	if err := executeChanges(target, sqlChanges, a.txMode); err != nil {
		return err
	}
	maybeCommunityNotice()
	return nil
}

// classifyApplyDesired classifies desired URLs for schema apply: scheme-less
// values yield the sqlclient missing-scheme error instead of a file suggestion.
func classifyApplyDesired(urls []string) ([]*stateClass, error) {
	// Mixed scheme check (syntactic)
	var schemes []string
	seen := map[string]bool{}
	for _, u := range urls {
		if u == "" {
			continue
		}
		s := schemeOf(u)
		if !seen[s] {
			seen[s] = true
			schemes = append(schemes, s)
		}
	}
	if len(schemes) > 1 {
		var quoted []string
		for _, s := range schemes {
			quoted = append(quoted, fmt.Sprintf("%q", s))
		}
		joined := strings.Join(quoted, ", ")
		if len(quoted) == 2 {
			joined = quoted[0] + " and " + quoted[1]
		}
		return nil, fmt.Errorf("got mixed --to url schemes: %s, the desired state must be provided from a single kind of source", joined)
	}
	var classes []*stateClass
	for _, u := range urls {
		if u == "" {
			continue
		}
		if !strings.Contains(u, "://") {
