// ---------- schema apply ----------

func newSchemaApplyCmd() *cobra.Command {
	var urlFlag, devURL, format, txMode, plan string
	var to, exclude, include, schemas []string
	var dryRun, autoApprove, edit bool
	var lockTimeout time.Duration
	var fileFlag string
	cmd := &cobra.Command{
		Use:   "apply",
		Short: "Apply an atlas schema to a target database.",
		Long: `'atlas schema apply' plans and executes a database migration to bring a given
database to the state described in the provided Atlas schema. Before running the
migration, Atlas will print the migration plan and prompt the user for approval.

The schema is provided by one or more URLs (to a HCL file or 
directory, database or migration directory) using the "--to, -t" flag:
  atlas schema apply -u URL --to "file://file1.hcl" --to "file://file2.hcl"
  atlas schema apply -u URL --to "file://schema/" --to "file://override.hcl"

As a convenience, schema URLs may also be provided via an environment definition in
the project file (see: https://atlasgo.io/cli/projects).

If run with the "--dry-run" flag, atlas will exit after printing out the planned
migration.`,
		Example: `  atlas schema apply -u "mysql://user:pass@localhost/dbname" --to "file://atlas.hcl"
  atlas schema apply -u "mysql://localhost" --to "file://schema.sql" --dev-url "docker://mysql/8/dev"
  atlas schema apply --env local --dev-url "docker://postgres/15/dev?search_path=public" --dry-run
  atlas schema apply -u "sqlite://file.db" --to "file://schema.sql" --dev-url "sqlite://dev?mode=memory"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaApply(cmd, applyArgs{
				url: urlFlag, devURL: devURL, format: format, txMode: txMode, plan: plan,
				to: to, exclude: exclude, include: include, schemas: schemas,
				dryRun: dryRun, autoApprove: autoApprove, edit: edit, file: fileFlag,
			})
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringSliceVar(&to, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringSliceVar(&exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringSliceVar(&include, "include", nil, "list of glob patterns used to select which resources to keep in inspection")
	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().BoolVar(&autoApprove, "auto-approve", false, "apply changes without prompting for approval")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&txMode, "tx-mode", "file", "set transaction mode [none, file]")
	cmd.Flags().StringVar(&plan, "plan", "", "URL to a pre-planned migration (e.g., atlas://repo/plans/name)")
	cmd.Flags().BoolVar(&edit, "edit", false, "open the generated SQL in an editor")
	cmd.Flags().DurationVar(&lockTimeout, "lock-timeout", 10*time.Second, "set how long to wait for the database lock")
	cmd.Flags().StringVar(&fileFlag, "file", "", "")
	_ = cmd.Flags().MarkHidden("file")
	cmd.MarkFlagsMutuallyExclusive("edit", "plan")
	cmd.MarkFlagsMutuallyExclusive("file", "to")
	_ = lockTimeout
	return cmd
}

type applyArgs struct {
	url, devURL, format, txMode, plan, file string
	to, exclude, include, schemas           []string
	dryRun, autoApprove, edit               bool
}

func runSchemaApply(cmd *cobra.Command, a applyArgs) error {
	// Community restrictions (order: plan, edit, include)
	if a.plan != "" {
		return communityAbort("schema apply", "--plan")
	}
	if a.edit {
		return communityAbort("schema apply", "--edit")
	}
	if len(a.include) > 0 {
		return communityAbort("schema apply", "--include")
	}
	if a.url == "" {
		return fmt.Errorf("required flag(s) \"url\" not set")
	}
	desiredURLs := a.to
	if a.file != "" {
		f := a.file
		if !strings.Contains(f, "://") {
			f = "file://" + f
		}
		desiredURLs = []string{f}
	}
	if len(desiredURLs) == 0 {
		return fmt.Errorf("one of flag(s) \"file\" or \"to\" is required")
	}
	if a.txMode != "none" && a.txMode != "file" {
		return fmt.Errorf("unknown tx-mode %q", a.txMode)
	}
	if a.format != "" && !a.dryRun && !a.autoApprove {
		return fmt.Errorf("--log and --format can only be used with --dry-run or --auto-approve")
	}
	// Target URL: file targets are treated as needing a dev database.
	if schemeOf(a.url) == "file" {
		return fmt.Errorf("--dev-url cannot be empty")
	}
	target, err := openTargetClient(a.url)
	if err != nil {
		return err
	}
	defer target.Close()
	if target.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", target.driver)
	}
	// Desired state classification (apply-specific missing scheme handling)
	classes, err := classifyApplyDesired(desiredURLs)
	if err != nil {
		return err
	}
	// Template parse (before reading desired) if format set
	var tmpl *template.Template
	if a.format != "" {
		dummy := cmdlog.NewSchemaApply(cmdlog.Env{Driver: target.driver, URL: target.url}, nil)
		t, perr := parseTemplateOnly(a.format, jsonOnlyFuncs(), "parse log format")
		if perr != nil {
			return perr
		}
		_ = dummy
		tmpl = t
	}
	// Dev handling
	dev, err := resolveDevForState(classes, a.devURL, target)
	if err != nil {
		return err
	}
	if dev != nil {
		defer dev.Close()
	}
	desired, _, err := readState(classes, dev, a.schemas, a.exclude)
	if err != nil {
		return err
	}
	current, err := inspectSQLiteRealm(target)
	if err != nil {
		return err
	}
	applyExcludes(current, a.exclude)
	changes := realmDiff(current, desired)
	sqlChanges, err := planChanges(current, desired, changes, "  ")
	if err != nil {
		return err
	}
	// Format mode
	if a.format != "" {
		log := cmdlog.NewSchemaApply(cmdlog.Env{Driver: target.driver, URL: target.url}, &cmdlog.Changes{})
		if a.dryRun {
			if len(sqlChanges) > 0 {
				log.Changes.Pending = sqlChanges
			}
			out, err := executeParsedTemplate(tmpl, log, "")
			if err != nil {
				return err
			}
			fmt.Fprint(cmd.OutOrStdout(), out)
			maybeCommunityNotice()
			return nil
		}
		// auto-approve: execute first
		if len(sqlChanges) > 0 {
			if err := executeChanges(target, sqlChanges, a.txMode); err != nil {
				return err
			}
			log.Changes.Applied = sqlChanges
		}
		out, err := executeParsedTemplate(tmpl, log, "")
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		maybeCommunityNotice()
		return nil
	}
	if len(sqlChanges) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schema is synced, no changes to be made")
		maybeCommunityNotice()
		return nil
	}
	// Print plan
	fmt.Fprintln(cmd.OutOrStdout(), "-- Planned Changes:")
	fmt.Fprint(cmd.OutOrStdout(), changesToSQLText(sqlChanges, ""))
	if a.dryRun {
		maybeCommunityNotice()
		return nil
	}
	if !a.autoApprove {
		sel, perr := promptSelect(cmd.InOrStdin(), cmd.OutOrStdout())
		if perr != nil {
			if perr == errInterrupt {
				return nil
			}
			return perr
		}
		if sel == 1 {
			// Abort
			return nil
		}
	}
	if err := executeChanges(target, sqlChanges, a.txMode); err != nil {
		return err
	}
	maybeCommunityNotice()
	return nil
}

// classifyApplyDesired classifies desired URLs for schema apply: scheme-less
// values yield the sqlclient missing-scheme error instead of a file suggestion.
func classifyApplyDesired(urls []string) ([]*stateClass, error) {
	// Mixed scheme check (syntactic)
	var schemes []string
	seen := map[string]bool{}
	for _, u := range urls {
		if u == "" {
			continue
		}
		s := schemeOf(u)
		if !seen[s] {
			seen[s] = true
			schemes = append(schemes, s)
		}
	}
	if len(schemes) > 1 {
		var quoted []string
		for _, s := range schemes {
			quoted = append(quoted, fmt.Sprintf("%q", s))
		}
		joined := strings.Join(quoted, ", ")
		if len(quoted) == 2 {
			joined = quoted[0] + " and " + quoted[1]
		}
		return nil, fmt.Errorf("got mixed --to url schemes: %s, the desired state must be provided from a single kind of source", joined)
	}
	var classes []*stateClass
	for _, u := range urls {
		if u == "" {
			continue
		}
		if !strings.Contains(u, "://") {
			return nil, fmt.Errorf("missing scheme. See: https://atlasgo.io/url")
		}
		sc, err := classifyStateURL(u)
		if err != nil {
			return nil, err
		}
		classes = append(classes, sc)
	}
	if len(classes) == 0 {
		return nil, fmt.Errorf("at least one url is required")
	}
	return classes, nil
}

// resolveDevForState decides the dev client based on state kinds.
func resolveDevForState(classes []*stateClass, devURL string, target *dbClient) (*dbClient, error) {
	hasFile, hasSQL := classesNeedDev(classes)
	if devURL != "" {
		dev, err := openDBClient(devURL)
		if err != nil {
			return nil, err
		}
		if dev.driver != "sqlite" {
			dev.Close()
			return nil, fmt.Errorf("%s: not supported in this build", dev.driver)
		}
		return dev, nil
	}
	if !hasFile {
		return nil, nil
	}
	if hasSQL {
		return nil, fmt.Errorf("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
	}
	// HCL only: auto in-memory dev for sqlite targets
	if target != nil && target.driver == "sqlite" {
		dev, err := openDBClient("sqlite://dev?mode=memory")
		if err != nil {
			return nil, err
		}
		return dev, nil
	}
	return nil, fmt.Errorf("--dev-url cannot be empty")
}

func executeChanges(c *dbClient, changes []*migrateChangeAlias, txMode string) error {
	return executeSQLChanges(c, changes, txMode)
}

// ---------- schema diff ----------

func newSchemaDiffCmd() *cobra.Command {
	var from, to, schemas, exclude, include []string
	var devURL, format string
	cmd := &cobra.Command{
		Use:   "diff",
		Short: "Calculate and print the diff between two schemas.",
		Long: `'atlas schema diff' reads the state of two given schema definitions, 
calculates the difference in their schemas, and prints a plan of
SQL statements to migrate the "from" database to the schema of the "to" database.
The database states can be read from a connected database, an HCL project or a migration directory.`,
		Example: `  atlas schema diff --from "mysql://user:pass@localhost:3306/test" --to "file://schema.hcl"
  atlas schema diff --from "mysql://user:pass@localhost:3306" --to "file://schema_1.hcl" --to "file://schema_2.hcl"
  atlas schema diff --from "mysql://user:pass@localhost:3306" --to "file://migrations" --format '{{ sql . "  " }}'`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runSchemaDiff(cmd, from, to, devURL, format, schemas, exclude, include)
		},
	}
	cmd.Flags().StringSliceVarP(&from, "from", "f", nil, "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
	cmd.Flags().StringSliceVar(&to, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringSliceVar(&exclude, "exclude", nil, "list of glob patterns used to filter resources from applying")
	cmd.Flags().StringSliceVar(&include, "include", nil, "list of glob patterns used to select which resources to keep in inspection")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	_ = cmd.MarkFlagRequired("from")
	_ = cmd.MarkFlagRequired("to")
	return cmd
}

func runSchemaDiff(cmd *cobra.Command, from, to []string, devURL, format string, schemas, exclude, include []string) error {
	if len(include) > 0 {
		return communityAbort("schema diff", "--include")
	}
	fromClasses, err := classifyStateURLs(from)
	if err != nil {
		return err
	}
	toClasses, err := classifyStateURLs(to)
	if err != nil {
		return err
	}
	all := append(append([]*stateClass{}, fromClasses...), toClasses...)
	hasFile, hasSQL := classesNeedDev(all)
	var dev *dbClient
	if hasFile {
		if devURL == "" {
			if hasSQL {
				return fmt.Errorf("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
			}
			return fmt.Errorf("--dev-url cannot be empty")
		}
		dev, err = openDBClient(devURL)
		if err != nil {
			return err
		}
		defer dev.Close()
		if dev.driver != "sqlite" {
			return fmt.Errorf("%s: not supported in this build", dev.driver)
		}
	}
	// template parse check before reading states (after dev driver validation)
	var tmpl *template.Template
	if format != "" {
		dummy := cmdlog.NewSchemaDiff(nil, &schema.Realm{}, &schema.Realm{}, nil)
		t, perr := parseTemplateOnly(format, diffFuncs(dummy), "parse log format")
		if perr != nil {
			return perr
		}
		tmpl = t
	}
	fromRealm, _, err := readState(fromClasses, dev, schemas, exclude)
	if err != nil {
		return err
	}
	toRealm, _, err := readState(toClasses, dev, schemas, exclude)
	if err != nil {
		return err
	}
	changes := realmDiff(fromRealm, toRealm)
	sd := cmdlog.NewSchemaDiff(nil, fromRealm, toRealm, changes)
	if format != "" {
		out, err := executeParsedTemplate(tmpl, sd, "")
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		maybeCommunityNotice()
		return nil
	}
	sqlChanges, err := planChanges(fromRealm, toRealm, changes, "")
	if err != nil {
		return err
	}
	if len(sqlChanges) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "Schemas are synced, no changes to be made.")
		maybeCommunityNotice()
		return nil
	}
	fmt.Fprint(cmd.OutOrStdout(), changesToSQLText(sqlChanges, ""))
	maybeCommunityNotice()
	return nil
}

// ---------- schema clean ----------

func newSchemaCleanCmd() *cobra.Command {
	var urlFlag, format string
	var dryRun, autoApprove bool
	cmd := &cobra.Command{
		Use:   "clean",
		Short: "Removes all objects from the connected database.",
		Long: `'atlas schema clean' drops all objects in the connected database and leaves it in an empty state.
As a safety feature, 'atlas schema clean' will ask for confirmation before attempting to execute any SQL.`,
