package migrate

import (
	"encoding/json"
	"strings"
	"time"
)

// LocalFile is a migration file in a local migration directory.
type LocalFile struct {
	n string
	b []byte
}

// File is an alias kept for convenience; the concrete type name is LocalFile.
type File = LocalFile

func NewLocalFile(name string, content []byte) *LocalFile {
	return &LocalFile{n: name, b: content}
}
func NewFile(name, content string) *LocalFile {
	return &LocalFile{n: name, b: []byte(content)}
}

func (f *LocalFile) Name() string {
	return f.n
}

func (f *LocalFile) Text() string { return string(f.b) }
func (f *LocalFile) Bytes() []byte { return f.b }

func (f *LocalFile) Version() string {
	n := f.n
	// Flyway style: V<version>__<desc>.sql
	if strings.HasPrefix(n, "V") && strings.HasSuffix(n, ".sql") {
		rest := n[1 : len(n)-4]
		if i := strings.Index(rest, "__"); i >= 0 {
			return rest[:i]
		}
		return rest
	}
	base := strings.TrimSuffix(n, ".sql")
	if i := strings.Index(base, "_"); i >= 0 {
		return base[:i]
	}
	return base
}

func (f *LocalFile) Description() string {
	n := f.n
	if strings.HasPrefix(n, "V") && strings.HasSuffix(n, ".sql") {
		rest := n[1 : len(n)-4]
		if i := strings.Index(rest, "__"); i >= 0 {
			return rest[i+2:]
		}
		return ""
	}
	base := strings.TrimSuffix(n, ".sql")
	if i := strings.Index(base, "_"); i >= 0 {
		return base[i+1:]
	}
	return ""
}

func (f *LocalFile) MarshalJSON() ([]byte, error) {
	type fileJSON struct {
		Name        string `json:"Name"`
		Version     string `json:"Version"`
		Description string `json:"Description,omitempty"`
	}
	return json.Marshal(fileJSON{Name: f.n, Version: f.Version(), Description: f.Description()})
}

// RevisionType describes how a revision was created.
type RevisionType int

const (
	RevisionTypeBaseline RevisionType = 1
	RevisionTypeApplied  RevisionType = 2
	RevisionTypeSet      RevisionType = 4
)

func (t RevisionType) String() string {
	switch t {
	case RevisionTypeBaseline:
		return "baseline"
	case RevisionTypeApplied:
		return "applied"
	case RevisionTypeSet:
		return "manually set"
	default:
		return ""
	}
}

func (t RevisionType) MarshalJSON() ([]byte, error) {
	return json.Marshal(t.String())
}

// Revision is a row of the atlas_schema_revisions table.
type Revision struct {
	Version         string
	Description     string
	Type            RevisionType
	Applied         int
	Total           int
	ExecutedAt      time.Time
	ExecutionTime   time.Duration
	Error           string `json:"-"`
	ErrorStmt       string `json:"-"`
	Hash            string `json:"-"`
	PartialHashes   []string `json:"-"`
	OperatorVersion string
}

func (r *Revision) MarshalJSON() ([]byte, error) {
	type revisionJSON struct {
		Version         string        `json:"Version"`
		Description     string        `json:"Description,omitempty"`
		Type            RevisionType  `json:"Type"`
		Applied         int           `json:"Applied"`
		Total           int           `json:"Total"`
		ExecutedAt      time.Time     `json:"ExecutedAt"`
		ExecutionTime   time.Duration `json:"ExecutionTime"`
		OperatorVersion string        `json:"OperatorVersion"`
	}
	return json.Marshal(revisionJSON{
		Version: r.Version, Description: r.Description, Type: r.Type, Applied: r.Applied, Total: r.Total,
		ExecutedAt: r.ExecutedAt, ExecutionTime: r.ExecutionTime, OperatorVersion: r.OperatorVersion,
	})
}
EOF
"}

