// ---------- Migrate status / apply reports ----------

func (s *MigrateStatus) MarshalJSON() ([]byte, error) {
	type statusJSON struct {
		Env       Env                `json:"Env"`
		Available []*migrate.File    `json:"Available,omitempty"`
		Pending   []*migrate.File    `json:"Pending,omitempty"`
		Applied   []*migrate.Revision `json:"Applied,omitempty"`
		Current   string             `json:"Current"`
		Next      string             `json:"Next"`
		Status    string             `json:"Status"`
	}
	return json.Marshal(statusJSON{
		Env: s.Env, Available: s.Available, Pending: s.Pending, Applied: s.AppliedRevisions,
		Current: s.Current, Next: s.Next, Status: s.Status,
	})
}

// File wraps a migrate.LocalFile for report purposes.
type File struct {
	File *migrate.File
}

func (f File) Name() string        { return f.File.Name() }
func (f File) Version() string     { return f.File.Version() }
func (f File) Description() string { return f.File.Description() }
func (f File) MarshalJSON() ([]byte, error) {
	return json.Marshal(f.File)
}

// StmtError is an error on a single statement.
type StmtError struct {
	Stmt string
	Err  string
}

func (e *StmtError) Error() string { return e.Err }

// FileChecks holds check results for a file.
type FileChecks struct {
	Name string
}

type AppliedFile struct {
	File    File
	Start   time.Time
	End     time.Time
	Skipped int
	Applied []string
	Checks  []*FileChecks
	Error   *StmtError
}

func (a *AppliedFile) Name() string        { return a.File.Name() }
func (a *AppliedFile) Version() string     { return a.File.Version() }
func (a *AppliedFile) Description() string { return a.File.Description() }
func (a *AppliedFile) MarshalJSON() ([]byte, error) {
	type appliedJSON struct {
		Name        string    `json:"Name"`
		Version     string    `json:"Version"`
		Description string    `json:"Description,omitempty"`
		Start       time.Time `json:"Start"`
		End         time.Time `json:"End"`
		Skipped     int       `json:"Skipped,omitempty"`
		Applied     []string  `json:"Applied,omitempty"`
	}
	return json.Marshal(appliedJSON{
		Name: a.Name(), Version: a.Version(), Description: a.Description(), Start: a.Start, End: a.End, Skipped: a.Skipped, Applied: a.Applied,
	})
}

type MigrateApply struct {
	ctx     context.Context
	Env     Env
	Pending []*migrate.File
	Applied []*AppliedFile
	Target  string
	Current string
	Start   time.Time
	End     time.Time
	Error   error `json:"-"`
}

func NewMigrateApply(env Env) *MigrateApply {
	return &MigrateApply{ctx: context.Background(), Env: env}
}
func (m *MigrateApply) Driver() string { return m.Env.Driver }
func (m *MigrateApply) URL() *sqlclient.URL {
	return m.Env.URL
}
func (m *MigrateApply) Dir() string { return m.Env.Dir }

func (m *MigrateApply) MarshalJSON() ([]byte, error) {
	type applyJSON struct {
		Driver  string          `json:"Driver,omitempty"`
		URL     *sqlclient.URL  `json:"URL,omitempty"`
		Dir     string          `json:"Dir,omitempty"`
		Pending []*migrate.File `json:"Pending,omitempty"`
		Applied []*AppliedFile  `json:"Applied,omitempty"`
		Target  string          `json:"Target,omitempty"`
		Current string          `json:"Current,omitempty"`
		Start   time.Time       `json:"Start"`
		End     time.Time       `json:"End"`
		Message string          `json:"Message"`
	}
	msg := ""
	if len(m.Applied) == 0 && m.Target == "" {
		msg = "No migration files to execute"
	} else {
		count := len(m.Applied)
		msg = fmt.Sprintf("Migrated to version %s from %s (%d migrations in total)", m.Target, m.Current, count)
		// Note: in observed output, count is number of applied files and the
		// word is "1 migrations" (not singularized).
	}
	return json.Marshal(applyJSON{
		Driver: m.Env.Driver, URL: m.Env.URL, Dir: m.Env.Dir, Pending: m.Pending, Applied: m.Applied,
		Target: m.Target, Current: m.Current, Start: m.Start, End: m.End, Message: msg,
	})
}
