)''')
# change MigrateStatus struct fields: add AppliedRevisions hidden from template? Template .Applied should be revisions.
# Original struct print ordering unknown; define fields as Env, Available, Pending, Applied, Current, Next, Status
# but Marshal needs Applied revisions. Template field .Applied is []*migrate.Revision.
s=s.replace('''type MigrateStatus struct {
	Env       Env
	Available []*migrate.File
	Pending   []*migrate.File
	Current   string
	Next      string
	Status    string
}''','''type MigrateStatus struct {
	Env              Env
	Available        []*migrate.File
	Pending          []*migrate.File
	Applied          []*migrate.Revision
	AppliedRevisions []*migrate.Revision `json:"-"`
	Current          string
	Next             string
	Status           string
}''')
# In MarshalJSON above we used AppliedRevisions; make it use Applied if AppliedRevisions nil
s=s.replace("Applied: s.AppliedRevisions,", "Applied: appliedRevisions(s),")
# add helper
