{"command":"cat > commands_migrate.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"atlas/cmdlog"
	"atlas/migrate"
)

const dirFlagUsage = "select migration directory using URL format"
const driverURLUsage = "[driver://username:password@address/dbname?param=value] select a resource using the URL format"

func addDirFlags(cmd *cobra.Command, dir *string, format *string) {
	cmd.Flags().StringVar(dir, "dir", "file://migrations", dirFlagUsage)
	if format != nil {
		cmd.Flags().StringVar(format, "dir-format", "atlas", "select migration file format")
	}
}

// validateDirChecksum prints the checksum error report to stdout and returns the error.
func validateDirChecksum(cmd *cobra.Command, dir *migrationDir) error {
	line, text, err := dir.validateSum()
	if err == nil {
		return nil
	}
	out := cmd.OutOrStdout()
	if text != "" {
		fmt.Fprintf(out, "You have a checksum error in your migration directory.\n\n\tL%d: %s\n\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n", line, text)
	} else {
		fmt.Fprintf(out, "You have a checksum error in your migration directory.\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n")
	}
	return err
}

func openDirOrErr(dirURL, format string) (*migrationDir, error) {
	return openMigrationDirWithFormat(dirURL, format)
}

func canonicalDirURL(dir *migrationDir) string {
	// file://<path>?format=<format>
