	cmd.Flags().StringVar(dir, "dir", "file://migrations", dirFlagUsage)
	if format != nil {
		cmd.Flags().StringVar(format, "dir-format", "atlas", "select migration file format")
	}
}

// validateDirChecksum prints the checksum error report to stdout and returns the error.
func validateDirChecksum(cmd *cobra.Command, dir *migrationDir) error {
	line, text, err := dir.validateSum()
	if err == nil {
		return nil
	}
	out := cmd.OutOrStdout()
	if text != "" {
		fmt.Fprintf(out, "You have a checksum error in your migration directory.\n\n\tL%d: %s\n\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n", line, text)
	} else {
		fmt.Fprintf(out, "You have a checksum error in your migration directory.\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n")
	}
	return err
}

func openDirOrErr(dirURL, format string) (*migrationDir, error) {
	return openMigrationDirWithFormat(dirURL, format)
}

func canonicalDirURL(dir *migrationDir) string {
	// file://<path>?format=<format>
	return "file://" + dir.path + "?format=" + dir.format
}

func editContent(initial string, filename string) (string, error) {
	tmpPath := filepath.Join(os.TempDir(), filename)
	if err := os.WriteFile(tmpPath, []byte(initial), 0o644); err != nil {
		return "", err
	}
	defer os.Remove(tmpPath)
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vi"
	}
	c := exec.Command("sh", "-c", editor+" "+tmpPath)
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	if err := c.Run(); err != nil {
		return "", fmt.Errorf("exec edit: %w", err)
	}
	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// ---------- migrate hash ----------

func newMigrateHashCmd() *cobra.Command {
	var dir, dirFormat string
	cmd := &cobra.Command{
		Use:   "hash",
		Short: "Hash (re-)creates an integrity hash file for the migration directory.",
		Long: `'atlas migrate hash' computes the integrity hash sum of the migration directory and stores it in the atlas.sum file.
This command should be used whenever a manual change in the migration directory was made.`,
		Example: `  atlas migrate hash`,
		RunE: func(cmd *cobra.Command, args []string) error {
			d, err := openDirOrErr(dir, dirFormat)
			if err != nil {
				return err
			}
			return d.writeHash()
		},
	}
	addDirFlags(cmd, &dir, &dirFormat)
	return cmd
}

// ---------- migrate new ----------

func newMigrateNewCmd() *cobra.Command {
	var dir, dirFormat string
	var edit bool
	cmd := &cobra.Command{
		Use:     "new [flags] [name]",
		Short:   "Creates a new empty migration file in the migration directory.",
		Long:    `'atlas migrate new' creates a new migration according to the configured formatter without any statements in it.`,
		Example: `  atlas migrate new my-new-migration`,
		Args:    cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateNew(dir, dirFormat, edit, args)
		},
	}
	addDirFlags(cmd, &dir, &dirFormat)
	cmd.Flags().BoolVar(&edit, "edit", false, "edit the created migration file(s)")
	return cmd
}

func migrationFileName(format, timestamp, name string) (filenames []string, contents []string) {
	switch format {
	case "goose":
		fn := timestamp + "_" + name + ".sql"
		if name == "" {
			fn = timestamp + ".sql"
		}
		return []string{fn}, []string{"-- +goose Up\n\n-- +goose Down\n"}
	case "flyway":
		v := "V" + timestamp + "__" + name + ".sql"
		u := "U" + timestamp + "__" + name + ".sql"
		return []string{v, u}, []string{"", ""}
	case "liquibase":
		fn := timestamp + "_" + name + ".sql"
		if name == "" {
			fn = timestamp + ".sql"
		}
		return []string{fn}, []string{"--liquibase formatted sql"}
	case "dbmate":
		fn := timestamp + "_" + name + ".sql"
		if name == "" {
			fn = timestamp + ".sql"
		}
		return []string{fn}, []string{"-- migrate:up\n\n-- migrate:down\n"}
	default: // atlas
		fn := timestamp + "_" + name + ".sql"
		if name == "" {
			fn = timestamp + ".sql"
		}
		return []string{fn}, []string{""}
	}
}

func runMigrateNew(dirURL, dirFormat string, edit bool, args []string) error {
	path, qformat, err := parseMigrationDirURL(dirURL)
	if err != nil {
		return err
	}
	format := dirFormat
	if qformat != "" {
		format = qformat
	}
	if format == "" {
		format = "atlas"
	}
	if !knownDirFormats[format] {
		return fmt.Errorf("unknown dir format %q", format)
	}
	if fi, err := os.Stat(path); err == nil && !fi.IsDir() {
		return fmt.Errorf("sql/migrate: %q is not a dir", path)
	}
	name := ""
	if len(args) > 0 {
		name = args[0]
	}
	timestamp := time.Now().Format("20060102150405")
	filenames, contents := migrationFileName(format, timestamp, name)
	// Edit first file's content if requested (before creating anything)
	if edit {
		edited, err := editContent(contents[0], filenames[0])
		if err != nil {
			return err
		}
		contents[0] = edited
	}
	if err := os.MkdirAll(path, 0o755); err != nil {
		return err
	}
	for i, fn := range filenames {
		if err := os.WriteFile(filepath.Join(path, fn), []byte(contents[i]), 0o644); err != nil {
			return err
		}
	}
	d := &migrationDir{path: path, rawURL: dirURL, format: format}
	return d.writeHash()
}

// ---------- migrate validate ----------

func newMigrateValidateCmd() *cobra.Command {
	var devURL, dir, dirFormat string
	cmd := &cobra.Command{
		Use:   "validate",
		Short: "Validates the migration directories checksum and SQL statements.",
		Long: `'atlas migrate validate' computes the integrity hash sum of the migration directory and compares it to the
atlas.sum file. If there is a mismatch it will be reported. If the --dev-url flag is given, the migration
files are executed on the connected database in order to validate SQL semantics.`,
		Example: `  atlas migrate validate
  atlas migrate validate --dir "file:///path/to/migration/directory"
  atlas migrate validate --dir "file:///path/to/migration/directory" --dev-url "docker://mysql/8/dev"
  atlas migrate validate --env dev --dev-url "docker://postgres/15/dev?search_path=public"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			d, err := openDirOrErr(dir, dirFormat)
			if err != nil {
				return err
			}
			if err := validateDirChecksum(cmd, d); err != nil {
				return err
			}
			if devURL == "" {
				return nil
			}
			dev, err := openDBClient(devURL)
			if err != nil {
				return err
			}
			defer dev.Close()
			if dev.driver != "sqlite" {
				return fmt.Errorf("%s: not supported in this build", dev.driver)
			}
			// Replay on dev
			if err := cleanDev(dev); err != nil {
				return err
			}
			for _, f := range d.files {
				stmts := statementsForFile(f, d.format)
				for _, stmt := range stmts {
					if err := dev.sqlite.Exec(stmt); err != nil {
						_ = cleanDev(dev)
						return fmt.Errorf("replaying the migration directory: sql/migrate: read migration directory state: sql/migrate: executing statement %q from version %q: %s", stmt, f.Version(), err.Error())
					}
				}
			}
			_ = cleanDev(dev)
			return nil
		},
	}
	cmd.Flags().StringVar(&devURL, "dev-url", "", driverURLUsage)
	addDirFlags(cmd, &dir, &dirFormat)
	return cmd
}

// ---------- migrate import ----------

func newMigrateImportCmd() *cobra.Command {
	var from, to, dirFormat string
	cmd := &cobra.Command{
		Use:   "import",
		Short: "Import a migration directory from another migration management tool to the Atlas format.",
		Long:  `Import a migration directory from another migration management tool to the Atlas format.`,
		Example: `  atlas migrate import --from "file:///path/to/source/directory?format=liquibase" --to "file:///path/to/migration/directory"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateImport(cmd, from, to, dirFormat)
		},
	}
	cmd.Flags().StringVar(&from, "from", "file://migrations", "select migration directory using URL format")
	cmd.Flags().StringVar(&to, "to", "file://migrations", "select migration directory using URL format")
	cmd.Flags().StringVar(&dirFormat, "dir-format", "atlas", "select migration file format")
	return cmd
}

func runMigrateImport(cmd *cobra.Command, from, to, dirFormat string) error {
	// Determine source format: dir-format flag is target? Original: import checks
	// the source format (from URL query or dir-format?) If source is atlas, cannot import.
	fromPath, fromQFormat, err := parseMigrationDirURL(from)
	if err != nil {
		return err
	}
	srcFormat := dirFormat
	if fromQFormat != "" {
		srcFormat = fromQFormat
	}
	// The --to directory must be opened first? Original with default from==to==migrations
	// and no dir present gave stat error before the format check.
	// Open source dir (must exist)
	srcDir, err := openMigrationDirWithFormat(from, srcFormat)
	_ = srcDir
	if err != nil {
		// openMigrationDirWithFormat returns stat errors etc.
		// However if from==to default and the dir doesn't exist, the original
		// error is "sql/migrate: stat migrations: ..." which matches.
		return err
	}
	if srcFormat == "atlas" || srcFormat == "" {
		return fmt.Errorf("cannot import a migration directory already in \"atlas\" format")
	}
	toPath, toQFormat, err := parseMigrationDirURL(to)
	if err != nil {
		return err
	}
	_ = toQFormat
	_ = fromPath
	// Conversion: read migration files from source, write them to the target
	// directory (converting names/content where needed).
	if fi, err := os.Stat(toPath); err == nil && !fi.IsDir() {
		return fmt.Errorf("sql/migrate: %q is not a dir", toPath)
	}
	if err := os.MkdirAll(toPath, 0o755); err != nil {
		return err
	}
	// For goose/dbmate: strip section markers; flyway: rename V files; liquibase: keep sql.
	for _, f := range srcDir.files {
		content := f.Text()
		name := f.Name()
		switch srcFormat {
		case "goose":
			content = extractGooseUp(content)
			// ensure trailing semicolon/newline formatting as original statements?
			if content != "" && !strings.HasSuffix(content, "\n") {
				content += "\n"
			}
		case "dbmate":
			content = extractDbmateUp(content)
			if content != "" && !strings.HasSuffix(content, "\n") {
				content += "\n"
			}
		case "flyway":
			// name stays? Flyway names are converted to atlas timestamp names:
			// V<ts>__<desc>.sql -> <ts>_<desc>.sql
			ver := f.Version()
			desc := f.Description()
			if desc != "" {
				name = ver + "_" + desc + ".sql"
			} else {
				name = ver + ".sql"
			}
		case "liquibase":
			// liquibase formatted sql files may contain changeset markers; keep content
			// but strip the liquibase header line
			content = strings.TrimPrefix(content, "--liquibase formatted sql")
			content = strings.TrimLeft(content, "\n")
		}
		if err := os.WriteFile(filepath.Join(toPath, name), []byte(content), 0o644); err != nil {
			return err
		}
	}
	d := &migrationDir{path: toPath, rawURL: to, format: "atlas"}
	return d.writeHash()
}

// helpers used by migrate apply/status/set (defined in commands_migrate2.go)
var _ = strings.TrimSpace
var _ = cmdlog.Env{}
var _ = migrate.File{}
EOF
"}

