package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"atlas/cmdlog"
	"atlas/migrate"
)

// ---------- pending computation ----------

type pendingInfo struct {
	pending     []*migrate.File
	current     string
	hasCurrent  bool
	partial     *revision
	partialFile *migrate.File
	outOfOrder  []*migrate.File
	target      string
}

func isPartialRev(r *revision) bool {
	return r != nil && r.Total > 0 && r.Applied < r.Total
}

func computePending(files []*migrate.File, revs []*revision, execOrder string) pendingInfo {
	info := pendingInfo{}
	revByVersion := map[string]*revision{}
	for _, r := range revs {
		revByVersion[r.Version] = r
	}
	// partial revision (last partial in list)
	for _, r := range revs {
		if isPartialRev(r) {
			info.partial = r
		}
	}
	// current: last revision version if at least one fully applied (applied>=total)
	// or any revision exists and partial is not the sole revision.
	hasFull := false
	for _, r := range revs {
		if !isPartialRev(r) {
			hasFull = true
		}
	}
	if len(revs) > 0 && (hasFull || info.partial == nil) {
		info.current = revs[len(revs)-1].Version
		info.hasCurrent = true
		// Special case: sole partial revision -> no current
		if info.partial != nil && len(revs) == 1 && !hasFull {
			info.current = ""
			info.hasCurrent = false
		}
	}
	// first applied version for out-of-order detection
	var firstApplied, lastApplied string
	for _, r := range revs {
		if firstApplied == "" {
			firstApplied = r.Version
		}
		lastApplied = r.Version
	}
	// Out of order files: no revision, version between first and last applied (exclusive/inclusive?)
	if len(revs) > 0 {
		for _, f := range files {
			v := f.Version()
			if _, ok := revByVersion[v]; ok {
				continue
			}
			if info.partial != nil && v == info.partial.Version {
				continue
			}
			if firstApplied != "" && v > firstApplied && v < lastApplied {
				info.outOfOrder = append(info.outOfOrder, f)
			} else if firstApplied != "" && v == lastApplied {
				// version equal to last applied but no revision with that version (shouldn't happen)
			} else if len(revs) >= 2 && v > firstApplied && v <= lastApplied {
				info.outOfOrder = append(info.outOfOrder, f)
			}
			// Also mid between first and current when current is from a later file:
			// handled by v<lastApplied above (lastApplied is last revision, which may be partial)
			if v > firstApplied && v < lastApplied {
				// already added
			}
		}
		// The boundary case: file version < lastApplied but > firstApplied is out of order
		// even if lastApplied equals current from a set? Already covered.
		// Additional case used by observed: applied 1,2; mid between them qualifies.
	}
	if execOrder == "non-linear" {
		// all files without a complete revision
		for _, f := range files {
			r, ok := revByVersion[f.Version()]
			if !ok || isPartialRev(r) {
				info.pending = append(info.pending, f)
			}
		}
	} else if info.partial != nil {
		// pending starts at partial file
		started := false
		for _, f := range files {
			if f.Version() == info.partial.Version {
				started = true
				info.partialFile = f
			}
			if started {
				info.pending = append(info.pending, f)
			}
		}
		if !started {
			// partial file removed from dir: treat files after partial version as pending
			for _, f := range files {
				if f.Version() > info.partial.Version {
					info.pending = append(info.pending, f)
				}
			}
		}
	} else if info.hasCurrent {
		for _, f := range files {
			if f.Version() > info.current {
				info.pending = append(info.pending, f)
			}
		}
	} else {
		info.pending = append(info.pending, files...)
	}
	if len(info.pending) > 0 {
		info.target = info.pending[len(info.pending)-1].Version()
	}
	return info
}

// ---------- migrate apply ----------

func newMigrateApplyCmd() *cobra.Command {
	var urlFlag, dir, format, revisionsSchema, baseline, txMode, execOrder string
	var dryRun, allowDirty bool
	var lockTimeout time.Duration
	cmd := &cobra.Command{
		Use:   "apply [flags] [amount]",
		Short: "Applies pending migration files on the connected database.",
		Long: `'atlas migrate apply' reads the migration state of the connected database and computes what migrations are pending.
It then attempts to apply the pending migration files in the correct order onto the database. 
The first argument denotes the maximum number of migration files to apply.
As a safety measure 'atlas migrate apply' will abort with an error, if:
  - the migration directory is not in sync with the 'atlas.sum' file
  - the migration and database history do not match each other

If run with the "--dry-run" flag, atlas will not execute any SQL.`,
		Example: `  atlas migrate apply -u "mysql://user:pass@localhost:3306/dbname"
  atlas migrate apply --dir "file:///path/to/migration/directory" --url "mysql://user:pass@localhost:3306/dbname" 1
  atlas migrate apply --env dev 1
  atlas migrate apply --dry-run --env dev 1`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateApply(cmd, migrateApplyOpts{
				url: urlFlag, dir: dir, format: format, revisionsSchema: revisionsSchema, baseline: baseline,
				txMode: txMode, execOrder: execOrder, dryRun: dryRun, allowDirty: allowDirty, args: args,
			})
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", driverURLUsage)
	addDirFlags(cmd, &dir, nil)
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&revisionsSchema, "revisions-schema", "", "name of the schema the revisions table resides in")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().DurationVar(&lockTimeout, "lock-timeout", 10*time.Second, "set how long to wait for the database lock")
	cmd.Flags().StringVar(&baseline, "baseline", "", "start the first migration after the given baseline version")
	cmd.Flags().StringVar(&txMode, "tx-mode", "file", "set transaction mode [none, file, all]")
	cmd.Flags().StringVar(&execOrder, "exec-order", "linear", "set file execution order [linear, linear-skip, non-linear]")
	cmd.Flags().BoolVar(&allowDirty, "allow-dirty", false, "allow start working on a non-clean database")
	_ = lockTimeout
	return cmd
}

type migrateApplyOpts struct {
	url, dir, format, revisionsSchema, baseline, txMode, execOrder string
	dryRun, allowDirty                                             bool
	args                                                           []string
}

func formatDuration(d time.Duration) string {
	return d.String()
}

func runMigrateApply(cmd *cobra.Command, o migrateApplyOpts) error {
	// amount parsing
	var amount *int
	if len(o.args) > 0 {
		raw := o.args[0]
		n, err := strconv.ParseInt(raw, 10, 64)
		if err != nil {
			detail := "invalid syntax"
			// strconv error detail
			if ne, ok := err.(*strconv.NumError); ok {
				detail = ne.Err.Error()
			}
			return fmt.Errorf("invalid amount argument %q (%s). Omit the argument or pass a valid integer instead", raw, detail)
		}
		if n == 0 {
			return fmt.Errorf("cannot apply '%s' migration files", raw)
		}
		if n < 0 {
			return fmt.Errorf("invalid amount argument %q (invalid syntax). Omit the argument or pass a valid integer instead", raw)
		}
		v := int(n)
		amount = &v
	}
	dir, err := openDirOrErr(o.dir, "atlas")
	// dir-format for migrate apply is not a flag; the URL may carry format
	if err != nil {
		// try with format from URL handled in openDir; still return
		return err
	}
	// Detect dir format from URL query (openDirOrErr used atlas default listing);
	// re-open properly respecting query format.
	if qd, qerr := openMigrationDirWithFormat(o.dir, "atlas"); qerr == nil {
		dir = qd
	}
	if err := validateDirChecksum(cmd, dir); err != nil {
		return err
	}
	if o.url == "" {
		return fmt.Errorf("required flag \"url\" not set")
	}
	client, err := openDBClient(o.url)
	if err != nil {
		return err
	}
	defer client.Close()
	if client.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", client.driver)
	}
	// template parse check (after dir checksum, before execution) for format
	var tmplText string
	_ = tmplText
	if o.format != "" {
		dummy := cmdlog.NewMigrateApply(cmdlog.Env{Driver: client.driver, URL: client.url, Dir: o.dir})
		if _, perr := parseTemplateOnly(o.format, jsonOnlyFuncs(), "parse format"); perr != nil {
			return perr
		}
		_ = dummy
	}
	if o.revisionsSchema != "" && o.revisionsSchema != "main" {
		// The check happens when the executor tries to write revisions; in
		// dry-run it also errors (observed). But for status-like reads it
		// would not. For apply, return it before executing (after dir+url).
		// However the original only errors after pending computation when
		// there is something to do? We return it now to match common cases.
		// To avoid breaking the no-pending case, we defer: check later.
	}
	revs, err := ensureRevisionsTable(client)
	if err != nil {
		return err
	}
	if o.baseline != "" && o.allowDirty {
		return fmt.Errorf("sql/migrate: baseline and allow-dirty are mutually exclusive")
	}
	// baseline handling
	if o.baseline != "" {
		found := false
		for _, f := range dir.files {
			if f.Version() == o.baseline {
				found = true
			}
		}
		if !found {
			return fmt.Errorf("baseline version %q not found", o.baseline)
		}
		if len(revs) == 0 {
			// insert baseline revision
			var bf *migrate.File
			for _, f := range dir.files {
				if f.Version() == o.baseline {
					bf = f
				}
			}
			rev := &revision{Version: o.baseline, Description: bf.Description(), Type: migrate.RevisionTypeBaseline, Applied: 0, Total: 0, ExecutedAt: nowTime(), Hash: fileHash(bf)}
			if !o.dryRun {
				// Baseline is recorded even in dry-run? The original dry-run
				// created the revisions table but did it insert baseline? We
				// record baseline only when not dry-run to be safe, but the
				// observed baseline apply was a real apply. For dry-run the
				// executor still computes pending from baseline.
				_ = insertRevision(client, rev, nil)
			} else {
				_ = insertRevision(client, rev, nil)
				// Remove it again? Instead we keep in-memory list only.
				_ = deleteRevision(client, rev.Version)
			}
			revs = append(revs, rev)
		}
	}
	// dirty check
	if len(revs) == 0 && o.baseline == "" && !o.allowDirty {
		realm, err := inspectSQLiteRealm(client)
		if err != nil {
			return err
		}
		count := 0
		for _, s := range realm.Schemas {
			count += len(s.Tables)
		}
		if count > 1 {
			return fmt.Errorf("sql/migrate: connected database is not clean: found multiple tables: %d. baseline version or allow-dirty is required", count)
		}
	}
	if o.execOrder != "linear" && o.execOrder != "linear-skip" && o.execOrder != "non-linear" {
		return fmt.Errorf("unknown execution order: %q", o.execOrder)
	}
	info := computePending(dir.files, revs, o.execOrder)
	// linear out-of-order check
	if o.execOrder == "linear" && len(info.outOfOrder) > 0 {
		return fmt.Errorf("migration file %s was added out of order. See: https://atlasgo.io/versioned/apply#non-linear-error", info.outOfOrder[0].Name())
	}
	pending := info.pending
	if amount != nil && *amount < len(pending) {
		pending = pending[:*amount]
	}
	if o.revisionsSchema != "" && o.revisionsSchema != "main" {
		return fmt.Errorf("cannot store revisions-table in a separate schema (%q) with SQLite driver", o.revisionsSchema)
	}
	// Build report
	report := cmdlog.NewMigrateApply(cmdlog.Env{Driver: client.driver, URL: client.url, Dir: o.dir})
	report.Current = ""
	if info.hasCurrent {
		// For the report JSON, Current is only set when there is no pending target?
		// Observed: pending case -> Current omitted, target set. No-pending -> Current set.
	}
	report.Pending = info.pending // full pending (before amount limiting?) Original: Pending in JSON was the pending list to apply (amount limited?)
	// Amount limiting affects Pending in report? Assume pending after limit for execution.
	report.Pending = pending
	if len(pending) > 0 {
		report.Target = pending[len(pending)-1].Version()
	} else {
		if info.hasCurrent {
			report.Current = info.current
		} else if len(revs) > 0 {
			report.Current = revs[len(revs)-1].Version
		}
	}
	report.Start = time.Now()

	if len(pending) == 0 {
		report.End = time.Now()
		if o.format != "" {
			out, err := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "execute log template")
			if err != nil {
				return err
			}
			fmt.Fprint(cmd.OutOrStdout(), out)
			return nil
		}
		fmt.Fprintln(cmd.OutOrStdout(), "No migration files to execute")
		return nil
	}

	// tx-mode validation happens inside the executor (after header in default mode).
	txValid := o.txMode == "none" || o.txMode == "file" || o.txMode == "all"

	if o.format == "" {
		// header
		if info.hasCurrent && info.current != "" {
			// current for header: if partial, current is partial version; computePending sets it
			// When there is a partial first revision, hasCurrent is false.
			fmt.Fprintf(cmd.OutOrStdout(), "Migrating to version %s from %s (%d migrations in total):\n\n", report.Target, headerCurrent(info, revs), len(pending))
		} else if info.partial != nil && len(revs) > 1 {
			fmt.Fprintf(cmd.OutOrStdout(), "Migrating to version %s from %s (%d migrations in total):\n\n", report.Target, info.partial.Version, len(pending))
		} else if info.partial != nil && info.partialFile != nil {
			fmt.Fprintf(cmd.OutOrStdout(), "Migrating to version %s from %s (%d migrations in total):\n\n", report.Target, info.partial.Version, len(pending))
		} else {
			fmt.Fprintf(cmd.OutOrStdout(), "Migrating to version %s (%d migrations in total):\n\n", report.Target, len(pending))
		}
	}

	if !txValid && !o.dryRun {
		// Executor fails before applying any file.
		report.End = time.Now()
		err := fmt.Errorf("unknown tx-mode %q", o.txMode)
		if o.format != "" {
			report.Error = err
			out, terr := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "execute log template")
			if terr != nil {
				return terr
			}
			fmt.Fprint(cmd.OutOrStdout(), out)
			return err
		}
		// default report: header already printed; then indented error and summary
		fmt.Fprintf(cmd.OutOrStdout(), "    %s\n\n", err.Error())
		fmt.Fprintf(cmd.OutOrStdout(), "  -------------------------\n")
		fmt.Fprintf(cmd.OutOrStdout(), "  -- -2562047h47m16.854775808s\n")
		// The original prints a trailing blank line after this in the tx-mode case.
		fmt.Fprintln(cmd.OutOrStdout(), "")
		return err
	}

	startAll := time.Now()
	var appliedFiles []*cmdlog.AppliedFile
	okMigrations := 0
	okStatements := 0
	errStatements := 0
	var firstErr error
	var errFile *cmdlog.AppliedFile

	// Transaction handling for "all"
	if !o.dryRun && o.txMode == "all" {
		_ = client.sqlite.Exec("BEGIN")
	}
	for _, f := range pending {
		stmts := statementsForFile(f, dir.format)
		startIdx := 0
		if info.partial != nil && info.partialFile != nil && f.Version() == info.partial.Version {
			startIdx = info.partial.Applied
		}
		af := &cmdlog.AppliedFile{File: cmdlog.File{File: f}, Start: time.Now()}
		fileStart := time.Now()
		if o.format == "" {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- migrating version %s\n", f.Version())
		}
		// per-file transaction
		if !o.dryRun && o.txMode == "file" {
			_ = client.sqlite.Exec("BEGIN")
		}
		var appliedStmts []string
		var fileErr error
		var failedStmt string
		execStart := time.Now()
		for i := startIdx; i < len(stmts); i++ {
			stmt := stmts[i]
			if o.format == "" {
				fmt.Fprintf(cmd.OutOrStdout(), "    -> %s\n", stmt)
			}
			appliedStmts = append(appliedStmts, stmt)
			if o.dryRun {
				continue
			}
			if err := client.sqlite.Exec(stmt); err != nil {
				fileErr = fmt.Errorf("sql/migrate: executing statement %q from version %q: %s", stmt, f.Version(), err.Error())
				failedStmt = stmt
				errStatements++
				if o.format == "" {
					fmt.Fprintf(cmd.OutOrStdout(), "    %s\n", err.Error())
				}
				af.Error = &cmdlog.StmtError{Stmt: stmt, Text: err.Error()}
				break
			}
			okStatements++
		}
		execDuration := time.Since(execStart)
		af.End = time.Now()
		af.Applied = appliedStmts
		if fileErr != nil {
			firstErr = fileErr
			errFile = af
			appliedFiles = append(appliedFiles, af)
			if !o.dryRun {
				if o.txMode == "file" || o.txMode == "all" {
					_ = client.sqlite.Exec("ROLLBACK")
				}
				// tx none: record partial revision
				if o.txMode == "none" {
					appliedCount := startIdx + (len(appliedStmts) - 1) // failed stmt not applied; appliedStmts includes failed
					// appliedStmts includes the failed statement as last element; successes are before it in this file run plus startIdx
					// Count successes in this run:
					successInRun := 0
					// appliedStmts length includes failed; successes = len-1
					if len(appliedStmts) > 0 {
						successInRun = len(appliedStmts) - 1
					}
					appliedCount = startIdx + successInRun
					var partialHashes []string
					// hashes of all successfully applied statements (from start of file)
					for j := 0; j < appliedCount && j < len(stmts); j++ {
						partialHashes = append(partialHashes, stmtHash(stmts[j]))
					}
					rev := &revision{Version: f.Version(), Description: f.Description(), Type: migrate.RevisionTypeApplied, Applied: appliedCount, Total: len(stmts), ExecutedAt: time.Now(), ExecutionTime: execDuration, Error: sqliteErrString(fileErr), ErrorStmt: failedStmt, Hash: fileHash(f)}
					// Error field in revision should be the raw sqlite error, not wrapped
					rev.Error = lastSQLiteError(fileErr)
					_ = insertRevision(client, rev, partialHashes)
				}
			}
			_ = fileStart
			break
		}
		// success
		okMigrations++
		if !o.dryRun {
			if o.txMode == "file" {
				_ = client.sqlite.Exec("COMMIT")
			}
			// record revision (for tx all, record inside transaction; commit later)
			rev := &revision{Version: f.Version(), Description: f.Description(), Type: migrate.RevisionTypeApplied, Applied: len(stmts), Total: len(stmts), ExecutedAt: time.Now(), ExecutionTime: execDuration, Hash: fileHash(f)}
			// For resumed partial, Applied/Total should be full file totals
			_ = insertRevision(client, rev, nil)
		}
		appliedFiles = append(appliedFiles, af)
		if o.format == "" {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- ok (%s)\n\n", formatDuration(time.Since(fileStart)))
		}
	}
	if !o.dryRun && o.txMode == "all" {
		if firstErr != nil {
			_ = client.sqlite.Exec("ROLLBACK")
		} else {
			_ = client.sqlite.Exec("COMMIT")
		}
	}
	// In tx file mode, a failed file's revision should not be recorded (rolled back) - handled.
	// In tx all, revisions recorded inside tx are rolled back on error - handled by transaction
	// (but our insertRevision used same connection, so it participates).

	report.Applied = appliedFiles
	report.End = time.Now()
	totalDuration := time.Since(startAll)

	if o.format != "" {
		if firstErr != nil {
			report.Error = firstErr
		}
		out, terr := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "execute log template")
		if terr != nil {
			return terr
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		if firstErr != nil {
			return firstErr
		}
		return nil
	}

	// summary
	fmt.Fprintf(cmd.OutOrStdout(), "  -------------------------\n")
	fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", formatDuration(totalDuration))
	if firstErr != nil {
		// migrations summary
		if okMigrations > 0 {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", pluralMigrationsWithErrors(okMigrations, 1))
		} else {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- 1 migration with errors\n")
		}
		if okStatements > 0 {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", pluralStatementsWithErrors(okStatements, errStatements))
		} else {
			fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", pluralStatementsWithErrorsOnly(errStatements))
		}
		return firstErr
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", pluralMigrations(len(pending)))
	totalStmts := 0
	for _, f := range pending {
		stmts := statementsForFile(f, dir.format)
		startIdx := 0
		if info.partial != nil && info.partialFile != nil && f.Version() == info.partial.Version {
			startIdx = info.partial.Applied
		}
		totalStmts += len(stmts) - startIdx
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", pluralStatements(totalStmts))
	_ = errFile
	return nil
}

func headerCurrent(info pendingInfo, revs []*revision) string {
	if info.partial != nil {
		return info.partial.Version
	}
	return info.current
}

func sqliteErrString(err error) string { return err.Error() }
func lastSQLiteError(wrapped error) string {
	// wrapped is sql/migrate: executing statement "..." from version "...": <sqlite>
	// Extract after last ": "
	s := wrapped.Error()
	idx := strings.LastIndex(s, ": ")
	if idx >= 0 {
		return s[idx+2:]
	}
	return s
}

func pluralMigrations(n int) string {
	if n == 1 {
		return "1 migration"
	}
	return fmt.Sprintf("%d migrations", n)
}
func pluralStatements(n int) string {
	if n == 1 {
		return "1 sql statement"
	}
	return fmt.Sprintf("%d sql statements", n)
}
func pluralMigrationsWithErrors(ok, withErr int) string {
	parts := []string{}
	parts = append(parts, fmt.Sprintf("%d migration ok", ok))
	if withErr == 1 {
		parts = append(parts, "1 with errors")
	} else {
		parts = append(parts, fmt.Sprintf("%d with errors", withErr))
	}
	if ok == 1 {
		// grammar stays "1 migration ok"
	}
	return strings.Join(parts, ", ")
}
func pluralStatementsWithErrors(ok, withErr int) string {
	okPart := fmt.Sprintf("%d sql statement ok", ok)
	if ok != 1 {
		okPart = fmt.Sprintf("%d sql statements ok", ok)
	}
	errPart := "1 with errors"
	if withErr != 1 {
		errPart = fmt.Sprintf("%d with errors", withErr)
	}
	return okPart + ", " + errPart
}
func pluralStatementsWithErrorsOnly(withErr int) string {
	if withErr == 1 {
		return "1 sql statement with errors"
	}
	return fmt.Sprintf("%d sql statements with errors", withErr)
}

// ---------- migrate status ----------

func newMigrateStatusCmd() *cobra.Command {
	var urlFlag, format, dir, dirFormat, revisionsSchema string
	cmd := &cobra.Command{
		Use:   "status",
		Short: "Get information about the current migration status.",
		Long:  `'atlas migrate status' reports information about the current status of a connected database compared to the migration directory.`,
		Example: `  atlas migrate status --url "mysql://user:pass@localhost:3306/"
  atlas migrate status --url "mysql://user:pass@localhost:3306/" --dir "file:///path/to/migration/directory"`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateStatus(cmd, urlFlag, format, dir, dirFormat, revisionsSchema)
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", driverURLUsage)
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	addDirFlags(cmd, &dir, &dirFormat)
	cmd.Flags().StringVar(&revisionsSchema, "revisions-schema", "", "name of the schema the revisions table resides in")
	_ = revisionsSchema
	return cmd
}

func runMigrateStatus(cmd *cobra.Command, urlFlag, format, dirURL, dirFormat, revisionsSchema string) error {
	dir, err := openDirOrErr(dirURL, dirFormat)
	if err != nil {
		return err
	}
	if err := validateDirChecksum(cmd, dir); err != nil {
		return err
	}
	client, err := openDBClient(urlFlag)
	if err != nil {
		return err
	}
	defer client.Close()
	if client.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", client.driver)
	}
	revs, err := ensureRevisionsTable(client)
	if err != nil {
		return err
	}
	info := computePending(dir.files, revs, "linear")
	report := &cmdlog.MigrateStatus{
		Env:       cmdlog.Env{Driver: client.driver, URL: client.url, Dir: canonicalDirURL(dir)},
		Available: dir.files,
	}
	report.Applied = revs
	// Current / Next / Status
	isPartial := info.partial != nil
	if isPartial {
		file := info.partialFile
		var total int
		if file != nil {
			total = len(statementsForFile(file, dir.format))
		} else {
			total = int(info.partial.Total)
		}
		report.Count = int(info.partial.Applied)
		report.Total = total
		report.Error = info.partial.Error
		report.SQL = info.partial.ErrorStmt
	}
	outOfOrder := info.outOfOrder
	if len(outOfOrder) > 0 && info.partial == nil {
		// Status pending includes only files after current (JSON), but text counts out-of-order
	}
	if info.partial != nil {
		if !info.hasCurrent && len(revs) == 1 {
			report.Current = "No migration applied yet"
		} else {
			report.Current = info.partial.Version
		}
		report.Next = info.partial.Version
		report.Status = "PENDING"
		report.Pending = info.pending
	} else if len(info.pending) > 0 {
		if info.hasCurrent {
			report.Current = info.current
		} else {
			report.Current = "No migration applied yet"
		}
		if len(outOfOrder) > 0 {
			report.Next = "UNKNOWN"
		} else {
			report.Next = info.pending[0].Version()
		}
		report.Status = "PENDING"
		report.Pending = info.pending
	} else {
		// No pending; check out-of-order still makes it pending? If out-of-order files exist
		// but no later pending, report pending with UNKNOWN.
		if len(outOfOrder) > 0 {
			if info.hasCurrent {
				report.Current = info.current
			} else {
				report.Current = "No migration applied yet"
			}
			report.Next = "UNKNOWN"
			report.Status = "PENDING"
			report.Pending = info.pending
		} else {
			if info.hasCurrent {
				report.Current = info.current
			} else if len(revs) > 0 {
				report.Current = revs[len(revs)-1].Version
			} else {
				report.Current = "No migration applied yet"
			}
			report.Next = "Already at latest version"
			report.Status = "OK"
		}
	}
	if format != "" {
		out, err := executeTemplate(format, report, jsonOnlyFuncs(), "parse format", "")
		if err != nil {
			return err
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		return nil
	}
	// Text output
	fmt.Fprintf(cmd.OutOrStdout(), "Migration Status: %s\n", report.Status)
	curText := report.Current
	if isPartial {
		if len(revs) == 1 && !info.hasCurrent {
			curText = fmt.Sprintf("No migration applied yet (%d statements applied)", info.partial.Applied)
		} else {
			curText = fmt.Sprintf("%s (%d statements applied)", report.Current, info.partial.Applied)
		}
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- Current Version: %s\n", curText)
	nextText := report.Next
	if isPartial {
		left := report.Total - int(info.partial.Applied)
		nextText = fmt.Sprintf("%s (%d statements left)", report.Next, left)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- Next Version:    %s\n", nextText)
	executedText := fmt.Sprintf("%d", len(revs))
	if isPartial {
		executedText = fmt.Sprintf("%d (last one partially)", len(revs))
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- Executed Files:  %s\n", executedText)
	pendingCount := len(info.pending)
	pendingText := fmt.Sprintf("%d", pendingCount)
	if report.Next == "UNKNOWN" {
		pendingText = fmt.Sprintf("%d (%d out of order)", pendingCount+len(outOfOrder), len(outOfOrder))
	}
	fmt.Fprintf(cmd.OutOrStdout(), "  -- Pending Files:   %s\n", pendingText)
	if isPartial && (info.partial.Error != "" || info.partial.ErrorStmt != "") {
		fmt.Fprintf(cmd.OutOrStdout(), "\nLast migration attempt had errors:\n")
		fmt.Fprintf(cmd.OutOrStdout(), "  -- SQL:   %s\n", info.partial.ErrorStmt)
		fmt.Fprintf(cmd.OutOrStdout(), "  -- ERROR: %s\n", info.partial.Error)
	} else if len(outOfOrder) > 0 && report.Next == "UNKNOWN" {
		fmt.Fprintf(cmd.OutOrStdout(), "\n  ERROR: migration file %s was added out of order. See: https://atlasgo.io/versioned/apply#non-linear-error\n", outOfOrder[0].Name())
	}
	return nil
}

// ---------- migrate set ----------

func newMigrateSetCmd() *cobra.Command {
	var urlFlag, dir, dirFormat, revisionsSchema string
	cmd := &cobra.Command{
		Use:   "set [flags] [version]",
		Short: "Set the current version of the migration history table.",
		Long: `'atlas migrate set' edits the revision table to consider all migrations up to and including the given version
to be applied. This command is usually used after manually making changes to the managed database.`,
		Example: `  atlas migrate set 3 --url "mysql://user:pass@localhost:3306/"
  atlas migrate set --env local
  atlas migrate set 1.2.4 --url "mysql://user:pass@localhost:3306/my_db" --revision-schema my_revisions`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateSet(cmd, urlFlag, dir, dirFormat, revisionsSchema, args)
		},
	}
	cmd.Flags().StringVarP(&urlFlag, "url", "u", "", driverURLUsage)
	addDirFlags(cmd, &dir, &dirFormat)
	cmd.Flags().StringVar(&revisionsSchema, "revisions-schema", "", "name of the schema the revisions table resides in")
	return cmd
}

func runMigrateSet(cmd *cobra.Command, urlFlag, dirURL, dirFormat, revisionsSchema string, args []string) error {
	dir, err := openDirOrErr(dirURL, dirFormat)
	if err != nil {
		return err
	}
	if err := validateDirChecksum(cmd, dir); err != nil {
		return err
	}
	client, err := openDBClient(urlFlag)
	if err != nil {
		return err
	}
	defer client.Close()
	if client.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", client.driver)
	}
	revs, err := ensureRevisionsTable(client)
	if err != nil {
		return err
	}
	if revisionsSchema != "" && revisionsSchema != "main" {
		return fmt.Errorf("cannot store revisions-table in a separate schema (%q) with SQLite driver", revisionsSchema)
	}
	if len(args) != 1 {
		return fmt.Errorf("accepts 1 arg(s), received %d", len(args))
	}
	version := args[0]
	// Find target file
	var target *migrate.File
	for _, f := range dir.files {
		if f.Version() == version {
			target = f
		}
	}
	if target == nil {
		return fmt.Errorf("migration with version %q not found", version)
	}
	// Current revisions by version
	revByVersion := map[string]*revision{}
	for _, r := range revs {
		revByVersion[r.Version] = r
	}
	// Files up to and including target
	var toSet []*migrate.File
	for _, f := range dir.files {
		if f.Version() <= version {
			toSet = append(toSet, f)
		}
	}
	var toRemove []*revision
	// Revisions with version > target (and version is in files or any) should be removed if their version > target
	// Original removes revisions that correspond to files after target? It removed files 2,3 when setting to 1.
	for _, r := range revs {
		if r.Version > version {
			toRemove = append(toRemove, r)
		}
	}
	// Determine actual changes (set = those in toSet not already in revs, removed = toRemove whose version corresponds to a file? )
	// Apply removals first? Output describes set count.
	var setList []*migrate.File
	for _, f := range toSet {
		if _, ok := revByVersion[f.Version()]; !ok {
			setList = append(setList, f)
		}
	}
	// Remove revisions > version (only those that are files? observed removed both when they were files)
	for _, r := range toRemove {
		_ = deleteRevision(client, r.Version)
	}
	for _, f := range setList {
		rev := &revision{Version: f.Version(), Description: f.Description(), Type: migrate.RevisionTypeSet, Applied: 0, Total: 0, ExecutedAt: time.Now(), Hash: fileHash(f)}
		_ = insertRevision(client, rev, nil)
	}
	if len(setList) > 0 {
		plural := "set"
		_ = plural
		fmt.Fprintf(cmd.OutOrStdout(), "Current version is %s (%d set):\n\n", version, len(setList))
		for _, f := range setList {
			fmt.Fprintf(cmd.OutOrStdout(), "  + %s (%s)\n", f.Version(), f.Description())
		}
		// trailing blank line? Original stdout had a blank line after list? Its display showed empty line.
		// We check: the printed output in probes ended without extra blank in repr? It showed \n\n at start and lines.
		// The original stdout for set ended with "\n" after last line plus a blank? In probe, after list there was an empty line in display.
		// We'll not add extra.
		fmt.Fprintln(cmd.OutOrStdout(), "")
		_ = toRemove
		return nil
	}
	if len(toRemove) > 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "Current version is %s (%d removed):\n\n", version, len(toRemove))
		// Removed list should be in file order
		// Build removed files list in version order from revs > target
		for _, r := range toRemove {
			fmt.Fprintf(cmd.OutOrStdout(), "  - %s (%s)\n", r.Version, r.Description)
		}
		fmt.Fprintln(cmd.OutOrStdout(), "")
		return nil
	}
	// No changes: what does original print? e.g. setting to same version already set
	fmt.Fprintf(cmd.OutOrStdout(), "Current version is %s (%d set):\n\n", version, 0)
	fmt.Fprintln(cmd.OutOrStdout(), "")
	return nil
}
EOF
"}

