type migrateDiffOpts struct {
	to, schemas                              []string
	devURL, dir, dirFormat, format, qualifier string
	edit                                     bool
	args                                     []string
}

// migratePlanData is the template data for migrate diff --format.
// Its type name in errors would be... we use a local struct; the original
// uses a plan type. The sql function expects this type.
type migratePlanData struct {
	Name    string
	Applied bool // placeholder?
}

func runMigrateDiff(cmd *cobra.Command, o migrateDiffOpts) error {
	dir, err := openDirOrErr(o.dir, o.dirFormat)
	if err != nil {
		// dir may not exist: unlike other migrate commands, migrate diff creates it?
		// Original: if migrations dir does not exist, diff creates? It computed current as empty.
		// Check: openMigrationDirWithFormat stats and errors. For migrate diff the
		// original behaviour when dir is missing is to treat current state as empty
		// and create the directory on write. So if stat error, create a placeholder.
		if !strings.Contains(err.Error(), "stat") {
			return err
		}
		// create placeholder dir object
		path, _, perr := parseMigrationDirURL(o.dir)
		if perr != nil {
			return perr
		}
		dir = &migrationDir{path: path, rawURL: o.dir, format: o.dirFormat}
		dir.files = nil
	} else {
		if err := validateDirChecksum(cmd, dir); err != nil {
			return err
		}
	}
	// Dev client
	dev, err := openDBClient(o.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	if dev.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", dev.driver)
	}
	// Desired state
	classes, err := classifyStateURLs(o.to)
	if err != nil {
		return err
	}
	// Template parse for format (before reading states) - original parses early
	if o.format != "" {
		if _, perr := parseTemplateOnly(o.format, sqlFuncMapForMigrateDiff(), "parse format"); perr != nil {
			return perr
		}
	}
	desired, _, err := readState(classes, dev, o.schemas, nil)
	if err != nil {
		return err
	}
	// Current state: replay migration files on dev
	current, err := replayDirOnDev(dir, dev)
	if err != nil {
		return err
	}
	changes := realmDiff(current, desired)
	sqlChanges, err := planChanges(current, desired, changes, "")
	if err != nil {
		return err
	}
	if len(sqlChanges) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "The migration directory is synced with the desired state, no changes to be made")
		return nil
	}
	// Format content
	var content string
	if o.format != "" {
		// The template is applied to a plan object; we emulate by executing
		// with a data object that our sql function can handle.
		planData := &planTemplateData{Changes: sqlChanges, Desired: desired, Current: current}
		out, err := executeTemplate(o.format, planData, migrateDiffFuncs(planData), "parse format", "")
		if err != nil {
			return err
		}
		content = out
	} else {
		content = changesToSQLText(sqlChanges, "")
	}
	name := ""
	if len(o.args) > 0 {
		name = o.args[0]
	}
	timestamp := time.Now().Format("20060102150405")
	filenames, _ := migrationFileName(dir.format, timestamp, name)
	filename := filenames[0]
	if o.edit {
		edited, err := editContent(content, filename)
		if err != nil {
			return err
		}
		content = edited
	}
	// Write file(s): for flyway, also undo file empty
	if err := ensureDirExists(dir.path); err != nil {
		return err
	}
	if err := writeFileContent(filepath.Join(dir.path, filename), content); err != nil {
		return err
	}
	if dir.format == "flyway" && len(filenames) > 1 {
		_ = writeFileContent(filepath.Join(dir.path, filenames[1]), "")
	}
	// Update hash
	return dir.writeHash()
}

func ensureDirExists(p string) error {
	return mkdirAll(p)
}

func replayDirOnDev(dir *migrationDir, dev *dbClient) (*schema.Realm, error) {
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	// refresh files list
	if dir.path != "" {
		_ = dir.refresh()
		if dir.files == nil {
			// directory may not have existed; refresh may have failed silently
			files, _ := dir.listFiles()
			dir.files = files
		}
	}
	for _, f := range dir.files {
		stmts := statementsForFile(f, dir.format)
		for _, stmt := range stmts {
			if err := dev.sqlite.Exec(stmt); err != nil {
				_ = cleanDev(dev)
				return nil, fmt.Errorf("sql/migrate: read migration directory state: sql/migrate: executing statement %q from version %q: %s", stmt, f.Version(), err.Error())
			}
		}
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return realm, nil
}

