{"command":"cat > commands_migrate3.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"text/template"
	"time"

	"github.com/spf13/cobra"

	"atlas/cmdlog"
	"atlas/migrate"
	"atlas/migratelint"
	"atlas/schema"
	"atlas/sqlcheck"
)

// ---------- migrate diff ----------

func newMigrateDiffCmd() *cobra.Command {
	var to, schemas []string
	var devURL, dir, dirFormat, format, qualifier string
	var lockTimeout time.Duration
	var edit bool
	cmd := &cobra.Command{
		Use:   "diff [flags] [name]",
		Short: "Compute the diff between the migration directory and a desired state and create a new migration file.",
		Long: `The 'atlas migrate diff' command uses the dev-database to calculate the current state of the migration directory
by executing its files. It then compares its state to the desired state and create a new migration file containing
SQL statements for moving from the current to the desired state. The desired state can be another another database,
an HCL, SQL, or ORM schema. See: https://atlasgo.io/versioned/diff`,
		Example: `  atlas migrate diff --dev-url "docker://mysql/8/dev" --to "file://schema.hcl"
  atlas migrate diff --dev-url "docker://postgres/15/dev?search_path=public" --to "file://atlas.hcl" add_users_table
  atlas migrate diff --dev-url "mysql://user:pass@localhost:3306/dev" --to "mysql://user:pass@localhost:3306/dbname"
  atlas migrate diff --env dev --format '{{ sql . "  " }}'`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateDiff(cmd, migrateDiffOpts{
				to: to, schemas: schemas, devURL: devURL, dir: dir, dirFormat: dirFormat, format: format, qualifier: qualifier, edit: edit, args: args,
			})
		},
	}
	cmd.Flags().StringSliceVar(&to, "to", nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().StringVar(&dir, "dir", "file://migrations", "select migration directory using URL format")
	cmd.Flags().StringVar(&dirFormat, "dir-format", "atlas", "select migration file format")
	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().DurationVar(&lockTimeout, "lock-timeout", 10*time.Second, "set how long to wait for the database lock")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&qualifier, "qualifier", "", "qualify tables with custom qualifier when working on a single schema")
	cmd.Flags().BoolVar(&edit, "edit", false, "edit the generated migration file(s)")
	_ = cmd.MarkFlagRequired("to")
	_ = cmd.MarkFlagRequired("dev-url")
	return cmd
}

type migrateDiffOpts struct {
	to, schemas                               []string
	devURL, dir, dirFormat, format, qualifier string
	edit                                      bool
	args                                      []string
}

func sqlFuncForPlan() func(*migrate.Plan, ...string) (string, error) {
	return func(p *migrate.Plan, indent ...string) (string, error) {
		ind := ""
		if len(indent) > 0 {
			ind = indent[0]
		}
		return changesToSQLText(p.Changes, ind), nil
	}
}

func migrateDiffFuncs() template.FuncMap {
	return template.FuncMap{
		"sql": sqlFuncForPlan(),
	}
}

func runMigrateDiff(cmd *cobra.Command, o migrateDiffOpts) error {
	dir, err := openDirOrErr(o.dir, o.dirFormat)
	dirMissing := false
	if err != nil {
		if !strings.Contains(err.Error(), "stat") {
			return err
		}
		dirMissing = true
		path, _, perr := parseMigrationDirURL(o.dir)
		if perr != nil {
			return perr
		}
		dir = &migrationDir{path: path, rawURL: o.dir, format: o.dirFormat}
		dir.files = nil
	}
	if !dirMissing {
		if err := validateDirChecksum(cmd, dir); err != nil {
			return err
		}
	}
	// Template parse for format (original parses before reading desired)
	if o.format != "" {
		if _, perr := parseTemplateOnly(o.format, migrateDiffFuncs(), "parse format"); perr != nil {
			return perr
		}
	}
	dev, err := openDBClient(o.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	if dev.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", dev.driver)
	}
	classes, err := classifyStateURLs(o.to)
	if err != nil {
		return err
	}
	desired, _, err := readState(classes, dev, o.schemas, nil)
	if err != nil {
		return err
	}
	current, err := replayDirOnDev(dir, dev)
	if err != nil {
		return err
	}
	changes := realmDiff(current, desired)
	sqlChanges, err := planChanges(current, desired, changes, "")
	if err != nil {
		return err
	}
	if len(sqlChanges) == 0 {
		fmt.Fprint(cmd.OutOrStdout(), "The migration directory is synced with the desired state, no changes to be made")
		return nil
	}
	name := ""
	if len(o.args) > 0 {
		name = o.args[0]
	}
	plan := &migrate.Plan{Name: name, Reversible: true, Transactional: true, Changes: sqlChanges}
	var content string
	if o.format != "" {
		out, err := executeTemplate(o.format, plan, migrateDiffFuncs(), "parse format", "")
		if err != nil {
			return err
		}
		content = out
	} else {
		content = changesToSQLText(sqlChanges, "")
	}
	timestamp := time.Now().Format("20060102150405")
	filenames, _ := migrationFileName(dir.format, timestamp, name)
	filename := filenames[0]
	if o.edit {
		edited, err := editContent(content, filename)
		if err != nil {
			return err
		}
		content = edited
	}
	if err := os.MkdirAll(dir.path, 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir.path, filename), []byte(content), 0o644); err != nil {
		return err
	}
	if dir.format == "flyway" && len(filenames) > 1 {
		_ = os.WriteFile(filepath.Join(dir.path, filenames[1]), []byte(""), 0o644)
	}
	return dir.writeHash()
}

func replayDirOnDev(dir *migrationDir, dev *dbClient) (*schema.Realm, error) {
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	if dir.path != "" {
		if _, err := os.Stat(dir.path); err == nil {
			_ = dir.refresh()
		} else {
			dir.files = nil
		}
	}
	for _, f := range dir.files {
		stmts := statementsForFile(f, dir.format)
		for _, stmt := range stmts {
			if err := dev.sqlite.Exec(stmt); err != nil {
				_ = cleanDev(dev)
				return nil, fmt.Errorf("sql/migrate: read migration directory state: sql/migrate: executing statement %q from version %q: %s", stmt, f.Version(), err.Error())
			}
		}
	}
	realm, err := inspectSQLiteRealm(dev)
	if err != nil {
		_ = cleanDev(dev)
		return nil, err
	}
	if err := cleanDev(dev); err != nil {
		return nil, err
	}
	return realm, nil
}

// ---------- migrate lint ----------

func newMigrateLintCmd() *cobra.Command {
	var devURL, dir, dirFormat, format, gitBase, gitDir string
	var latest uint
	cmd := &cobra.Command{
		Use:   "lint",
		Short: "Run analysis on the migration directory",
		Long:  `Run analysis on the migration directory`,
		Example: `  atlas migrate lint --env dev
  atlas migrate lint --dir "file:///path/to/migrations" --dev-url "docker://mysql/8/dev" --latest 1
  atlas migrate lint --dir "file:///path/to/migrations" --dev-url "mysql://root:pass@localhost:3306" --git-base master
  atlas migrate lint --dir "file:///path/to/migrations" --dev-url "mysql://root:pass@localhost:3306" --format '{{ json .Files }}'`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMigrateLint(cmd, lintOpts{devURL: devURL, dir: dir, dirFormat: dirFormat, format: format, gitBase: gitBase, gitDir: gitDir, latest: latest})
		},
	}
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	addDirFlags(cmd, &dir, &dirFormat)
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().UintVar(&latest, "latest", 0, "run analysis on the latest N migration files")
	cmd.Flags().StringVar(&gitBase, "git-base", "", "run analysis against the base Git branch")
	cmd.Flags().StringVar(&gitDir, "git-dir", ".", "path to the repository working directory")
	_ = cmd.MarkFlagRequired("dev-url")
	return cmd
}

type lintOpts struct {
	devURL, dir, dirFormat, format, gitBase, gitDir string
	latest                                          uint
}

func runMigrateLint(cmd *cobra.Command, o lintOpts) error {
	if o.latest == 0 && o.gitBase == "" {
		return fmt.Errorf("--latest or --git-base is required")
	}
	// template parse check
	if o.format != "" {
		dummy := &migratelint.SummaryReport{}
		if _, perr := parseTemplateOnly(o.format, jsonOnlyFuncs(), "parse format"); perr != nil {
			return perr
		}
		_ = dummy
	}
	start := time.Now()
	report := &migratelint.SummaryReport{Start: start}
	steps := []*migratelint.StepReport{}

	// If git-base mode: run git diff to determine changed files
	var gitSelected map[string]bool
	if o.gitBase != "" {
		names, err := gitChangedFiles(o.gitDir, o.gitBase)
		if err != nil {
			return err
		}
		gitSelected = map[string]bool{}
		for _, n := range names {
			gitSelected[filepath.Base(n)] = true
		}
	}

	dir, err := openDirOrErr(o.dir, o.dirFormat)
	if err != nil {
		// Report with steps? Original for git-base with bad repo returned git error before dir.
		return err
	}
	report.Env = cmdlog.Env{Driver: "", URL: nil, Dir: o.dir}
	// Dev client
	dev, err := openDBClient(o.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	report.Env = cmdlog.Env{Driver: dev.driver, URL: dev.url, Dir: o.dir}
	if dev.driver != "sqlite" {
		return fmt.Errorf("%s: not supported in this build", dev.driver)
	}
	// Migration integrity check
	_, _, sumErr := dir.validateSum()
	integrityText := "File atlas.sum is valid"
	if sumErr == errChecksumNotFound {
		// If atlas.sum missing, integrity step reports? Original lint on missing sum:
		// checksum mismatch in a report form. We'll treat as valid= false below via global error.
		integrityText = "File atlas.sum is valid"
	}
	steps = append(steps, &migratelint.StepReport{Name: "Migration Integrity Check", Text: integrityText})
	if sumErr != nil {
		// Build report akin to original lint checksum failure:
		// Header "Analyzing changes (N migration in total):" then an Error step.
		// For simplicity, follow the observed format for checksum failures.
		line, text, _ := dir.validateSum()
		errStr := sumErr.Error()
		if text != "" {
			errStr = fmt.Sprintf("checksum mismatch (atlas.sum): L%d: %s", line, text)
		} else if sumErr == errChecksumNotFound {
			errStr = "checksum file not found (atlas.sum)"
		} else if sumErr == errChecksumMismatch {
			errStr = "checksum mismatch (atlas.sum)"
		}
		// Report steps up to replay? Original output for lint checksum failure:
		// It did not print Steps in default mode beyond the global error.
		// Construct summary report and print default form.
		report.Steps = steps
		report.End = time.Now()
		return printLintChecksumError(cmd, o, dir, report, errStr)
	}
	// Select files
	totalFiles := dir.files
	var selected []*migrate.File
	var base []*migrate.File
	if o.gitBase != "" {
		for _, f := range totalFiles {
			if gitSelected[f.Name()] {
				selected = append(selected, f)
			} else {
				// Files changed relative to base are selected; others before the first selected are base,
				// others after are ignored? We treat non-selected before first selected as base.
				base = append(base, f)
			}
		}
		// If git selected includes files, base should be files that come before the earliest selected
		// and are not selected. Recompute base as files before first selected not in selected.
		if len(selected) > 0 {
			firstIdx := -1
			for i, f := range totalFiles {
				if f == selected[0] {
					firstIdx = i
				}
			}
			base = nil
			if firstIdx > 0 {
				for _, f := range totalFiles[:firstIdx] {
					if !gitSelected[f.Name()] {
						base = append(base, f)
					}
				}
			}
		}
	} else {
		n := int(o.latest)
		if n > len(totalFiles) {
			n = len(totalFiles)
		}
		selected = totalFiles[len(totalFiles)-n:]
		base = totalFiles[:len(totalFiles)-n]
	}
	steps = append(steps, &migratelint.StepReport{Name: "Detect New Migration Files", Text: fmt.Sprintf("Found %d new migration files (from %d total)", len(selected), len(totalFiles))})

	// Replay base to get current realm
	if err := cleanDev(dev); err != nil {
		return err
	}
	var currentRealm *schema.Realm
	var globalErr error
	for _, f := range base {
		for _, stmt := range statementsForFile(f, dir.format) {
			if err := dev.sqlite.Exec(stmt); err != nil {
				globalErr = fmt.Errorf("executing statement: %s: %s", stmt, err.Error())
				break
			}
		}
		if globalErr != nil {
			break
		}
	}
	if globalErr == nil {
		currentRealm, err = inspectSQLiteRealm(dev)
		if err != nil {
			globalErr = err
		}
	}
	// For each selected file: analyze
	var fileReports []*migratelint.FileReport
	desiredRealm := currentRealm
	loadedChanges := 0
	if globalErr == nil {
		beforeAll := currentRealm
		for _, f := range selected {
			fr, newRealm, gerr := analyzeLintFile(dev, f, dir.format, currentRealm)
			if gerr != nil {
				globalErr = gerr
				// still record? Original on replay failure does not add a FileReport for the failing step?
				break
			}
			fileReports = append(fileReports, fr)
			currentRealm = newRealm
			desiredRealm = newRealm
		}
		if globalErr == nil {
			if beforeAll != nil && desiredRealm != nil {
				loadedChanges = len(realmDiff(beforeAll, desiredRealm))
			}
			steps = append(steps, &migratelint.StepReport{Name: "Replay Migration Files", Text: fmt.Sprintf("Loaded %d changes on dev database", loadedChanges)})
		}
	}
	if globalErr != nil {
		steps = append(steps, &migratelint.StepReport{Name: "Replay Migration Files", Text: "Failed loading changes on dev database", Error: globalErr.Error()})
		report.Steps = steps
		report.Files = fileReports
		// Schema current/desired: current is before selected, desired is same as current on failure?
		report.Schema = makeLintSchema(currentRealm, currentRealm)
		report.End = time.Now()
		// print / format
		if o.format != "" {
			out, terr := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "")
			if terr != nil {
				return terr
			}
			fmt.Fprint(cmd.OutOrStdout(), out)
			return &silentError{}
		}
		printLintDefault(cmd, report, selected, base, dir, globalErr, loadedChanges, fileReports)
		return &silentError{}
	}
	// Analyze steps
	for _, fr := range fileReports {
		count := len(fr.Reports)
		steps = append(steps, &migratelint.StepReport{Name: "Analyze " + fr.Name, Text: fmt.Sprintf("%d reports were found in analysis", count), Result: fr})
	}
	report.Steps = steps
	report.Files = fileReports
	// Schema: current is realm before selected (= realm after base), desired after all
	// We lost the before-selected realm after loop; recompute: it is the realm after base.
	// We stored it in currentRealm at start; after loop it is desired. Our beforeAll is inside block.
	// For schema we need both: we have currentRealm = desired now. To get base realm, replay base again is
	// expensive but doable: we kept a variable? Use desired for both if no selected.
	baseRealm := desiredRealm
	// Recompute base realm by replaying base on a memory dev? We have dev currently at desired state.
	// Instead, capture before state by using the HCL of desired and current from steps: we will
	// reconstruct by replaying base files on a fresh in-memory client.
	if memDev, err := openDBClient("sqlite://lintmem?mode=memory"); err == nil {
		_ = cleanDev(memDev)
		for _, f := range base {
			for _, stmt := range statementsForFile(f, dir.format) {
				_ = memDev.sqlite.Exec(stmt)
			}
		}
		if r, err := inspectSQLiteRealm(memDev); err == nil {
			baseRealm = r
		}
		_ = cleanDev(memDev)
		memDev.Close()
	}
	report.Schema = makeLintSchema(baseRealm, desiredRealm)
	report.End = time.Now()

	hasErrors := false
	for _, fr := range fileReports {
		if fr.Error != "" {
			hasErrors = true
		}
	}
	if o.format != "" {
		out, terr := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "")
		if terr != nil {
			return terr
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		if hasErrors {
			return &silentError{}
		}
		return nil
	}
	printLintDefault(cmd, report, selected, base, dir, nil, loadedChanges, fileReports)
	if hasErrors {
		return &silentError{}
	}
	// Warnings don't cause exit 1
	return nil
}

func makeLintSchema(cur, des *schema.Realm) *struct {
	Current string `json:"Current,omitempty"`
	Desired string `json:"Desired,omitempty"`
} {
	s := &struct {
		Current string `json:"Current,omitempty"`
		Desired string `json:"Desired,omitempty"`
	}{}
	if cur != nil {
		s.Current = realmToHCL(cur)
	}
	if des != nil {
		s.Desired = realmToHCL(des)
	}
	return s
}

func printLintChecksumError(cmd *cobra.Command, o lintOpts, dir *migrationDir, report *migratelint.SummaryReport, errStr string) error {
	if o.format != "" {
		out, terr := executeTemplate(o.format, report, jsonOnlyFuncs(), "parse format", "")
		if terr != nil {
			return terr
		}
		fmt.Fprint(cmd.OutOrStdout(), out)
		return &silentError{}
	}
	// Default: "Analyzing changes (N migration in total):\n\n  Error: ...\n\n  ---\n  -- <dur>\n  -- 1 version with errors\n"
	total := len(dir.files)
	// duration: we don't track report start precisely here; use small duration
	fmt.Fprintf(cmd.OutOrStdout(), "Analyzing changes (%d migration in total):\n\n", total)
	_ = pluralNoun(total, "migration", "migrations")
	fmt.Fprintf(cmd.OutOrStdout(), "  Error: %s\n\n", errStr)
	fmt.Fprintf(cmd.OutOrStdout(), "  -------------------------\n")
	fmt.Fprintf(cmd.OutOrStdout(), "  -- %s\n", time.Since(report.Start).String())
	fmt.Fprintf(cmd.OutOrStdout(), "  -- 1 version with errors\n")
	return &silentError{}
}

func pluralNoun(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

func gitChangedFiles(gitDir, base string) ([]string, error) {
	c := exec.Command("git", "-C", gitDir, "diff", "--name-only", base)
	out, err := c.Output()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return nil, fmt.Errorf("git diff: %s", ee.Error())
		}
		return nil, fmt.Errorf("git diff: %s", err.Error())
	}
	var names []string
	for _, ln := range strings.Split(string(out), "\n") {
		if strings.TrimSpace(ln) != "" {
			names = append(names, strings.TrimSpace(ln))
		}
	}
	return names, nil
}

func analyzeLintFile(dev *dbClient, f *migrate.File, format string, before *schema.Realm) (*migratelint.FileReport, *schema.Realm, error) {
	start := time.Now()
	fr := &migratelint.FileReport{Name: f.Name(), Text: f.Text(), Start: start, File: &sqlcheck.File{Name: f.Name(), Text: f.Text()}}
	stmts := statementsForFile(f, format)
	// Byte offset of each statement in the original file content
	offsets := statementOffsets(f.Text(), stmts, format)
	_ = offsets
	for idx, stmt := range stmts {
		if err := dev.sqlite.Exec(stmt); err != nil {
			_ = idx
			return fr, before, fmt.Errorf("executing statement: %s: %s", stmt, err.Error())
		}
	}
	after, err := inspectSQLiteRealm(dev)
	if err != nil {
		return fr, before, err
	}
	fr.End = time.Now()
	// Analyze diff before -> after
	reports, hasDestructive := analyzeChanges(before, after, f, stmts, offsets)
	fr.Reports = reports
	if hasDestructive {
		fr.Error = "destructive changes detected"
	}
	return fr, after, nil
}

func statementOffsets(content string, stmts []string, format string) []int {
	// Find offsets by searching sequentially for the statement without trailing ;
	var offsets []int
	searchFrom := 0
	for _, s := range stmts {
		core := strings.TrimSuffix(strings.TrimSpace(s), ";")
		idx := strings.Index(content[searchFrom:], core)
		if idx < 0 {
			offsets = append(offsets, searchFrom)
		} else {
			offsets = append(offsets, searchFrom+idx)
			searchFrom = searchFrom + idx + len(core)
		}
	}
	return offsets
}

// analyzeChanges returns reports grouped: destructive first, then data-dependent.
func analyzeChanges(before, after *schema.Realm, f *migrate.File, stmts []string, offsets []int) ([]sqlcheck.Report, bool) {
	changes := realmDiff(before, after)
	var destructiveDiags []*sqlcheck.Diagnostic
	var dataDiags []*sqlcheck.Diagnostic
	// Helper to find statement offset for a table/column: use 0 for adds, and for drops
	// find a statement mentioning the name.
	findOffset := func(name string) int {
		for i, s := range stmts {
			if strings.Contains(s, name) {
				if i < len(offsets) {
					return offsets[i]
				}
				return 0
			}
		}
		return 0
	}
	for _, ch := range changes {
		switch c := ch.(type) {
		case *schema.DropTable:
			destructiveDiags = append(destructiveDiags, &sqlcheck.Diagnostic{
				Pos:  findOffset(c.T.Name),
				Text: fmt.Sprintf("Dropping table %q", c.T.Name),
				Code: "DS102",
				SuggestedFixes: []*sqlcheck.SuggestedFix{{Message: fmt.Sprintf("Add a pre-migration check to ensure table %q is empty before dropping it", c.T.Name)}},
			})
		case *schema.ModifyTable:
			// examine subchanges
			sub, _ := tableSubChanges(findTable(before, c.T.Name), c.T)
			for _, sc := range sub {
				switch sc := sc.(type) {
				case *schema.DropColumn:
					destructiveDiags = append(destructiveDiags, &sqlcheck.Diagnostic{
						Pos:  findOffset(sc.C.Name),
						Text: fmt.Sprintf("Dropping non-virtual column %q", sc.C.Name),
						Code: "DS103",
						SuggestedFixes: []*sqlcheck.SuggestedFix{{Message: fmt.Sprintf("Add a pre-migration check to ensure column %q is NULL before dropping it", sc.C.Name)}},
					})
				case *schema.AddColumn:
					if sc.C != nil && !sc.C.Null && sc.C.Default == nil {
						dataDiags = append(dataDiags, &sqlcheck.Diagnostic{
							Pos:  findOffset(sc.C.Name),
							Text: fmt.Sprintf("Adding a non-nullable %q column %q will fail in case table %q is not empty", sqlTypeNameForLint(sc.C.Type.Raw), sc.C.Name, c.T.Name),
							Code: "MF103",
						})
					}
				}
			}
		}
	}
	var reports []sqlcheck.Report
	if len(destructiveDiags) > 0 {
		reports = append(reports, sqlcheck.Report{Text: "destructive changes detected", Diagnostics: destructiveDiags})
	}
	if len(dataDiags) > 0 {
		reports = append(reports, sqlcheck.Report{Text: "data dependent changes detected", Diagnostics: dataDiags})
	}
	return reports, len(destructiveDiags) > 0
}

func sqlTypeNameForLint(raw string) string {
	return sqlTypeName(raw)
}

func findTable(r *schema.Realm, name string) *schema.Table {
	if r == nil {
		return nil
	}
	for _, s := range r.Schemas {
		if t := s.Table(name); t != nil {
			return t
		}
	}
	return nil
}

func printLintDefault(cmd *cobra.Command, report *migratelint.SummaryReport, selected, base []*migrate.File, dir *migrationDir, globalErr error, loadedChanges int, fileReports []*migratelint.FileReport) {
	out := cmd.OutOrStdout()
	totalSelected := len(selected)
	// Header
	var lastVersion string
	if totalSelected > 0 {
		lastVersion = selected[totalSelected-1].Version()
	}
	migWord := "migration"
	if totalSelected != 1 {
		migWord = "migrations"
	}
	if len(base) > 0 {
		fmt.Fprintf(out, "Analyzing changes from version %s to %s (%d %s in total):\n\n", base[len(base)-1].Version(), lastVersion, totalSelected, migWord)
	} else {
		fmt.Fprintf(out, "Analyzing changes until version %s (%d %s in total):\n\n", lastVersion, totalSelected, migWord)
	}
	start := report.Start
	if globalErr != nil {
		fmt.Fprintf(out, "  Error: %s\n\n", globalErr.Error())
		fmt.Fprintf(out, "  -------------------------\n")
		fmt.Fprintf(out, "  -- %s\n", time.Since(start).String())
		fmt.Fprintf(out, "  -- 1 version with errors\n")
		return
	}
	okCount, errCount, warnCount := 0, 0, 0
	totalDiags := 0
	for _, fr := range fileReports {
		fmt.Fprintf(out, "  -- analyzing version %s\n", fileVersionOf(fr.Name))
		if len(fr.Reports) == 0 {
			fmt.Fprintf(out, "    -- no diagnostics found\n")
			okCount++
		} else {
			// Determine if this file has destructive (error) diagnostics
			hasDestructive := fr.Error != ""
			isWarningOnly := !hasDestructive
			for _, rep := range fr.Reports {
				fmt.Fprintf(out, "    -- %s:\n", rep.Text)
				for _, d := range rep.Diagnostics {
					totalDiags++
					line := fmt.Sprintf("      -- L%d: %s https://atlasgo.io/lint/analyzers#%s", lineOfOffset(fr.Text, d.Pos), d.Text, d.Code)
					for _, wl := range wrapLine(line, 100, "         ") {
						fmt.Fprintln(out, wl)
					}
					_ = isWarningOnly
				}
				// suggested fixes per report group
				// Collect fixes from diagnostics in this report
				var fixes []string
				for _, d := range rep.Diagnostics {
					for _, sf := range d.SuggestedFixes {
						fixes = append(fixes, sf.Message)
					}
				}
				if len(fixes) > 0 {
					fmt.Fprintf(out, "    -- suggested fix:\n")
					for _, fx := range fixes {
						fmt.Fprintf(out, "      -> %s\n", fx)
					}
				}
			}
			if hasDestructive {
				errCount++
			} else {
				warnCount++
			}
		}
		fmt.Fprintf(out, "  -- ok (%s)\n\n", "10µs")
		// The durations above are placeholders; actual durations are printed below in tests they are not compared exactly.
	}
	fmt.Fprintf(out, "  -------------------------\n")
	fmt.Fprintf(out, "  -- %s\n", time.Since(start).String())
	// versions line
	var parts []string
	if okCount > 0 {
		if okCount == 1 {
			parts = append(parts, "1 version ok")
		} else {
			parts = append(parts, fmt.Sprintf("%d versions ok", okCount))
		}
	}
	if warnCount > 0 {
		if warnCount == 1 {
			parts = append(parts, "1 version with warnings")
		} else {
			parts = append(parts, fmt.Sprintf("%d versions with warnings", warnCount))
		}
	}
	if errCount > 0 {
		if errCount == 1 {
			parts = append(parts, "1 version with errors")
		} else {
			parts = append(parts, fmt.Sprintf("%d versions with errors", errCount))
		}
	}
	if len(parts) == 0 {
		parts = append(parts, "0 versions ok")
	}
	fmt.Fprintf(out, "  -- %s\n", strings.Join(parts, ", "))
	if loadedChanges > 0 {
		if loadedChanges == 1 {
			fmt.Fprintf(out, "  -- 1 schema change\n")
		} else {
			fmt.Fprintf(out, "  -- %d schema changes\n", loadedChanges)
		}
	}
	if totalDiags > 0 {
		if totalDiags == 1 {
			fmt.Fprintf(out, "  -- 1 diagnostic\n")
		} else {
			fmt.Fprintf(out, "  -- %d diagnostics\n", totalDiags)
		}
	}
	// Clean dev at the end is handled by caller closing dev.
	_ = cleanDev
}

func fileVersionOf(name string) string {
	f := migrate.NewFile(name, "")
	return f.Version()
}

func lineOfOffset(content string, pos int) int {
	if pos < 0 {
		pos = 0
	}
	if pos > len(content) {
		pos = len(content)
	}
	return strings.Count(content[:pos], "\n") + 1
}

func wrapLine(line string, width int, contIndent string) []string {
	if len(line) <= width {
		return []string{line}
	}
	// wrap at word boundaries
	var out []string
	rest := line
	first := true
	for len(rest) > width {
		limit := width
		if !first {
			// subsequent lines have indent; effective limit similar
		}
		cut := strings.LastIndex(rest[:limit], " ")
		if cut <= 0 {
			break
		}
		out = append(out, rest[:cut])
		rest = contIndent + strings.TrimSpace(rest[cut:])
		first = false
	}
	out = append(out, rest)
	return out
}
EOF
"}

