package main

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"
)

func newHelpCommand(root *cobra.Command) *cobra.Command {
	helpCmd := &cobra.Command{
		Use:   "help [command]",
		Short: "Help about any command",
		Long: `Help provides help for any command in the application.
Simply type atlas help [path to command] for full details.`,
		Args: cobra.ArbitraryArgs,
		Run: func(cmd *cobra.Command, args []string) {
			out := cmd.OutOrStdout()
			if len(args) == 0 {
				_ = root.Help()
				return
			}
			// Find deepest matching command
			cur := root
			matched := 0
			for _, a := range args {
				var next *cobra.Command
				for _, sub := range cur.Commands() {
					if sub.Name() == a {
						next = sub
						break
					}
					for _, al := range sub.Aliases {
						if al == a {
							next = sub
							break
						}
					}
					if next != nil {
						break
					}
				}
				if next == nil {
					break
				}
				cur = next
				matched++
			}
			if matched == 0 {
				// Unknown help topic
				var parts []string
				for _, a := range args {
					parts = append(parts, "`"+a+"`")
				}
				fmt.Fprintf(out, "Unknown help topic [%s]\n", strings.Join(parts, " "))
				fmt.Fprint(out, rootUsageWithoutFlags(root))
				return
			}
			_ = cur.Help()
		},
	}
	return helpCmd
}

func rootUsageWithoutFlags(root *cobra.Command) string {
	var sb strings.Builder
	sb.WriteString("Usage:\n  atlas [command]\n\n")
	sb.WriteString("Available Commands:\n")
	cmds := root.Commands()
	// Cobra sorts commands by name when EnableCommandSorting is true
	// Compute name padding like cobra (longest command name)
	maxLen := 0
	for _, c := range cmds {
		if !c.IsAvailableCommand() {
			continue
		}
		if len(c.Name()) > maxLen {
			maxLen = len(c.Name())
		}
	}
	// NamePadding in cobra is at least based on the longest name; padding uses
	// rpad(name, NamePadding) where NamePadding returns the longest length.
	for _, c := range cmds {
		if !c.IsAvailableCommand() {
			continue
		}
		name := c.Name()
		pad := strings.Repeat(" ", maxLen-len(name))
		sb.WriteString(fmt.Sprintf("  %s%s  %s\n", name, pad, c.Short))
	}
	sb.WriteString("\nUse \"atlas [command] --help\" for more information about a command.\n")
	return sb.String()
}
EOF
