	sb.WriteString("Usage:\n  atlas [command]\n\n")
	sb.WriteString("Available Commands:\n")
	cmds := root.Commands()
	// Cobra sorts commands by name when EnableCommandSorting is true
	// Compute name padding like cobra (longest command name)
	maxLen := 0
	for _, c := range cmds {
		if !c.IsAvailableCommand() {
			continue
		}
		if len(c.Name()) > maxLen {
			maxLen = len(c.Name())
		}
	}
	// NamePadding in cobra is at least based on the longest name; padding uses
	// rpad(name, NamePadding) where NamePadding returns the longest length.
	for _, c := range cmds {
		if !c.IsAvailableCommand() {
			continue
		}
		name := c.Name()
		pad := strings.Repeat(" ", maxLen-len(name))
		sb.WriteString(fmt.Sprintf("  %s%s  %s\n", name, pad, c.Short))
	}
	sb.WriteString("\nUse \"atlas [command] --help\" for more information about a command.\n")
	return sb.String()
}
