// cleanSQLStatement removes SQL comments from a statement (outside strings)
// and trims surrounding whitespace.
func cleanSQLStatement(stmt string) string {
	var b strings.Builder
	i := 0
	for i < len(stmt) {
		c := stmt[i]
		if c == '\'' || c == '"' || c == '`' {
			// copy quoted verbatim
			b.WriteByte(c)
			i++
			for i < len(stmt) {
				b.WriteByte(stmt[i])
				if stmt[i] == c {
					if i+1 < len(stmt) && stmt[i+1] == c {
						b.WriteByte(stmt[i+1])
						i += 2
						continue
					}
					i++
					break
				}
				i++
			}
			continue
		}
		if c == '[' {
			for i < len(stmt) {
				b.WriteByte(stmt[i])
				if stmt[i] == ']' {
					i++
					break
				}
				i++
			}
			continue
		}
		if c == '-' && i+1 < len(stmt) && stmt[i+1] == '-' {
			for i < len(stmt) && stmt[i] != '\n' {
				i++
			}
			continue
		}
		if c == '/' && i+1 < len(stmt) && stmt[i+1] == '*' {
			i += 2
			for i+1 < len(stmt) && !(stmt[i] == '*' && stmt[i+1] == '/') {
				i++
			}
			if i+1 < len(stmt) {
				i += 2
			}
			b.WriteByte(' ')
