package main

import (
	"fmt"
	"strings"
)

type sqlScanError struct {
	msg string
}

func (e *sqlScanError) Error() string { return e.msg }

// scanSQLStatements splits content into raw statements and validates
// quotes / parentheses. filename is used for error messages (basename).
func scanSQLStatements(content, filename string) ([]string, error) {
	var stmts []string
	n := len(content)
	i := 0
	line, col := 1, 1
	advance := func() {
		if i < n {
			if content[i] == '\n' {
				line++
				col = 1
			} else {
				col++
			}
			i++
		}
	}
	// helpers to peek
	type parenPos struct{ line, col int }
	var parens []parenPos
	var quote byte
	var quoteLine, quoteCol int
	isTrigger := false
	triggerDepth := 0
	triggerStarted := false
	// statement start index (byte offset) and whether we're in a statement
	stmtStart := -1
	// current word accumulation for keyword detection
	var word strings.Builder
	var words []string
	flushWord := func() {
		if word.Len() > 0 {
			words = append(words, strings.ToUpper(word.String()))
			word.Reset()
		}
	}
	checkTriggerStart := func() {
		// words collected so far (upper)
		if len(words) >= 2 {
			idx := 0
			if words[0] == "CREATE" {
				idx = 1
				if idx < len(words) && (words[idx] == "TEMP" || words[idx] == "TEMPORARY") {
					idx++
				}
				if idx < len(words) && words[idx] == "TRIGGER" {
					isTrigger = true
				}
			}
		}
	}
	for i < n {
		c := content[i]
		if quote != 0 {
			if c == quote {
				// '' escape for single quote
				if quote == '\'' && i+1 < n && content[i+1] == '\'' {
					advance()
					advance()
					continue
				}
				quote = 0
				advance()
				continue
			}
			advance()
			continue
		}
