package main

import (
	"fmt"
	"strings"

	"atlas/migrate"
)

func isFKPragma(cmd string) bool {
	c := strings.ToLower(strings.TrimSpace(cmd))
	return strings.HasPrefix(c, "pragma foreign_keys")
}

func executeSQLChanges(c *dbClient, changes []*migrate.Change, txMode string) error {
	if c == nil || c.sqlite == nil {
		if c != nil && c.deferredErr != nil {
			return sqliteErrPrefix(c.deferredErr)
		}
		return nil
	}
	useTx := txMode != "none"
	inTx := false
	commit := func() error {
		if inTx {
			if err := c.sqlite.Exec("COMMIT"); err != nil {
				return err
			}
			inTx = false
		}
		return nil
	}
	for _, ch := range changes {
		if useTx && isFKPragma(ch.Cmd) {
			if err := commit(); err != nil {
				return err
			}
			if err := c.sqlite.Exec(ch.Cmd); err != nil {
				if ch.Comment != "" {
					return fmt.Errorf("%s: %s", ch.Comment, err.Error())
				}
				return err
			}
			continue
		}
		if useTx && !inTx {
			if err := c.sqlite.Exec("BEGIN"); err != nil {
				return err
			}
			inTx = true
		}
		if err := c.sqlite.Exec(ch.Cmd); err != nil {
			if inTx {
				_ = c.sqlite.Exec("ROLLBACK")
				inTx = false
			}
			if ch.Comment != "" {
				return fmt.Errorf("%s: %s", ch.Comment, err.Error())
			}
			return err
		}
	}
	return commit()
}
